export const adminMachine = setup({
  types: {
    context: {} as AdminContext,
    events: {} as AdminEvent,
  },
  actors: {
    deleteRoom: deleteRoomLogic,
  },
  guards: {
    isAdmin: () => {
      return getIsAdmin()
    },
    isRoomCreator: () => {
      const user = getCurrentUser()
      const room = getCurrentRoom()
      return !!user && !!room && user.userId === room.creator
    },
  },
  actions: {
    deputizeDj: ({ event }) => {
      if (event.type !== "DEPUTIZE_DJ") return
      emitToSocket("DEPUTIZE_DJ", event.userId)
    },
    designateAdmin: ({ event }) => {
      if (event.type !== "DESIGNATE_ADMIN") return
      emitToSocket("DESIGNATE_ADMIN", event.userId)
    },
    togglePersona: ({ event }) => {
      if (event.type !== "TOGGLE_PERSONA") return
      emitToSocket("TOGGLE_PERSONA", { userId: event.userId, personaId: event.personaId })
    },
    setSettings: ({ event }) => {
      if (event.type !== "SET_SETTINGS") return
      emitToSocket("SET_ROOM_SETTINGS", event.data)
    },
    activateSegment: ({ event }) => {
      if (event.type !== "ACTIVATE_SEGMENT") return
      emitToSocket("SET_ACTIVE_SEGMENT", event.data)
    },
    injectSegmentTracks: ({ event }) => {
      if (event.type !== "INJECT_SEGMENT_TRACKS") return
      emitToSocket("INJECT_SEGMENT_TRACKS", event.data)
    },
    clearPlaylist: () => {
      emitToSocket("CLEAR_PLAYLIST", {})
    },
    notify: () => {
      toast({
        title: "Settings updated",
        status: "success",
        duration: 3000,
      })
    },
    onDeleteSuccess: () => {
      toast({
        title: "Room deleted",
        description: "Your room has been deleted",
        status: "success",
      })
      window.location.href = "/"
    },
    onDeleteError: () => {
      toast({
        title: "Error deleting room",
        description: "There was an error deleting your room",
        status: "error",
      })
    },
  },
}).createMachine({
  id: "admin",
  initial: "idle",
  context: {},
  states: {
    // Idle state - not activated for room
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    // Active state — emits admin actions only (no SERVER_EVENT handlers / socket sub)
    active: {
      on: {
        DEACTIVATE: {
          target: "idle",
        },
        SET_SETTINGS: { actions: ["setSettings", "notify"], guard: "isAdmin" },
        ACTIVATE_SEGMENT: { actions: ["activateSegment"], guard: "isAdmin" },
        INJECT_SEGMENT_TRACKS: { actions: ["injectSegmentTracks"], guard: "isAdmin" },
        CLEAR_PLAYLIST: { actions: ["clearPlaylist"], guard: "isAdmin" },
        DELETE_ROOM: { target: ".deleting", guard: "isRoomCreator" },
        DEPUTIZE_DJ: { actions: ["deputizeDj"], guard: "isAdmin" },
        DESIGNATE_ADMIN: { actions: ["designateAdmin"], guard: "isRoomCreator" },
        TOGGLE_PERSONA: { actions: ["togglePersona"], guard: "isAdmin" },
      },
      initial: "ready",
      states: {
        ready: {},
        deleting: {
          invoke: {
            id: "deleteRoom",
            src: "deleteRoom",
            input: ({ event }) => {
              if (event.type === "DELETE_ROOM") {
                return { id: event.data.id }
              }
              return { id: "" }
            },
            onDone: {
              target: "ready",
              actions: ["onDeleteSuccess"],
            },
            onError: {
              target: "ready",
              actions: ["onDeleteError"],
            },
          },
        },
      },
    },
  },
})

export const addToQueueUiMachine = setup({
  types: {
    context: {} as AddToQueueUiMachineContext,
    events: {} as AddToQueueUiEvent,
  },
  actions: {
    persistUi: ({ context }) => {
      saveAddToQueueUi(context.roomId, persistedSlice(context))
    },
    activateRoom: assign(({ event }) => {
      if (event.type !== "ACTIVATE") return {}
      const stored = loadAddToQueueUi(event.roomId)
      return {
        roomId: event.roomId,
        mode: stored?.mode ?? "search",
        sourceFilter: stored?.sourceFilter ?? "all",
        browse: stored?.browse,
        pendingNavigation: null,
        ignoreBrowseLocation: false,
        restoreAttempted: false,
        canBrowse: false,
        browseableSourceIds: [] as string[],
        metadataSourceIds: [] as string[],
      }
    }),
    deactivateRoom: assign(() => emptyContext()),
    setCapabilities: assign(({ context, event }) => {
      if (event.type !== "SET_CAPABILITIES") return {}
      const { canBrowse, browseableSourceIds, metadataSourceIds } = event
      let mode = context.mode
      if (!canBrowse && mode === "browse") mode = "search"

      const sourceFilter = clampSourceFilter(
        mode,
        context.sourceFilter,
        browseableSourceIds,
        metadataSourceIds,
      )

      const becameBrowsable = canBrowse && !context.canBrowse
      const shouldRestore =
        canBrowse &&
        Boolean(context.browse) &&
        !context.pendingNavigation &&
        (!context.restoreAttempted || becameBrowsable)

      return {
        canBrowse,
        browseableSourceIds,
        metadataSourceIds,
        mode,
        sourceFilter,
        restoreAttempted: context.restoreAttempted || canBrowse || browseableSourceIds.length === 0,
        ...(shouldRestore && context.browse
          ? {
              pendingNavigation: browseLocationToNavigation(context.browse),
              ignoreBrowseLocation: true,
            }
          : {}),
      }
    }),
    deepLinkMedia: assign(({ context, event }) => {
      if (event.type !== "DEEP_LINK_MEDIA") return {}
      if (!context.browseableSourceIds.includes("local")) return {}
      return {
        mode: "browse" as const,
        sourceFilter: "local",
        pendingNavigation: {
          source: "local",
          mediaKey: event.mediaKey,
          rootKind: "media" as const,
        },
        ignoreBrowseLocation: true,
        restoreAttempted: true,
      }
    }),
    setMode: assign(({ context, event }) => {
      if (event.type !== "SET_MODE") return {}
      let mode = event.mode
      if (mode === "browse" && !context.canBrowse) mode = "search"
      const sourceFilter = clampSourceFilter(
        mode,
        context.sourceFilter,
        context.browseableSourceIds,
        context.metadataSourceIds,
      )
      return { mode, sourceFilter }
    }),
    setSource: assign(({ context, event }) => {
      if (event.type !== "SET_SOURCE") return {}
      return {
        sourceFilter: clampSourceFilter(
          context.mode,
          event.sourceFilter,
          context.browseableSourceIds,
          context.metadataSourceIds,
        ),
      }
    }),
    openBrowse: assign(({ event }) => {
      if (event.type !== "OPEN_BROWSE") return {}
      return {
        mode: "browse" as const,
        sourceFilter: event.nav.source,
        pendingNavigation: event.nav,
        ignoreBrowseLocation: true,
      }
    }),
    clearPendingNavigation: assign({
      pendingNavigation: null,
      ignoreBrowseLocation: false,
    }),
    setBrowseLocation: assign(({ context, event }) => {
      if (event.type !== "BROWSE_LOCATION") return {}
      if (context.ignoreBrowseLocation) return {}
      return { browse: event.location }
    }),
    restoreBrowseView: assign(({ context }) => {
      if (context.mode !== "browse" || !context.canBrowse || !context.browse) return {}
      // Already queued (e.g. SET_CAPABILITIES + modal open in the same tick).
      if (context.pendingNavigation) return { ignoreBrowseLocation: true }
      return {
        pendingNavigation: browseLocationToNavigation(context.browse),
        ignoreBrowseLocation: true,
      }
    }),
  },
}).createMachine({
  id: "addToQueueUi",
  context: emptyContext(),
  initial: "inactive",
  states: {
    inactive: {
      on: {
        ACTIVATE: {
          target: "active",
          actions: "activateRoom",
        },
      },
    },
    active: {
      on: {
        ACTIVATE: {
          actions: "activateRoom",
        },
        DEACTIVATE: {
          target: "inactive",
          actions: "deactivateRoom",
        },
        SET_CAPABILITIES: {
          actions: ["setCapabilities", "persistUi"],
        },
        DEEP_LINK_MEDIA: {
          actions: ["deepLinkMedia", "persistUi"],
        },
        SET_MODE: {
          actions: ["setMode", "persistUi"],
        },
        SET_SOURCE: {
          actions: ["setSource", "persistUi"],
        },
        OPEN_BROWSE: {
          actions: ["openBrowse", "persistUi"],
        },
        NAVIGATION_APPLIED: {
          actions: "clearPendingNavigation",
        },
        BROWSE_LOCATION: {
          actions: ["setBrowseLocation", "persistUi"],
        },
        RESTORE_BROWSE_VIEW: {
          actions: "restoreBrowseView",
        },
      },
    },
  },
})

const addToLibraryMachine = setup({
  types: {
    context: {} as Context,
    events: {} as Event,
  },
  actions: {
    sendCheckRequest: ({ context }) => {
      emitToSocket("CHECK_SAVED_TRACKS", {
        trackIds: context.ids,
        targetService: context.targetService,
      })
    },
    sendAddRequest: ({ context, event }) => {
      const data = event.type === "ADD" ? event.data ?? context.ids : context.ids
      const targetService =
        event.type === "ADD" ? event.targetService ?? context.targetService : context.targetService
      emitToSocket("ADD_TO_LIBRARY", { trackIds: data, targetService })
    },
    sendRemoveRequest: ({ context, event }) => {
      const data = event.type === "REMOVE" ? event.data ?? context.ids : context.ids
      const targetService =
        event.type === "REMOVE"
          ? event.targetService ?? context.targetService
          : context.targetService
      emitToSocket("REMOVE_FROM_LIBRARY", { trackIds: data, targetService })
    },
    setCheckedTracks: assign(({ context, event }) => {
      if (event.type === "CHECK_SAVED_TRACKS_RESULTS") {
        return {
          tracks: event.data.trackIds.reduce(
            (acc, id, index) => {
              acc[id] = event.data.results[index]
              return acc
            },
            { ...context.tracks },
          ),
        }
      }
      return {}
    }),
    setIds: assign(({ context, event }) => {
      if (event.type === "SET_IDS") {
        return {
          ids: event.data ?? context.ids,
          targetService: event.targetService ?? context.targetService,
        }
      }
      return {}
    }),
    showAddSuccess: () => {
      toast({
        title: "Added to your library",
        status: "success",
      })
    },
    showRemoveSuccess: () => {
      toast({
        title: "Removed from your library",
        status: "success",
      })
    },
    showError: ({ event }) => {
      if (
        event.type === "CHECK_SAVED_TRACKS_FAILURE" ||
        event.type === "ADD_TO_LIBRARY_FAILURE" ||
        event.type === "REMOVE_FROM_LIBRARY_FAILURE"
      ) {
        toast({
          title: "Error",
          description: event.data.message,
          status: "error",
        })
      }
    },
  },
  guards: {
    canFetch: ({ context }) => {
      return context.ids && context.ids.length > 0
    },
    cannotFetch: ({ context }) => {
      return !context.ids || context.ids.length === 0
    },
  },
}).createMachine({
  id: "addToLibrary",
  initial: "initial",
  context: {
    ids: [],
    tracks: {},
    targetService: undefined,
  },
  on: {
    SET_IDS: {
      actions: ["setIds"],
      target: ".loading.checking",
    },
    CHECK_SAVED_TRACKS_RESULTS: {
      target: ".checked",
      actions: ["setCheckedTracks"],
    },
    CHECK_SAVED_TRACKS_FAILURE: {
      target: ".error",
      // NOTE: Don't show error toast for unsupported services (graceful handling)
      // actions: ["showError"],
    },
    ADD_TO_LIBRARY_SUCCESS: {
      target: ".loading.checking",
      actions: ["showAddSuccess"],
    },
    ADD_TO_LIBRARY_FAILURE: {
      target: ".error",
      actions: ["showError"],
    },
    REMOVE_FROM_LIBRARY_SUCCESS: {
      target: ".loading.checking",
      actions: ["showRemoveSuccess"],
    },
    REMOVE_FROM_LIBRARY_FAILURE: {
      target: ".error",
      actions: ["showError"],
    },
  },
  states: {
    initial: {
      always: [
        { target: "loading.checking", guard: "canFetch" },
        { target: "idle", guard: "cannotFetch" },
      ],
    },
    idle: {
      on: {
        SET_IDS: {
          actions: ["setIds"],
          target: "loading.checking",
        },
      },
    },
    loading: {
      initial: "checking",
      states: {
        checking: {
          entry: ["sendCheckRequest"],
        },
        adding: {
          entry: ["sendAddRequest"],
        },
        removing: {
          entry: ["sendRemoveRequest"],
        },
      },
    },
    checked: {
      id: "checked",
      on: {
        CHECK: "loading.checking",
        ADD: "loading.adding",
        REMOVE: "loading.removing",
      },
    },
    error: {
      id: "error",
      on: {
        CHECK: "loading.checking",
        ADD: "loading.adding",
        REMOVE: "loading.removing",
        SET_IDS: {
          actions: ["setIds"],
          target: "loading.checking",
        },
      },
    },
  },
})

export const errorHandlerMachine = setup({
  types: {
    context: {} as Context,
    events: {} as ErrorEvent,
  },
  actions: {
    notify: ({ context, event }) => {
      if (event.type !== "ERROR_OCCURRED") return
      if (context.errors.filter((x) => !!x).find((e) => e?.id === event.data?.id)) {
        return
      }
      toast({
        title: event.data?.error,
        description: event.data?.message,
        status: "error",
        duration: event.data?.duration === null ? null : 3000,
        isClosable: true,
        id: event.data?.id,
        onCloseComplete: () => {
          // Note: This will be handled via direct send to errorActor when needed
        },
      })
    },
    addError: assign(({ context, event }) => {
      if (event.type !== "ERROR_OCCURRED") return context
      return {
        errors: [...context.errors, event.data],
      }
    }),
    removeError: assign(({ context, event }) => {
      if (event.type !== "CLEAR_ERROR") return context
      return {
        errors: context.errors.filter((e) => e !== event.data),
      }
    }),
  },
}).createMachine({
  id: "errorHandler",
  context: {
    errors: [],
  },
  on: {
    ERROR_OCCURRED: {
      actions: ["notify", "addError"],
    },
    CLEAR_ERROR: {
      actions: ["removeError"],
    },
  },
})

const socketMachine = setup({
  types: {
    context: {} as SocketContext,
    events: {} as SocketMachineEvent,
  },
  actors: {
    socketConnection: socketConnectionLogic,
  },
  actions: {
    addSubscriber: assign(({ context, event }: { context: SocketContext; event: SocketMachineEvent }) => {
      if (event.type !== "SUBSCRIBE") return {}
      if (!event.subscriber || typeof event.subscriber.send !== "function") {
        console.error("[SocketActor] Invalid subscriber for ID:", event.id, event.subscriber)
        return {}
      }
      // Using object allows idempotent subscriptions - same ID just updates reference
      return { subscribers: { ...context.subscribers, [event.id]: event.subscriber } }
    }),
    removeSubscriber: assign(({ context, event }: { context: SocketContext; event: SocketMachineEvent }) => {
      if (event.type !== "UNSUBSCRIBE") return {}
      const { [event.id]: _removed, ...rest } = context.subscribers
      return { subscribers: rest }
    }),
    setConnected: assign({
      connectionStatus: "connected" as const,
      lastError: null,
    }),
    setDisconnected: assign({
      connectionStatus: "disconnected" as const,
    }),
    setReconnecting: assign({
      connectionStatus: "connecting" as const,
    }),
    setError: assign(({ event }: { event: SocketMachineEvent }) => {
      if (event.type === "SOCKET_ERROR") {
        return { lastError: event.error }
      }
      return { lastError: null }
    }),
    incrementReconnectAttempts: assign(({ context, event }: { context: SocketContext; event: SocketMachineEvent }) => {
      if (event.type === "SOCKET_RECONNECTING") {
        return { reconnectAttempts: event.attemptNumber }
      }
      return { reconnectAttempts: context.reconnectAttempts + 1 }
    }),
    resetReconnectAttempts: assign({
      reconnectAttempts: 0,
    }),
    /** Before entering `disconnected` — run on transitions to disconnected */
    prepareOfflineFromDisconnect: assign(({ event }: { event: SocketMachineEvent }) => {
      if (event.type === "SOCKET_DISCONNECTED" && "reason" in event) {
        return { lastOfflineReason: (event as { reason?: string }).reason ?? "disconnected" }
      }
      return { lastOfflineReason: "disconnected" }
    }),
    prepareOfflineReconnectFailed: assign({
      lastOfflineReason: "reconnect_failed",
    }),
    clearOnlinePayload: assign({
      lastOnlinePayload: () => ({} as OnlinePayload),
    }),
    setOnlinePayloadFromFirstConnect: assign({
      lastOnlinePayload: () => ({} as OnlinePayload),
    }),
    setOnlinePayloadFromReconnect: assign(({ event }: { event: SocketMachineEvent }) => {
      if (event.type !== "SOCKET_RECONNECTED") return { lastOnlinePayload: {} as OnlinePayload }
      return { lastOnlinePayload: { attemptNumber: event.attemptNumber } }
    }),
    emitToServer: ({ event }: { event: SocketMachineEvent }) => {
      if (event.type !== "EMIT") return

      // Always emit: Socket.IO buffers while disconnected; dropping here lost sends after reconnect
      socket.emit(event.eventType, event.data)
      if (!socket.connected && !socket.active) {
        socket.connect()
      }
    },
    broadcastToSubscribers: ({ context, event }: { context: SocketContext; event: SocketMachineEvent }) => {
      if (event.type !== "SERVER_EVENT") return

      Object.entries(context.subscribers).forEach(([id, subscriber]) => {
        if (!subscriber || typeof subscriber.send !== "function") return
        if (!subscriberAccepts(subscriber, event.eventType)) return
        try {
          subscriber.send({ type: event.eventType, data: event.data })
        } catch (err) {
          console.error("[SocketActor] Error broadcasting to subscriber:", id, err)
        }
      })
    },
    broadcastOnline: ({ context }: { context: SocketContext }) => {
      const d: Record<string, unknown> = {}
      if (context.lastOnlinePayload?.attemptNumber != null) {
        d.attemptNumber = context.lastOnlinePayload.attemptNumber
      }
      broadcast(context.subscribers, "SOCKET_ONLINE", d)
    },
    broadcastOffline: ({ context }: { context: SocketContext }) => {
      broadcast(context.subscribers, "SOCKET_OFFLINE", { reason: context.lastOfflineReason })
    },
    broadcastRetrying: ({ context, event }: { context: SocketContext; event: SocketMachineEvent }) => {
      if (event.type !== "SOCKET_RECONNECTING") return
      broadcast(context.subscribers, "SOCKET_RECONNECTING", { attemptNumber: event.attemptNumber })
    },
    /** Safety net when the manager is inactive (e.g. finite reconnection cap exhausted) */
    attemptReconnect: () => {
      if (!socket.connected && !socket.active) {
        console.log("[SocketActor] Delayed reconnect nudge (disconnected safety net)")
        socket.connect()
      }
    },
  },
}).createMachine({
  id: "socket",
  initial: "initializing",
  context: {
    subscribers: {},
    connectionStatus: "disconnected",
    reconnectAttempts: 0,
    lastError: null,
    lastOfflineReason: "disconnected",
    lastOnlinePayload: {},
  },
  invoke: {
    id: "socketConnection",
    src: "socketConnection",
  },
  on: {
    // Subscription management - available in all states
    SUBSCRIBE: {
      actions: "addSubscriber",
    },
    UNSUBSCRIBE: {
      actions: "removeSubscriber",
    },
    // Outgoing events - emit to server
    EMIT: {
      actions: "emitToServer",
    },
    // Handle server events in all states to avoid race conditions
    // (events can arrive before SOCKET_CONNECTED is processed)
    SERVER_EVENT: {
      actions: "broadcastToSubscribers",
    },
  },
  states: {
    initializing: {
      on: {
        SOCKET_CONNECTED: {
          target: "connected",
          actions: ["setOnlinePayloadFromFirstConnect", "setConnected", "resetReconnectAttempts", "broadcastOnline"],
        },
        SOCKET_DISCONNECTED: {
          target: "disconnected",
          actions: ["prepareOfflineFromDisconnect", "setDisconnected", "broadcastOffline"],
        },
      },
    },
    disconnected: {
      after: {
        30000: {
          target: "disconnected",
          reenter: true,
          actions: "attemptReconnect",
        },
      },
      on: {
        SOCKET_CONNECTED: {
          target: "connected",
          actions: ["setOnlinePayloadFromFirstConnect", "setConnected", "resetReconnectAttempts", "broadcastOnline"],
        },
        SOCKET_RECONNECTING: {
          target: "reconnecting",
          actions: ["setReconnecting", "incrementReconnectAttempts", "broadcastRetrying"],
        },
      },
    },
    connected: {
      on: {
        SOCKET_DISCONNECTED: {
          target: "disconnected",
          actions: ["prepareOfflineFromDisconnect", "setDisconnected", "broadcastOffline"],
        },
        SOCKET_ERROR: {
          actions: "setError",
        },
      },
    },
    reconnecting: {
      on: {
        SOCKET_RECONNECTING: {
          actions: ["incrementReconnectAttempts", "broadcastRetrying"],
        },
        /** Fires before `reconnect` on some stacks — connect without attempt number */
        SOCKET_CONNECTED: {
          target: "connected",
          actions: ["setOnlinePayloadFromFirstConnect", "setConnected", "resetReconnectAttempts", "broadcastOnline"],
        },
        SOCKET_RECONNECTED: {
          target: "connected",
          actions: [
            "setOnlinePayloadFromReconnect",
            "setConnected",
            "resetReconnectAttempts",
            "broadcastOnline",
            "clearOnlinePayload",
          ],
        },
        SOCKET_RECONNECT_FAILED: {
          target: "disconnected",
          actions: ["prepareOfflineReconnectFailed", "setDisconnected", "broadcastOffline"],
        },
        SOCKET_ERROR: {
          actions: "setError",
        },
      },
    },
  },
})

export const whatsNewMachine = setup({
  types: {
    context: {} as WhatsNewContext,
    events: {} as WhatsNewEvent,
  },
  actions: {
    loadContent: assign(() => loadMonths()),
    syncAttention: ({ context }) => {
      syncUnreadNotification(context.latestMonthId)
    },
    markViewed: ({ context }) => {
      const monthId = context.latestMonthId
      if (!monthId) return
      markWhatsNewMonthViewed(monthId)
      resolveNotifications([whatsNewMonthNotificationId(monthId)])
    },
    clearAttention: () => {
      reconcileNotifications(WHATS_NEW_SOURCE, [])
    },
  },
}).createMachine({
  id: "whatsNew",
  initial: "idle",
  context: {
    months: [],
    latestMonthId: null,
  },
  states: {
    idle: {
      on: {
        ACTIVATE: {
          target: "active",
          actions: ["loadContent", "syncAttention"],
        },
      },
    },
    active: {
      exit: ["clearAttention"],
      on: {
        DEACTIVATE: "idle",
        MARK_VIEWED: { actions: ["markViewed"] },
        REFRESH: { actions: ["loadContent", "syncAttention"] },
      },
    },
  },
})

export const usersMachine = setup({
  types: {
    context: {} as UsersContext,
    events: {} as UsersEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `users-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event),
        eventTypes: [
          "USER_JOINED",
          "USER_LEFT",
          "USER_STATUS_CHANGED",
          "KICK_USER",
          "PERSONA_ASSIGNED",
          "PERSONA_REMOVED",
          "PERSONA_DEFINITIONS_UPDATED",
          "SET_USERS",
          "SET_DATA",
          "INIT",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    setUsers: assign(({ event }) => {
      if ("data" in event && "users" in event.data && event.data.users) {
        return derivePresence(event.data.users)
      }
      return { users: [], listeners: [], dj: null }
    }),
    patchUserStatus: assign(({ context, event }) => {
      if (event.type !== "USER_STATUS_CHANGED") return {}
      const updated = event.data.user
      const users = context.users.map((u) =>
        u.userId === updated.userId ? { ...u, ...updated } : u,
      )
      const hasUser = users.some((u) => u.userId === updated.userId)
      return derivePresence(hasUser ? users : [...users, updated])
    }),
    setAssignablePersonas: assign({
      assignablePersonas: ({ event }) => {
        if (event.type === "INIT" && event.data.assignablePersonas) {
          return event.data.assignablePersonas
        }
        if (event.type === "PERSONA_DEFINITIONS_UPDATED") {
          return event.data.assignablePersonas
        }
        return []
      },
    }),
    resetUsers: assign({
      users: () => [],
      listeners: () => [],
      dj: () => null,
      assignablePersonas: () => [],
      subscriptionId: () => null,
    }),
  },
}).createMachine({
  id: "users",
  initial: "idle",
  context: {
    users: [],
    dj: null,
    listeners: [],
    assignablePersonas: [],
    subscriptionId: null,
  },
  states: {
    // Idle state - not subscribed to socket events
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    // Active state - subscribed to socket events
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["resetUsers"],
        },
        USER_JOINED: {
          actions: ["setUsers"],
        },
        USER_LEFT: {
          actions: ["setUsers"],
        },
        USER_STATUS_CHANGED: {
          actions: ["patchUserStatus"],
        },
        KICK_USER: {
          actions: ["setUsers"],
        },
        PERSONA_ASSIGNED: {
          actions: ["setUsers"],
        },
        PERSONA_REMOVED: {
          actions: ["setUsers"],
        },
        PERSONA_DEFINITIONS_UPDATED: {
          actions: ["setAssignablePersonas"],
        },
        SET_USERS: {
          actions: ["setUsers"],
        },
        SET_DATA: {
          actions: ["setUsers"],
        },
        INIT: {
          actions: ["setUsers", "setAssignablePersonas"],
        },
      },
    },
  },
})

export const userGameStateMachine = setup({
  types: {
    context: {} as UserGameStateContext,
    events: {} as UserGameStateEvent,
  },
  guards: {
    /** Room-wide game/inventory events name their subject; skip everyone else's. */
    isMyGameEvent: ({ event }) => {
      const data = (event as { data?: UserScopedEventData }).data
      return isGameEventForUser(data, getCurrentUser()?.userId)
    },
    isMyGiftTradeEvent: ({ event }) => {
      const data = (event as { data?: GiftTradeEventData }).data
      return isGiftTradeEventForUser(data, getCurrentUser()?.userId)
    },
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `userGameState-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => {
          if (self.getSnapshot().status !== "active") return
          self.send(event as UserGameStateEvent)
        },
        eventTypes: [
          "INIT",
          "USER_GAME_STATE",
          "USER_GAME_STATE_INVALIDATED",
          "ERROR_OCCURRED",
          "GAME_SESSION_STARTED",
          "GAME_SESSION_ENDED",
          "GAME_STATE_CHANGED",
          "GAME_MODIFIER_APPLIED",
          "GAME_MODIFIER_REMOVED",
          "PRESENTED_IDENTITY_CHANGED",
          "INVENTORY_ITEM_ACQUIRED",
          "INVENTORY_ITEM_REMOVED",
          "INVENTORY_ITEM_UPDATED",
          "INVENTORY_ITEM_USED",
          "INVENTORY_ITEM_TRANSFERRED",
          "GIFT_OFFERED",
          "GIFT_DECLINED",
          "GIFT_CANCELLED",
          "GIFT_COMPLETED",
          "TRADE_INVITE_OFFERED",
          "TRADE_INVITE_DECLINED",
          "TRADE_INVITE_CANCELLED",
          "TRADE_INVITE_EXPIRED",
          "TRADE_INVITE_ACCEPTED",
          "TRADE_UPDATED",
          "TRADE_COMPLETED",
          "TRADE_CANCELLED",
          "GAME_SESSION_CONFIG_UPDATED",
          "GAME_ECONOMY_SCALE_CHANGED",
          "STORED_ARTIFACTS_RESULT",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
      debouncedRequest.cancel()
    },
    /** Immediate request (ACTIVATE / REFRESH / INIT) — no debounce. */
    requestGameState: () => {
      debouncedRequest.cancel()
      emitToSocket("GET_MY_GAME_STATE", {})
    },
    /** Debounced request for socket-driven invalidation bursts. */
    scheduleRequestGameState: () => {
      debouncedRequest.schedule()
    },
    /** Named assign: `enqueue.assign()` during socket broadcast warns (custom-action stack). */
    patchActiveTrade: assign(({ context, event }) => {
      if (event.type !== "TRADE_UPDATED") return {}
      const trade = event.data?.trade
      if (!trade || !context.payload) return {}
      return {
        payload: {
          ...context.payload,
          activeTrade: trade,
        },
      }
    }),
    scheduleRefetchIfTradeEscrowChanged: ({ context, event }) => {
      if (event.type !== "TRADE_UPDATED") return
      const trade = event.data?.trade
      if (!trade || !context.payload) return
      if (
        tradeEscrowChanged(context.payload.activeTrade, trade) ||
        tradeHasUnknownDefinitions(trade, context.payload.itemDefinitions)
      ) {
        debouncedRequest.schedule()
      }
    },
    notifyNavSessionFromTrade: ({ context, event }) => {
      if (event.type !== "TRADE_UPDATED") return
      const trade = event.data?.trade
      if (!trade || !context.payload) return
      notifyGameStateNavSession({
        allowTrading: context.payload.session?.config?.allowTrading === true,
        activeTrade: trade,
      })
    },
    setPayload: assign(({ event }) => {
      if (event.type !== "USER_GAME_STATE") return {}
      const d = event.data
      return {
        payload: {
          session: d.session,
          state: d.state,
          inventory: d.inventory,
          itemDefinitions: d.itemDefinitions ?? [],
          pluginUserState: d.pluginUserState ?? {},
          pendingGifts: d.pendingGifts,
          pendingTradeInvites: d.pendingTradeInvites,
          activeTrade: d.activeTrade ?? null,
          presentedIdentity: d.presentedIdentity ?? null,
        },
        error: null,
      }
    }),
    mergeEconomyScale: assign(({ event, context }) => {
      if (event.type !== "GAME_ECONOMY_SCALE_CHANGED") return {}
      const payload = context.payload
      if (!payload?.session) return {}
      const prev = resolveEconomy(payload.session.config.economy)
      return {
        payload: {
          ...payload,
          session: {
            ...payload.session,
            config: {
              ...payload.session.config,
              economy: {
                ...prev,
                costScale: event.data.costScale,
                earnScale: event.data.earnScale,
                updatedBy: event.data.updatedBy,
                reason: event.data.reason,
              },
            },
          },
        },
      }
    }),
    notifyNavSession: ({ event, context }) => {
      if (event.type === "USER_GAME_STATE") {
        notifyGameStateNavSession(sessionSnapshotFromPayload(event.data))
        notifyGameStateNavInventory({
          type: "held",
          itemIds: (event.data.inventory?.items ?? []).map((item) => item.itemId),
        })
        return
      }
      notifyGameStateNavSession(sessionSnapshotFromPayload(context.payload))
    },
    notifyNavSessionCleared: () => {
      notifyGameStateNavSession(sessionSnapshotFromPayload(null))
      notifyGameStateNavInventory({ type: "held", itemIds: [] })
    },
    notifyNavDropRemovedItem: ({ event }) => {
      if (event.type !== "INVENTORY_ITEM_REMOVED") return
      const itemId = event.data.itemId?.trim()
      if (itemId) notifyGameStateNavInventory({ type: "drop", itemId })
    },
    notifyNavDropTransferredItem: ({ event }) => {
      if (event.type !== "INVENTORY_ITEM_TRANSFERRED") return
      const me = getCurrentUser()?.userId
      if (!me || event.data.fromUserId !== me) return
      const itemId = event.data.item?.itemId?.trim()
      if (itemId) notifyGameStateNavInventory({ type: "drop", itemId })
    },
    requestStoredArtifacts: enqueueActions(({ event, context, enqueue }) => {
      if (event.type !== "USER_GAME_STATE") return
      const sessionId = event.data.session?.id
      if (!sessionId) return
      if (context.storedArtifactsSessionId === sessionId) return
      enqueue("assignStoredArtifactsSessionId")
      enqueue(() => {
        emitToSocket("GET_STORED_ARTIFACTS", {})
      })
    }),
    assignStoredArtifactsSessionId: assign(({ event }) => {
      if (event.type !== "USER_GAME_STATE") return {}
      const sessionId = event.data.session?.id
      if (!sessionId) return {}
      return { storedArtifactsSessionId: sessionId }
    }),
    setStoredArtifacts: assign(({ event }) => {
      if (event.type !== "STORED_ARTIFACTS_RESULT") return {}
      return { storedArtifacts: event.data?.artifacts ?? [] }
    }),
    beginStashPick: assign(({ event }) => {
      if (event.type !== "BEGIN_STASH_PICK") return {}
      const artifactId = event.artifactId?.trim()
      if (!artifactId) return {}
      return { pendingPickArtifactId: artifactId }
    }),
    clearStashPick: assign({
      pendingPickArtifactId: () => null,
    }),
    clearPayload: assign({
      payload: () => ({
        session: null,
        state: null,
        inventory: null,
        itemDefinitions: [],
        pluginUserState: {},
        pendingGifts: undefined,
        pendingTradeInvites: undefined,
        activeTrade: null,
        presentedIdentity: null,
      }),
      storedArtifacts: () => [],
      storedArtifactsSessionId: () => null,
      pendingPickArtifactId: () => null,
      error: () => null,
    }),
    setError: assign(({ event }) => {
      if (event.type !== "ERROR_OCCURRED") return {}
      return { error: event.data?.message ?? "Could not load your game state." }
    }),
    reset: assign({
      subscriptionId: () => null,
      payload: () => null,
      storedArtifacts: () => [],
      storedArtifactsSessionId: () => null,
      pendingPickArtifactId: () => null,
      error: () => null,
    }),
  },
}).createMachine({
  id: "userGameState",
  initial: "idle",
  context: {
    subscriptionId: null,
    payload: null,
    storedArtifacts: [],
    storedArtifactsSessionId: null,
    pendingPickArtifactId: null,
    error: null,
  },
  /** Socket invalidations apply in every subscribed state (loading / ready / refreshing). */
  on: {
    BEGIN_STASH_PICK: {
      actions: ["beginStashPick"],
    },
    CLEAR_STASH_PICK: {
      actions: ["clearStashPick"],
    },
    USER_GAME_STATE_INVALIDATED: {
      actions: ["scheduleRequestGameState"],
    },
    GAME_STATE_CHANGED: {
      guard: "isMyGameEvent",
      actions: ["scheduleRequestGameState"],
    },
    GAME_MODIFIER_APPLIED: {
      guard: "isMyGameEvent",
      actions: ["scheduleRequestGameState"],
    },
    GAME_MODIFIER_REMOVED: {
      guard: "isMyGameEvent",
      actions: ["scheduleRequestGameState"],
    },
    PRESENTED_IDENTITY_CHANGED: {
      guard: "isMyGameEvent",
      actions: ["scheduleRequestGameState"],
    },
    INVENTORY_ITEM_ACQUIRED: {
      guard: "isMyGameEvent",
      actions: ["scheduleRequestGameState"],
    },
    INVENTORY_ITEM_REMOVED: {
      guard: "isMyGameEvent",
      actions: ["notifyNavDropRemovedItem", "scheduleRequestGameState"],
    },
    INVENTORY_ITEM_UPDATED: {
      guard: "isMyGameEvent",
      actions: ["scheduleRequestGameState"],
    },
    INVENTORY_ITEM_USED: {
      guard: "isMyGameEvent",
      actions: ["scheduleRequestGameState"],
    },
    INVENTORY_ITEM_TRANSFERRED: {
      guard: "isMyGameEvent",
      actions: ["notifyNavDropTransferredItem", "scheduleRequestGameState"],
    },
    GIFT_OFFERED: refetchMyGiftTrade,
    GIFT_DECLINED: refetchMyGiftTrade,
    GIFT_CANCELLED: refetchMyGiftTrade,
    GIFT_COMPLETED: refetchMyGiftTrade,
    TRADE_INVITE_OFFERED: refetchMyGiftTrade,
    TRADE_INVITE_DECLINED: refetchMyGiftTrade,
    TRADE_INVITE_CANCELLED: refetchMyGiftTrade,
    TRADE_INVITE_EXPIRED: refetchMyGiftTrade,
    TRADE_INVITE_ACCEPTED: refetchMyGiftTrade,
    TRADE_UPDATED: {
      guard: "isMyGiftTradeEvent",
      actions: [
        "scheduleRefetchIfTradeEscrowChanged",
        "patchActiveTrade",
        "notifyNavSessionFromTrade",
      ],
    },
    TRADE_COMPLETED: refetchMyGiftTrade,
    TRADE_CANCELLED: refetchMyGiftTrade,
    STORED_ARTIFACTS_RESULT: {
      actions: ["setStoredArtifacts"],
    },
  },
  states: {
    idle: {
      on: {
        ACTIVATE: "loading",
      },
    },
    loading: {
      entry: ["subscribe", "requestGameState"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["unsubscribe", "reset", "notifyNavSessionCleared"],
        },
        INIT: {
          actions: ["requestGameState"],
        },
        USER_GAME_STATE: {
          target: "ready",
          actions: ["setPayload", "notifyNavSession", "requestStoredArtifacts"],
        },
        ERROR_OCCURRED: {
          target: "error",
          actions: ["setError"],
        },
      },
    },
    ready: {
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["unsubscribe", "reset", "notifyNavSessionCleared"],
        },
        REFRESH: {
          target: "refreshing",
        },
        INIT: {
          actions: ["requestGameState"],
        },
        USER_GAME_STATE: {
          actions: ["setPayload", "notifyNavSession", "requestStoredArtifacts"],
        },
        GAME_SESSION_STARTED: {
          actions: ["requestGameState"],
        },
        GAME_SESSION_CONFIG_UPDATED: {
          actions: ["requestGameState"],
        },
        GAME_ECONOMY_SCALE_CHANGED: {
          actions: ["mergeEconomyScale"],
        },
        GAME_SESSION_ENDED: {
          actions: ["clearPayload", "notifyNavSessionCleared"],
        },
      },
    },
    refreshing: {
      entry: ["requestGameState"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["unsubscribe", "reset", "notifyNavSessionCleared"],
        },
        INIT: {
          actions: ["requestGameState"],
        },
        USER_GAME_STATE: {
          target: "ready",
          actions: ["setPayload", "notifyNavSession", "requestStoredArtifacts"],
        },
        ERROR_OCCURRED: {
          target: "error",
          actions: ["setError"],
        },
      },
    },
    error: {
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["unsubscribe", "reset", "notifyNavSessionCleared"],
        },
        INIT: {
          target: "refreshing",
        },
        REFRESH: {
          target: "loading",
        },
      },
    },
  },
})

