export const trackPreviewMachine = setup({
  types: {
    context: {} as TrackPreviewContext,
    events: {} as TrackPreviewEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `trackPreview-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as TrackPreviewEvent),
        eventTypes: ["GET_TRACK_PREVIEW_RESULTS", "GET_TRACK_PREVIEW_FAILURE"],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    requestPreview: assign(({ context, event }) => {
      if (event.type !== "TOGGLE_PREVIEW") return {}
      unloadHowl(context.howl)
      audioActor.send({ type: "END_PREVIEW" })
      const payload = {
        trackId: event.trackId,
        ...(event.mediaKey ? { mediaKey: event.mediaKey } : {}),
        ...(event.source ? { source: event.source } : {}),
      }
      // Defer emit so entry subscribe runs first when transitioning idle → active.
      queueMicrotask(() => {
        emitToSocket("GET_TRACK_PREVIEW", payload)
      })
      return {
        trackKey: event.trackKey,
        status: "loading" as const,
        howl: null,
      }
    }),
    stopPreview: assign(({ context }) => {
      unloadHowl(context.howl)
      audioActor.send({ type: "END_PREVIEW" })
      return { trackKey: null, status: "idle" as const, howl: null }
    }),
    playPreview: assign(({ context, event, self }) => {
      if (event.type !== "GET_TRACK_PREVIEW_RESULTS") return {}
      unloadHowl(context.howl)
      const url = resolvePreviewClipUrl(event.data.url)
      let started = false
      const sound = new Howl({
        src: [url],
        html5: true,
        volume: previewVolume(),
        format: ["mp3"],
        onplay: () => {
          if (started) return
          started = true
          audioActor.send({ type: "START_PREVIEW" })
        },
        onend: () => {
          self.send({ type: "PREVIEW_ENDED" })
        },
        onloaderror: (_id, err) => {
          console.error("[TrackPreview] Failed to load clip:", url, err)
          self.send({ type: "PREVIEW_ERROR" })
        },
        onplayerror: (_id, err) => {
          console.error("[TrackPreview] Failed to play clip:", url, err)
          self.send({ type: "PREVIEW_ERROR" })
        },
      })
      sound.once("load", () => {
        sound.play()
      })
      sound.load()
      return { status: "playing" as const, howl: sound }
    }),
    clearAfterFailure: assign(({ context }) => {
      unloadHowl(context.howl)
      audioActor.send({ type: "END_PREVIEW" })
      return { trackKey: null, status: "idle" as const, howl: null }
    }),
    reset: assign(({ context }) => {
      unloadHowl(context.howl)
      audioActor.send({ type: "END_PREVIEW" })
      return defaultContext
    }),
  },
  guards: {
    isSamePlayingTrack: ({ context, event }) =>
      event.type === "TOGGLE_PREVIEW" &&
      context.trackKey === event.trackKey &&
      context.status === "playing",
  },
}).createMachine({
  id: "trackPreview",
  initial: "idle",
  context: defaultContext,
  states: {
    idle: {
      on: {
        ACTIVATE: "active",
        TOGGLE_PREVIEW: {
          target: "active",
          actions: ["requestPreview"],
        },
      },
    },
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe", "reset"],
      on: {
        DEACTIVATE: "idle",
        TOGGLE_PREVIEW: [
          {
            guard: "isSamePlayingTrack",
            actions: ["stopPreview"],
          },
          {
            actions: ["requestPreview"],
          },
        ],
        STOP_PREVIEW: {
          actions: ["stopPreview"],
        },
        GET_TRACK_PREVIEW_RESULTS: {
          actions: ["playPreview"],
        },
        GET_TRACK_PREVIEW_FAILURE: {
          actions: ["clearAfterFailure"],
        },
        PREVIEW_ENDED: {
          actions: ["stopPreview"],
        },
        PREVIEW_ERROR: {
          actions: ["clearAfterFailure"],
        },
      },
    },
  },
})

const createMachineConfig = (initialContext: Context) =>
  setup({
    types: {
      context: {} as Context,
      events: {} as ToggleableCollectionEvent,
    },
    actions: {
      enablePersistence: assign({
        persistent: () => true,
      }),
      persist: ({ context }) => {
        if (context.persistent) {
          sessionStorage.setItem(context.name, JSON.stringify(context.collection))
        }
      },
      loadCollection: assign({
        collection: ({ context }) =>
          context.persistent
            ? JSON.parse(sessionStorage.getItem(context.name) || "[]") || []
            : context.collection,
      }),
      setName: assign({
        name: ({ event }) => {
          if (event.type === "SET_NAME") {
            return event.data
          }
          return ""
        },
      }),
      setItems: assign({
        collection: ({ event }) => {
          if (event.type === "SET_ITEMS") {
            return event.data
          }
          return []
        },
      }),
      addItems: assign({
        collection: ({ context, event }) => {
          if (event.type !== "ADD_ITEMS") return context.collection
          return uniqBy(context.idPath || "id", [...event.data, ...context.collection])
        },
      }),
      clear: assign({ collection: [] }),
      toggleItem: assign({
        collection: ({ context, event }) => {
          if (event.type !== "TOGGLE_ITEM" && event.type !== "TOGGLE_MESSAGE") {
            return context.collection
          }
          const isPresent = context.collection
            .map((record) => get(context.idPath || "id", record))
            .includes(get(context.idPath || "id", event.data))

          if (isPresent) {
            return context.collection.filter(
              (x: ChatMessage) =>
                get(context.idPath || "id", x) !== get(context.idPath || "id", event.data),
            )
          }
          return uniqBy("id", [event.data, ...context.collection])
        },
      }),
    },
  }).createMachine({
    id: "toggleableCollection",
    initial: "ready",
    context: initialContext,
    on: {
      TOGGLE_ITEM: { actions: ["toggleItem", "persist"] },
      SET_ITEMS: { actions: ["setItems"] },
      ADD_ITEMS: { actions: ["addItems"] },
      CLEAR: { actions: ["clear"] },
    },
    states: {
      ready: {
        entry: ["loadCollection"],
        on: {
          TOGGLE_MESSAGE: { actions: ["toggleItem", "persist"] },
          ENABLE_PERSISTENCE: { actions: ["enablePersistence"] },
          SET_NAME: { actions: ["setName"] },
        },
      },
    },
  })

