export const savePlaylistMachine = setup({
  types: {
    context: {} as Context,
    events: {} as SavePlaylistEvent,
  },
  actions: {
    savePlaylist: ({ event }) => {
      if (event.type === "SAVE_PLAYLIST") {
        // Extract track IDs for the target service from metadataSources
        const trackData = event.items.map((item) => {
          // Try to get track ID from the specific metadata source
          const sourceData = item.metadataSources?.[event.targetService]
          if (sourceData?.source?.trackId) {
            return { 
              trackId: sourceData.source.trackId, 
              found: true, 
              title: item.title,
              artist: item.track.artists?.[0]?.title
            }
          }
          // Fallback: if target is spotify and we have a mediaSource with spotify type
          if (event.targetService === "spotify" && item.mediaSource?.type === "spotify") {
            return { 
              trackId: item.mediaSource.trackId, 
              found: true,
              title: item.title,
              artist: item.track.artists?.[0]?.title
            }
          }
          // Track not available for this service
          return { 
            trackId: null, 
            found: false,
            title: item.title,
            artist: item.track.artists?.[0]?.title
          }
        })

        const matchedTracks = trackData.filter((t) => t.found).map((t) => t.trackId!)
        const skippedTracks = trackData.filter((t) => !t.found)

        console.log("[savePlaylistMachine] Sending to socket:", {
          name: event.name,
          targetService: event.targetService,
          totalTracks: event.items.length,
          matchedTracks: matchedTracks.length,
          skippedTracks: skippedTracks.length,
        })

        if (matchedTracks.length === 0) {
          // No tracks could be matched - emit error locally
          toast({
            title: "Playlist failed",
            description: `No tracks found for ${event.targetService}. Try a different service.`,
            status: "error",
            duration: 4000,
          })
          return
        }

        // Note: Unavailable tracks are now shown disabled in the UI with tooltips,
        // so we don't need a warning toast here

        emitToSocket("SAVE_PLAYLIST", {
          name: event.name,
          trackIds: matchedTracks,
          targetService: event.targetService,
          roomId: event.roomId,
        })
      }
    },
    setPlaylistMeta: assign({
      playlistMeta: ({ event }) => {
        if (event.type === "PLAYLIST_SAVED") {
          return event.data
        }
        return null
      },
    }),
    setPlaylistError: assign({
      playlistError: ({ event }) => {
        if (event.type === "SAVE_PLAYLIST_FAILED") {
          return event.error
        }
        return null
      },
    }),
    notifyPlaylistCreated: () => {
      toast({
        title: "Playlist saved",
        description: "Your playlist has been saved",
        status: "success",
        duration: 4000,
      })
    },
    notifyPlaylistCreateFailed: ({ context }) => {
      console.error("[savePlaylistMachine] Error:", context.playlistError)
      const errorMessage =
        context.playlistError?.message ||
        (typeof context.playlistError === "string" ? context.playlistError : null) ||
        "Failed to save playlist"
      toast({
        title: "Playlist failed",
        description: errorMessage,
        status: "error",
        duration: 4000,
      })
    },
  },
}).createMachine({
  id: "save-playlist",
  context: {
    playlistMeta: null,
    playlistError: null,
  },
  initial: "idle",
  states: {
    idle: {
      on: {
        SAVE_PLAYLIST: {
          target: "loading",
          actions: ["savePlaylist"],
        },
      },
    },
    loading: {
      on: {
        PLAYLIST_SAVED: {
          target: "success",
          actions: ["setPlaylistMeta", "notifyPlaylistCreated"],
        },
        SAVE_PLAYLIST_FAILED: {
          target: "error",
          actions: ["setPlaylistError", "notifyPlaylistCreateFailed"],
        },
      },
    },
    success: {
      id: "success",
      after: {
        1000: "idle",
      },
    },
    error: {
      id: "error",
      after: {
        1000: "idle",
      },
    },
  },
})

export const roomSetupMachine = setup({
  types: {
    context: {} as RoomSetupContext,
    events: {} as RoomSetupEvent,
  },
  actors: {
    createRoomRequest: createRoomLogic,
  },
  actions: {
    setError: assign(({ event }) => {
      if (event.type !== "xstate.error.actor.createRoomRequest") return {}
      // Clear the creation flag on error so user can retry
      sessionStorage.removeItem("roomCreationInProgress")
      sessionStorage.removeItem("createRoomShowId")
      sessionStorage.removeItem("createRoomLiveIngestEnabled")
      sessionStorage.removeItem("createRoomLiveWhepUrl")
      sessionStorage.removeItem("createRoomLiveHlsUrl")
      sessionStorage.removeItem("createRoomPlaybackControllerId")
      return {
        error: String(event.error),
      }
    }),
    setRoom: ({ event }) => {
      if (event.type !== "xstate.done.actor.createRoomRequest") {
        return
      }
      saveCurrentUser({
        currentUser: {
          userId: event.output.room?.creator ?? "",
          isAdmin: true,
        },
      })
      // Clear all room creation state from sessionStorage
      sessionStorage.removeItem("createRoomTitle")
      sessionStorage.removeItem("createRoomType")
      sessionStorage.removeItem("createRoomDeputizeOnJoin")
      sessionStorage.removeItem("createRoomradioMetaUrl")
      sessionStorage.removeItem("createRoomRadioListenUrl")
      sessionStorage.removeItem("createRoomRadioProtocol")
      sessionStorage.removeItem("createRoomShowId")
      sessionStorage.removeItem("createRoomLiveIngestEnabled")
      sessionStorage.removeItem("createRoomLiveWhepUrl")
      sessionStorage.removeItem("createRoomLiveHlsUrl")
      sessionStorage.removeItem("createRoomPublic")
      sessionStorage.removeItem("createRoomPlaybackControllerId")
      sessionStorage.removeItem("roomCreationInProgress")
      window.location.href = `/rooms/${event.output.room.id}`
    },
    setRequirements: assign(({ event }) => {
      if (event.type !== "SET_REQUIREMENTS") return {}
      return {
        room: event.data.room,
      }
    }),
  },
  guards: {
    hasRequirements: ({ context }) => {
      return !!context.room
    },
  },
}).createMachine({
  id: "roomSetup",
  initial: "initial",
  context: {
    error: null,
    room: null,
  },
  states: {
    initial: {
      on: {
        SET_REQUIREMENTS: {
          actions: ["setRequirements"],
          target: "loading",
        },
      },
    },
    loading: {
      invoke: {
        id: "createRoomRequest",
        src: "createRoomRequest",
        input: ({ context }) => context,
        onDone: {
          target: "success",
          actions: ["setRoom"],
        },
        onError: {
          target: "error",
          actions: ["setError"],
        },
      },
    },
    success: {
      type: "final",
    },
    error: {},
  },
})

