export const roomLayoutMachine = setup({
  types: {
    context: {} as RoomLayoutState,
    events: {} as RoomLayoutEvent,
  },
  actions: {
    loadLayout: assign(() => loadRoomLayout()),
    persistLayout: ({ context }) => {
      saveRoomLayout(context)
    },
  },
}).createMachine({
  id: "roomLayout",
  initial: "active",
  context: loadRoomLayout(),
  states: {
    active: {
      entry: ["loadLayout"],
      on: {
        RESIZE_END: {
          actions: [
            assign(({ context, event }) => {
              if (event.type !== "RESIZE_END") return {}
              const sizes = normalizeLayoutSizes(event.sizes)
              if (event.layout === "4") {
                return { ...context, layout4: sizes }
              }
              return { ...context, layout3: sizes }
            }),
            "persistLayout",
          ],
        },
        RESET: {
          actions: [
            assign(({ context, event }) => {
              if (event.type !== "RESET") return {}
              if (event.layout === "4") {
                return { ...context, layout4: getDefaultLayout("4") }
              }
              if (event.layout === "3") {
                return { ...context, layout3: getDefaultLayout("3") }
              }
              return {
                layout3: getDefaultLayout("3"),
                layout4: getDefaultLayout("4"),
              }
            }),
            "persistLayout",
          ],
        },
      },
    },
  },
})

export const roomGameStateMachine = setup({
  types: {
    context: {} as RoomGameStateContext,
    events: {} as RoomGameStateEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `roomGameState-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as RoomGameStateEvent),
        eventTypes: [
          "INIT",
          "GAME_SESSION_STARTED",
          "GAME_SESSION_ENDED",
          "ROOM_GAME_STATE",
          "GAME_MODIFIER_APPLIED",
          "GAME_MODIFIER_REMOVED",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    requestSnapshot: () => {
      emitToSocket("GET_ROOM_GAME_STATE", {})
    },
    setSnapshot: assign(({ event }) => {
      if (event.type !== "ROOM_GAME_STATE") return {}
      return {
        sessionId: event.data.sessionId ?? null,
        modifiersByUserId: event.data.modifiersByUserId ?? {},
      }
    }),
    applyModifier: assign(({ context, event }) => {
      if (event.type !== "GAME_MODIFIER_APPLIED") return {}
      const { userId, modifier } = event.data
      if (!userId || !modifier) return {}
      const existing = context.modifiersByUserId[userId] ?? []
      const replaced = existing.filter((m) => m.id !== modifier.id)
      replaced.push(modifier)
      return {
        modifiersByUserId: {
          ...context.modifiersByUserId,
          [userId]: replaced,
        },
      }
    }),
    removeModifier: assign(({ context, event }) => {
      if (event.type !== "GAME_MODIFIER_REMOVED") return {}
      const { userId, modifierId } = event.data
      if (!userId || !modifierId) return {}
      const existing = context.modifiersByUserId[userId]
      if (!existing) return {}
      const next = existing.filter((m) => m.id !== modifierId)
      const nextMap = { ...context.modifiersByUserId }
      if (next.length === 0) {
        delete nextMap[userId]
      } else {
        nextMap[userId] = next
      }
      return { modifiersByUserId: nextMap }
    }),
    clearModifiers: assign({
      sessionId: () => null,
      modifiersByUserId: () => ({}),
    }),
    reset: assign({
      subscriptionId: () => null,
      sessionId: () => null,
      modifiersByUserId: () => ({}),
    }),
  },
}).createMachine({
  id: "roomGameState",
  initial: "idle",
  context: {
    subscriptionId: null,
    sessionId: null,
    modifiersByUserId: {},
  },
  states: {
    idle: {
      on: {
        ACTIVATE: "ready",
      },
    },
    ready: {
      entry: ["subscribe", "requestSnapshot"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["unsubscribe", "reset"],
        },
        INIT: {
          actions: ["requestSnapshot"],
        },
        GAME_SESSION_STARTED: {
          actions: ["requestSnapshot"],
        },
        GAME_SESSION_ENDED: {
          actions: ["clearModifiers"],
        },
        ROOM_GAME_STATE: {
          actions: ["setSnapshot"],
        },
        GAME_MODIFIER_APPLIED: {
          actions: ["applyModifier"],
        },
        GAME_MODIFIER_REMOVED: {
          actions: ["removeModifier"],
        },
      },
    },
  },
})

export const roomFetchMachine = setup({
  types: {
    context: {} as RoomFetchContext,
    events: {} as RoomFetchEvent,
  },
  actors: {
    socketConnection: socketConnectionLogic,
    fetchRoom: fetchRoomLogic,
  },
  guards: {
    isRoomNotFound: ({ event }) => {
      if (event.type !== "xstate.error.actor.fetchRoom") return false
      return fetchErrorStatus(event.error) === 404
    },
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `room-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as RoomFetchEvent),
        eventTypes: [
          "ROOM_DELETED",
          "SESSION_ENDED",
          "SHOW_SCHEDULE_UPDATED",
          "ROOM_SETTINGS_UPDATED",
          "ROOM_DATA",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    setSocketError: assign(({ context, event }) => {
      if (event.type !== "SOCKET_ERROR") return context
      return {
        error: {
          message: "You've been disconnected from the server, attempting to reconnect...",
          status: 400,
        },
      }
    }),
    clearError: assign(() => {
      return {
        error: null,
      }
    }),
    setError: assign(({ context, event }) => {
      if (event.type !== "xstate.error.actor.fetchRoom" && event.type !== "SOCKET_ERROR") {
        return context
      }

      const errorStatus =
        event.type === "xstate.error.actor.fetchRoom"
          ? (event.error as any)?.response?.status
          : (event as any).data?.error?.status
      const errorMessage = getErrorMessage({ status: errorStatus }, false, "room")

      return {
        error: {
          message: errorMessage,
          status: errorStatus ?? 500,
        },
      }
    }),
    setId: assign(({ context, event }) => {
      if (event.type !== "FETCH") return context
      return {
        id: event.data.id,
      }
    }),
    /**
     * Hybrid radio WebRTC must stop before room context updates reach React, or Shoutcast
     * mounts with a stale "playing" snapshot from the audio machine (play then does nothing).
     */
    stopAudioWhenHybridRadioIngestDisabled: ({ context, event }) => {
      if (event.type !== "ROOM_SETTINGS_UPDATED" && event.type !== "ROOM_DATA") {
        return
      }
      const prev = context.room
      const next = event.data.room
      if (!prev || !next) return
      if (prev.type !== "radio" || next.type !== "radio") return
      if (!prev.liveIngestEnabled) return
      // Still enabled (explicit true); false/undefined = path off
      if (next.liveIngestEnabled === true) return
      audioActor.send({ type: "STOP" })
    },
    setRoom: assign(({ context, event }) => {
      const hasShow = (r: Omit<Room, "password"> | null | undefined) =>
        r?.showId != null && r.showId !== ""

      if (event.type === "xstate.done.actor.fetchRoom") {
        const r = event.output.room
        return {
          room: r,
          scheduleSnapshot: hasShow(r) ? (event.output.scheduleSnapshot ?? null) : null,
        }
      }
      if (event.type === "ROOM_SETTINGS_UPDATED") {
        const r = event.data.room
        return {
          room: r,
          scheduleSnapshot: hasShow(r) ? context.scheduleSnapshot : null,
        }
      }
      if (event.type === "ROOM_DATA") {
        const r = event.data.room
        const snap =
          event.data.scheduleSnapshot !== undefined
            ? event.data.scheduleSnapshot
            : context.scheduleSnapshot
        return {
          room: r,
          scheduleSnapshot: hasShow(r) ? snap : null,
        }
      }
      return context
    }),
    setScheduleFromSocket: assign(({ context, event }) => {
      if (event.type !== "SHOW_SCHEDULE_UPDATED") return context
      if (event.data.roomId !== context.id) return context
      return {
        ...context,
        scheduleSnapshot: event.data.snapshot,
      }
    }),
    reset: assign(() => {
      return {
        id: null,
        room: null,
        scheduleSnapshot: null,
        error: null,
        subscriptionId: null,
      }
    }),
    getLatestData: ({ context }) => {
      const messages = chatActor.getSnapshot().context.messages
      const lastMessageTime = messages[messages.length - 1]?.timestamp
      const playlist = playlistActor.getSnapshot().context.playlist
      const lastPlaylistItemTime = playlist[playlist.length - 1]?.addedAt

      emitToSocket("GET_LATEST_ROOM_DATA", {
        id: context.id,
        lastMessageTime,
        lastPlaylistItemTime,
        lastPollChange: getLastPollChange(),
      })
    },
    assignRoomDeleted: assign(() => {
      return {
        error: {
          message: ROOM_EXPIRED_MESSAGE,
          status: 404,
        },
      }
    }),
    redirectHome: () => {
      window.location.replace("/")
    },
  },
  delays: {
    roomMissingRedirect: ROOM_MISSING_REDIRECT_MS,
  },
}).createMachine({
  id: "roomFetch",
  initial: "idle",
  context: {
    fetchOnInit: true,
    id: null,
    room: null,
    scheduleSnapshot: null,
    subscriptionId: null,
  },
  states: {
    // Idle state - not subscribed to socket events
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    // Active state - subscribed to socket events
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      invoke: {
        id: "socketConnection",
        src: "socketConnection",
      },
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["reset"],
        },
        FETCH: {
          target: ".loading",
          actions: ["setId"],
        },
        RESET: {
          actions: ["reset"],
          target: ".initial",
        },
        ROOM_DELETED: {
          target: ".deleted",
          actions: ["assignRoomDeleted"],
        },
        SOCKET_ERROR: {
          actions: ["setSocketError"],
        },
        RECONNECTED: {
          actions: ["getLatestData", "clearError"],
        },
        SESSION_ENDED: {
          actions: ["reset"],
          target: ".initial",
        },
        SHOW_SCHEDULE_UPDATED: {
          actions: ["setScheduleFromSocket"],
        },
      },
      initial: "initial",
      states: {
        initial: {},
        loading: {
          invoke: {
            id: "fetchRoom",
            src: "fetchRoom",
            input: ({ context }) => ({ id: context.id }),
            onDone: {
              target: "success",
              actions: ["setRoom"],
            },
            onError: [
              {
                guard: "isRoomNotFound",
                target: "deleted",
                actions: ["setError"],
              },
              {
                target: "error",
                actions: ["setError"],
              },
            ],
          },
        },
        success: {
          on: {
            ROOM_SETTINGS_UPDATED: {
              actions: ["stopAudioWhenHybridRadioIngestDisabled", "setRoom"],
            },
            GET_LATEST_ROOM_DATA: {
              actions: ["getLatestData"],
            },
            ROOM_DATA: {
              actions: ["stopAudioWhenHybridRadioIngestDisabled", "setRoom"],
            },
          },
        },
        error: {},
        deleted: {
          after: {
            roomMissingRedirect: {
              target: "redirecting",
              actions: ["redirectHome"],
            },
          },
          on: {
            FETCH: {},
            RESET: {},
            SOCKET_ERROR: {},
            RECONNECTED: {},
            SESSION_ENDED: {},
          },
        },
        redirecting: {},
      },
    },
  },
})

export const reducedMotionMachine = setup({
  types: {
    context: {} as Context,
    events: {} as ReducedMotionEvent,
  },
  actions: {
    setReducedMotion: assign({
      reducedMotion: ({ event }) => {
        if (event.type === "SET_REDUCED_MOTION") {
          return event.value
        }
        return false
      },
    }),
    toggleReducedMotion: assign({
      reducedMotion: ({ context }) => !context.reducedMotion,
    }),
    persistReducedMotion: ({ context }) => {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(context.reducedMotion))
    },
    loadReducedMotion: assign({
      reducedMotion: () => {
        const stored = sessionStorage.getItem(STORAGE_KEY)
        return stored ? JSON.parse(stored) : false
      },
    }),
  },
}).createMachine({
  id: "reducedMotion",
  context: {
    reducedMotion: false,
  },
  entry: ["loadReducedMotion"],
  on: {
    SET_REDUCED_MOTION: {
      actions: ["setReducedMotion", "persistReducedMotion"],
    },
    TOGGLE_REDUCED_MOTION: {
      actions: ["toggleReducedMotion", "persistReducedMotion"],
    },
  },
})

export const radioStreamMachine = setup({
  types: {
    context: {} as RadioStreamContext,
    events: {} as RadioStreamEvent,
    emitted: {} as RadioStreamEmitted,
  },
  actors: {
    playbackRun: fromCallback<
      AnyEventObject,
      { url: string; mseRejected: boolean }
    >(({ input, sendBack }) => {
      let detach: (() => void) | null = null

      const attachElement = (el: HTMLAudioElement) => {
        const onPlaying = () => sendBack({ type: "ELEMENT_PLAYING" })
        const onEnded = () => sendBack({ type: "ELEMENT_ENDED" })
        const onError = () =>
          sendBack({ type: "ELEMENT_ERROR", message: mediaErrorMessage(el) })
        el.addEventListener("playing", onPlaying)
        el.addEventListener("ended", onEnded)
        el.addEventListener("error", onError)
        return () => {
          el.removeEventListener("playing", onPlaying)
          el.removeEventListener("ended", onEnded)
          el.removeEventListener("error", onError)
        }
      }

      const startElement = () => {
        setRadioPlaybackUrl(input.url)
        const el = ensureRadioPlaybackElement()
        if (!el) {
          sendBack({ type: "ELEMENT_ERROR", message: "noAudioElement" })
          return
        }
        detach?.()
        detach = attachElement(el)
        playRadioPlayback()
      }

      const startMse = () => {
        const el = ensureRadioMseElement()
        if (!el) {
          sendBack({ type: "MSE_FALLBACK" })
          startElement()
          return
        }
        const onPlaying = () => {
          markRadioMsePlaying()
          sendBack({ type: "ELEMENT_PLAYING" })
        }
        const onEnded = () => sendBack({ type: "ELEMENT_ENDED" })
        const onError = () =>
          sendBack({ type: "ELEMENT_ERROR", message: mediaErrorMessage(el) })
        el.addEventListener("playing", onPlaying)
        el.addEventListener("ended", onEnded)
        el.addEventListener("error", onError)
        detach = () => {
          el.removeEventListener("playing", onPlaying)
          el.removeEventListener("ended", onEnded)
          el.removeEventListener("error", onError)
          releaseRadioMse()
        }
        startRadioMseStream(input.url, {
          onFallbackBeforePlaying: () => {
            sendBack({ type: "MSE_FALLBACK" })
            releaseRadioMse()
            startElement()
          },
        })
        playRadioMse()
      }

      if (useMseRadioTransport(input.mseRejected)) startMse()
      else startElement()

      return () => {
        detach?.()
        detach = null
        releaseRadioPlayback()
        releaseRadioMse()
      }
    }),
  },
  guards: {
    canConnect: ({ context }) => context.playing && Boolean(context.url),
    hasUrl: ({ context }) => Boolean(context.url),
    canRetry: ({ context }) => context.retries < MAX_PLAYBACK_RETRIES,
  },
  actions: {
    setPlaying: assign({ playing: true }),
    clearPlaying: assign({ playing: false }),
    setUrl: assign({
      url: ({ event }) => (event.type === "SET_URL" ? event.url : null),
      error: null,
      retries: 0,
    }),
    clearError: assign({ error: null }),
    setError: assign({
      error: ({ event }) => (event.type === "ELEMENT_ERROR" ? event.message : "streamFailed"),
    }),
    countRetry: assign({ retries: ({ context }) => context.retries + 1 }),
    clearRetries: assign({ retries: 0, error: null }),
    rejectMse: assign({ mseRejected: true }),
    reset: assign({
      url: null,
      playing: false,
      error: null,
      retries: 0,
      mseRejected: false,
    }),
    emitPlaybackStarted: emit({ type: "playbackStarted" as const }),
    emitFailed: emit(({ context }) => ({
      type: "failed" as const,
      message: context.error ?? "streamFailed",
    })),
  },
}).createMachine({
  id: "radioStream",
  initial: "idle",
  context: {
    url: null,
    playing: false,
    error: null,
    retries: 0,
    mseRejected: false,
  },
  on: {
    SET_URL: [
      {
        guard: ({ context, event }) => context.playing && event.url !== context.url,
        target: ".active",
        reenter: true,
        actions: ["setUrl"],
      },
      { actions: ["setUrl"] },
    ],
    PAUSE: { target: ".idle", actions: ["clearPlaying"] },
    TEARDOWN: { target: ".idle", actions: ["reset"] },
  },
  states: {
    idle: {
      on: {
        PLAY: [
          {
            guard: "hasUrl",
            target: "active",
            actions: ["setPlaying", "clearRetries"],
          },
          { actions: ["setPlaying"] },
        ],
      },
      always: { guard: "canConnect", target: "active" },
    },

    active: {
      id: "playbackActive",
      entry: ["clearError"],
      invoke: {
        src: "playbackRun",
        input: ({ context }) => ({
          url: context.url ?? "",
          mseRejected: context.mseRejected,
        }),
      },
      initial: "loading",
      states: {
        loading: {
          on: {
            ELEMENT_PLAYING: {
              target: "playing",
              actions: ["clearRetries", "emitPlaybackStarted"],
            },
            MSE_FALLBACK: { actions: ["rejectMse"] },
          },
        },
        playing: {
          on: {
            MSE_FALLBACK: { actions: ["rejectMse"] },
          },
        },
      },
      on: {
        ELEMENT_ENDED: [
          { guard: "canRetry", target: "reconnecting", actions: ["countRetry"] },
          { target: "failed", actions: ["setError", "emitFailed"] },
        ],
        ELEMENT_ERROR: [
          {
            guard: "canRetry",
            target: "reconnecting",
            actions: ["setError", "countRetry"],
          },
          { target: "failed", actions: ["setError", "emitFailed"] },
        ],
      },
    },

    reconnecting: {
      after: {
        [RECONNECT_DELAY_MS]: [
          { guard: "canConnect", target: "active", reenter: true },
          { target: "idle" },
        ],
      },
    },

    failed: {
      on: {
        PLAY: [
          {
            guard: "hasUrl",
            target: "active",
            actions: ["setPlaying", "clearRetries"],
          },
          { actions: ["setPlaying"] },
        ],
      },
    },
  },
})

export const quickAccessPanelsMachine = setup({
  types: {
    context: {} as QuickAccessPanelsMachineContext,
    events: {} as QuickAccessPanelsEvent,
  },
  actions: {
    persistPanels: ({ context }) => {
      saveQuickAccessPanels(context.roomId, context.panels)
    },
    activateRoom: assign(({ event }) => {
      if (event.type !== "ACTIVATE") return {}
      return {
        roomId: event.roomId,
        panels: loadQuickAccessPanels(event.roomId),
      }
    }),
    deactivateRoom: assign(() => ({
      roomId: null,
      panels: {} as QuickAccessPanelsMap,
    })),
    togglePanel: assign(({ context, event }) => {
      if (event.type !== "TOGGLE") return {}
      const { pluginName } = event
      const existing = context.panels[pluginName]
      return {
        panels: {
          ...context.panels,
          [pluginName]: { open: !existing?.open },
        },
      }
    }),
    closePanel: assign(({ context, event }) => {
      if (event.type !== "CLOSE") return {}
      const existing = context.panels[event.pluginName]
      if (!existing) return {}
      return {
        panels: {
          ...context.panels,
          [event.pluginName]: { open: false },
        },
      }
    }),
    prunePanels: assign(({ context, event }) => {
      if (event.type !== "PRUNE") return {}
      const allowed = new Set(event.enabledPluginNames)
      let changed = false
      const next: QuickAccessPanelsMap = {}
      for (const [name, panel] of Object.entries(context.panels)) {
        if (allowed.has(name)) {
          next[name] = panel
        } else {
          changed = true
        }
      }
      if (!changed) return {}
      return { panels: next }
    }),
  },
}).createMachine({
  id: "quickAccessPanels",
  context: {
    roomId: null,
    panels: {},
  },
  initial: "inactive",
  states: {
    inactive: {
      on: {
        ACTIVATE: {
          target: "active",
          actions: "activateRoom",
        },
      },
    },
    active: {
      on: {
        ACTIVATE: {
          actions: ["activateRoom", "persistPanels"],
        },
        DEACTIVATE: {
          target: "inactive",
          actions: "deactivateRoom",
        },
        TOGGLE: {
          actions: ["togglePanel", "persistPanels"],
        },
        CLOSE: {
          actions: ["closePanel", "persistPanels"],
        },
        PRUNE: {
          actions: ["prunePanels", "persistPanels"],
        },
      },
    },
  },
})

export const queueMachine = setup({
  types: {
    context: {} as QueueContext,
    events: {} as QueueEvent,
  },
  guards: {
    canQueue: () => {
      const isAdmin = getIsAdmin()
      const canDj = canAddToQueue()
      return isAdmin || canDj
    },
  },
  actions: {
    setQueuedTrack: assign(({ event }) => {
      if (event.type === "SEND_TO_QUEUE") {
        return { queuedTrack: event.track }
      }
      return {}
    }),
    sendToQueue: ({ event }) => {
      if (event.type === "SEND_TO_QUEUE") {
        const source = (event.track as { source?: string }).source
        emitToSocket("QUEUE_SONG", source ? { trackId: event.track.id, source } : event.track.id)
      }
    },
    notifyQueued: ({ context, event }) => {
      if (event.type !== "SONG_QUEUED") return
      disarmQueueAddButtonShake()
      const undoTrackId = queuedAddUndoTrackId({
        playbackMode: getCurrentRoom()?.playbackMode,
        queuedItem: event.data,
        queuedTrack: context.queuedTrack,
      })
      toast({
        title: `Added to Queue`,
        description: `${context.queuedTrack?.title} has been added to the queue`,
        status: "success",
        duration: 4000,
        isClosable: true,
        ...(undoTrackId
          ? { action: { label: "Undo", onClick: () => undoQueuedTrack(undoTrackId) } }
          : {}),
      })
    },
    notifyQueueHeld: ({ event, context }) => {
      if (event.type !== "SONG_QUEUE_HELD") return
      disarmQueueAddButtonShake()
      const undoTrackId = context.queuedTrack?.id?.trim() || null
      toast({
        title: "Song saved for your turn",
        description:
          event.data?.message ||
          `${context.queuedTrack?.title ?? "Your song"} will be added when it's your turn`,
        status: "info",
        duration: 5000,
        isClosable: true,
        ...(undoTrackId
          ? { action: { label: "Undo", onClick: () => undoHeldQueue(undoTrackId) } }
          : {}),
      })
    },
    notifyQueueFailure: ({ event }) => {
      if (event.type === "SONG_QUEUE_FAILURE") {
        shakeArmedQueueAddButtonIfPlaybackMissing(event.data?.message)
        toast({
          title: `Track was not added`,
          description: event.data?.message || "Something went wrong",
          status: "error",
          duration: 4000,
          isClosable: true,
        })
      }
    },
    disarmAddButton: () => {
      disarmQueueAddButtonShake()
    },
  },
}).createMachine({
  id: "queue",
  initial: "idle",
  context: {
    queuedTrack: null,
  },
  states: {
    idle: {
      on: {
        SEND_TO_QUEUE: {
          target: "loading",
          actions: ["setQueuedTrack", "sendToQueue"],
          guard: "canQueue",
        },
        SOCKET_OFFLINE: { actions: ["disarmAddButton"] },
      },
    },
    loading: {
      on: {
        SONG_QUEUED: { target: "idle", actions: ["notifyQueued"] },
        SONG_QUEUE_HELD: { target: "idle", actions: ["notifyQueueHeld"] },
        SONG_QUEUE_FAILURE: {
          target: "idle",
          actions: ["notifyQueueFailure"],
        },
        SOCKET_OFFLINE: { target: "idle", actions: ["disarmAddButton"] },
      },
    },
  },
})

export const queueListMachine = setup({
  types: {
    context: {} as QueueListContext,
    events: {} as QueueListEvent,
  },
  actions: {
    subscribe: assign(({ context, self }) => {
      const id = `queueList-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as QueueListEvent),
        eventTypes: ["INIT", "QUEUE_CHANGED"],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    applySocketQueue: assign(({ event }) => {
      if (event.type === "INIT" || event.type === "QUEUE_CHANGED") {
        return {
          queue: event.data.queue ?? [],
          splitKey: event.data.splitKey ?? null,
        }
      }
      return {}
    }),
    resetQueue: assign({
      queue: () => [],
      splitKey: () => null,
      subscriptionId: () => null,
    }),
  },
}).createMachine({
  id: "queueList",
  initial: "idle",
  context: {
    queue: [],
    splitKey: null,
    subscriptionId: null,
  },
  states: {
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["resetQueue"],
        },
        INIT: {
          actions: ["applySocketQueue"],
        },
        QUEUE_CHANGED: {
          actions: ["applySocketQueue"],
        },
      },
    },
  },
})

export const pollMachine = setup({
  types: {
    context: {} as PollContext,
    events: {} as PollEvent,
  },
  guards: {
    isActivePollVote: ({ context, event }) => {
      if (event.type !== "POLL_VOTE_CONFIRMED") return false
      return event.data.pollId === context.activePoll?.id
    },
    isActivePollVoteCast: ({ context, event }) => {
      if (event.type !== "POLL_VOTE_CAST") return false
      return event.data.pollId === context.activePoll?.id
    },
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `poll-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as PollEvent),
        eventTypes: [
          "INIT",
          "ROOM_DATA",
          "POLL_PUBLISHED",
          "POLL_VOTE_CAST",
          "POLL_VOTE_CONFIRMED",
          "POLL_VOTE_FAILED",
          "POLL_CLOSED",
          "POLL_DELETED",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    hydrateFromInit: assign(({ event }) => {
      if (event.type !== "INIT") return {}
      const activePoll = event.data.activePoll ?? null
      return {
        activePoll,
        myVote: event.data.myVote ?? null,
        rollbackVote: null,
        votePending: false,
        totalVotes: initialTotalVotes(activePoll, event.data.totalVotes),
        revealResults: null,
        history: event.data.pollHistory ?? [],
      }
    }),
    applyRoomData: assign(({ context, event }) => {
      if (event.type !== "ROOM_DATA") return {}
      const updates: Partial<PollContext> = {}
      if ("activePoll" in event.data) {
        const activePoll = event.data.activePoll ?? null
        updates.activePoll = activePoll
        updates.totalVotes = initialTotalVotes(activePoll, event.data.totalVotes)
        if (!activePoll) {
          updates.myVote = null
          updates.rollbackVote = null
          updates.votePending = false
          updates.revealResults = null
        }
      }
      if (event.data.pollHistorySince?.length) {
        updates.history = mergeHistory(context.history, event.data.pollHistorySince)
      }
      return updates
    }),
    setPublishedPoll: assign(({ event }) => {
      if (event.type !== "POLL_PUBLISHED") return {}
      const poll = event.data.poll
      return {
        activePoll: poll,
        myVote: null,
        rollbackVote: null,
        votePending: false,
        revealResults: null,
        totalVotes: initialTotalVotes(poll),
      }
    }),
    setVoteCastTotal: assign(({ event }) => {
      if (event.type !== "POLL_VOTE_CAST") return {}
      if (event.data.totalVotes === null) return {}
      return { totalVotes: event.data.totalVotes }
    }),
    confirmVote: assign(({ event }) => {
      if (event.type !== "POLL_VOTE_CONFIRMED") return {}
      return {
        myVote: {
          pollId: event.data.pollId,
          optionId: event.data.optionId,
          votedAt: Date.now(),
        },
        rollbackVote: null,
        votePending: false,
      }
    }),
    rollbackOptimisticVote: assign(({ context, event }) => {
      if (event.type !== "POLL_VOTE_FAILED") return {}
      const message =
        VOTE_FAILURE_MESSAGES[event.data.reason] ?? "Your vote could not be recorded."
      toast({ title: "Vote failed", description: message, type: "error" })
      return {
        myVote: context.rollbackVote,
        rollbackVote: null,
        votePending: false,
      }
    }),
    closeActivePoll: assign(({ context, event }) => {
      if (event.type !== "POLL_CLOSED") return {}
      const entry: PollHistoryEntry = {
        poll: event.data.poll,
        results: event.data.results,
      }
      const history = mergeHistory(context.history, [entry])
      // Queue Theme (and any plugin) can close poll A and publish poll B in one
      // cycle. If B is already active, keep it — only record A's results.
      const isCurrentPoll =
        context.activePoll != null && context.activePoll.id === event.data.poll.id
      if (!isCurrentPoll) {
        return { history }
      }
      return {
        activePoll: event.data.poll,
        myVote: null,
        rollbackVote: null,
        votePending: false,
        totalVotes: null,
        revealResults: event.data.results,
        history,
      }
    }),
    removeFromHistory: assign(({ context, event }) => {
      if (event.type !== "POLL_DELETED") return {}
      return {
        history: context.history.filter((entry) => entry.poll.id !== event.data.pollId),
      }
    }),
    castVoteOptimistic: assign(({ context, event }) => {
      if (event.type !== "CAST_VOTE") return {}
      return {
        rollbackVote: context.myVote,
        votePending: true,
        myVote: {
          pollId: event.data.pollId,
          optionId: event.data.optionId,
          votedAt: Date.now(),
        },
      }
    }),
    emitCastVote: ({ event }) => {
      if (event.type !== "CAST_VOTE") return
      emitToSocket("CAST_POLL_VOTE", {
        pollId: event.data.pollId,
        optionId: event.data.optionId,
      })
    },
    clearReveal: assign(({ context }) => {
      // Reveal timeout must not wipe a poll that replaced the closed one
      // (Queue Theme TRACK_CHANGED: close + immediately create).
      if (context.activePoll?.status === "open") {
        return { revealResults: null }
      }
      return {
        activePoll: null,
        revealResults: null,
      }
    }),
    markAnimationSeen: assign(({ context, event }) => {
      if (event.type !== "MARK_ANIMATION_SEEN") return {}
      const next = new Set(context.seenAnimations)
      next.add(event.data.key)
      return { seenAnimations: next }
    }),
    reset: assign({
      activePoll: () => null,
      myVote: () => null,
      rollbackVote: () => null,
      votePending: () => false,
      totalVotes: () => null,
      revealResults: () => null,
      history: () => [],
      seenAnimations: () => new Set<string>(),
      subscriptionId: () => null,
    }),
  },
}).createMachine({
  id: "poll",
  initial: "idle",
  context: {
    activePoll: null,
    myVote: null,
    rollbackVote: null,
    votePending: false,
    totalVotes: null,
    revealResults: null,
    history: [],
    seenAnimations: new Set<string>(),
    subscriptionId: null,
  },
  states: {
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["reset"],
        },
        INIT: {
          actions: ["hydrateFromInit"],
        },
        ROOM_DATA: {
          actions: ["applyRoomData"],
        },
        POLL_PUBLISHED: {
          actions: ["setPublishedPoll"],
        },
        POLL_VOTE_CAST: {
          guard: "isActivePollVoteCast",
          actions: ["setVoteCastTotal"],
        },
        POLL_VOTE_CONFIRMED: {
          guard: "isActivePollVote",
          actions: ["confirmVote"],
        },
        POLL_VOTE_FAILED: {
          actions: ["rollbackOptimisticVote"],
        },
        POLL_CLOSED: {
          actions: ["closeActivePoll"],
        },
        POLL_DELETED: {
          actions: ["removeFromHistory"],
        },
        CAST_VOTE: {
          actions: ["castVoteOptimistic", "emitCastVote"],
        },
        CLEAR_REVEAL: {
          actions: ["clearReveal"],
        },
        MARK_ANIMATION_SEEN: {
          actions: ["markAnimationSeen"],
        },
      },
    },
  },
})

