export const pluginComponentMachine = setup({
  types: {
    context: {} as PluginComponentContext,
    events: {} as PluginComponentEvent,
    input: {} as PluginComponentInput,
  },
  guards: {
    hasRoomId: ({ context }) => context.roomId !== null,
  },
  actors: {
    fetchComponentState: fromPromise(
      async ({ input }: { input: { roomId: string; pluginName: string } }) => {
        const response = await getPluginComponentState(input.roomId, input.pluginName)
        return response.state
      },
    ),
    pluginSocket: pluginSocketActor,
  },
  actions: {
    setRoomId: assign({
      roomId: ({ event }) => {
        if (event.type === "SET_ROOM_ID") {
          return event.roomId
        }
        return null
      },
    }),
    setStore: assign({
      store: ({ event }) => {
        if (event.type === "xstate.done.actor.fetchComponentState") {
          return event.output
        }
        return {}
      },
      error: null,
    }),
    setError: assign({
      error: ({ event }) => {
        if (event.type === "xstate.error.actor.fetchComponentState") {
          return event.error instanceof Error
            ? event.error
            : new Error("Failed to fetch plugin component state")
        }
        return null
      },
    }),
    updateStoreFromPluginEvent: assign({
      store: ({ context, event }) => {
        if (event.type !== "PLUGIN_EVENT") return context.store

        // Event data already contains the relevant updates (filtered by service)
        const updates: Record<string, unknown> = {}
        for (const key of context.storeKeys) {
          if (key in event.data) {
            updates[key] = event.data[key]
          }
        }

        // Only update if there are matching keys
        if (Object.keys(updates).length === 0) return context.store

        return {
          ...context.store,
          ...updates,
        }
      },
    }),
    updateStore: assign({
      store: ({ context, event }) => {
        if (event.type === "UPDATE_STORE") {
          return { ...context.store, ...event.updates }
        }
        return context.store
      },
    }),
    resetContext: assign({
      roomId: null,
      store: {},
      error: null,
    }),
  },
}).createMachine({
  id: "pluginComponent",
  initial: "idle",
  context: ({ input }) => ({
    pluginName: input.pluginName,
    roomId: null,
    storeKeys: input.storeKeys,
    store: {},
    error: null,
  }),
  states: {
    idle: {
      // Automatically transition to fetching when roomId becomes available
      always: {
        target: "fetching",
        guard: "hasRoomId",
      },
      on: {
        SET_ROOM_ID: {
          actions: "setRoomId",
        },
      },
    },
    fetching: {
      invoke: {
        id: "fetchComponentState",
        src: "fetchComponentState",
        input: ({ context }) => ({
          roomId: context.roomId!,
          pluginName: context.pluginName,
        }),
        onDone: {
          target: "ready",
          actions: "setStore",
        },
        onError: {
          target: "error",
          actions: "setError",
        },
      },
    },
    ready: {
      // Invoke socket actor to listen for plugin events
      invoke: {
        id: "pluginSocket",
        src: "pluginSocket",
        input: ({ context }) => ({
          pluginName: context.pluginName,
          storeKeys: context.storeKeys,
        }),
      },
      on: {
        PLUGIN_EVENT: {
          actions: "updateStoreFromPluginEvent",
        },
        UPDATE_STORE: {
          actions: "updateStore",
        },
        SET_ROOM_ID: {
          // If roomId changes, refetch
          target: "fetching",
          actions: "setRoomId",
        },
        RESET: {
          target: "idle",
          actions: "resetContext",
        },
      },
    },
    error: {
      on: {
        RETRY: "fetching",
        RESET: {
          target: "idle",
          actions: "resetContext",
        },
      },
    },
  },
})

export const playlistMachine = setup({
  types: {
    context: {} as PlaylistContext,
    events: {} as PlaylistEvent,
  },
  actions: {
    subscribe: assign(({ context, self }) => {
      const id = `playlist-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as PlaylistEvent),
        eventTypes: [
          "INIT",
          "PLAYLIST",
          "PLAYLIST_TRACK_ADDED",
          "PLAYLIST_TRACK_UPDATED",
          "PLAYLIST_TRACK_DELETED",
          "ROOM_DATA",
          "ROOM_SETTINGS_UPDATED",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    setData: assign({
      playlist: ({ event }) => {
        if (event.type === "INIT") {
          return event.data.playlist || []
        }
        return []
      },
    }),
    setPlaylist: assign({
      playlist: ({ event }) => {
        if (event.type === "PLAYLIST") {
          return event.data
        }
        return []
      },
    }),
    resetPlaylist: assign({
      playlist: () => [],
      subscriptionId: () => null,
    }),
    addTracksToPlaylist: assign({
      playlist: ({ context, event }) => {
        if (event.type !== "ROOM_DATA") {
          return context.playlist
        }
        // Use track.id as unique key since QueueItem doesn't have timestamp
        return uniqBy(
          (item: QueueItem) => item.track.id,
          [...context.playlist, ...(event.data.playlist || [])],
        )
      },
    }),
    addToPlaylist: assign({
      playlist: ({ context, event }) => {
        if (event.type !== "PLAYLIST_TRACK_ADDED") {
          return context.playlist
        }
        return [...context.playlist, event.data.track]
      },
    }),
    updateTrackInPlaylist: assign({
      playlist: ({ context, event }) => {
        if (event.type !== "PLAYLIST_TRACK_UPDATED") {
          return context.playlist
        }
        const updatedTrack = event.data.track
        // Find and update the track by mediaSource.trackId
        return context.playlist.map((item) =>
          item.mediaSource.trackId === updatedTrack.mediaSource.trackId ? updatedTrack : item,
        )
      },
    }),
    removeFromPlaylist: assign({
      playlist: ({ context, event }) => {
        if (event.type !== "PLAYLIST_TRACK_DELETED") {
          return context.playlist
        }
        // Remove the track by playedAt timestamp
        return context.playlist.filter((item) => item.playedAt !== event.data.playedAt)
      },
    }),
    clearDisabledPluginData: assign({
      playlist: ({ context, event }) => {
        if (event.type !== "ROOM_SETTINGS_UPDATED" || !event.data.pluginConfigs) {
          return context.playlist
        }

        const disabledPlugins = new Set<string>()
        for (const [name, config] of Object.entries(event.data.pluginConfigs)) {
          if ((config as { enabled?: boolean } | undefined)?.enabled !== true) {
            disabledPlugins.add(name)
          }
        }

        if (disabledPlugins.size === 0) return context.playlist

        return context.playlist.map((item) => {
          if (!item.pluginData) return item

          const cleanedPluginData = { ...item.pluginData }
          for (const pluginName of disabledPlugins) {
            delete cleanedPluginData[pluginName]
          }

          if (Object.keys(cleanedPluginData).length === 0) {
            return { ...item, pluginData: undefined }
          }
          return { ...item, pluginData: cleanedPluginData }
        })
      },
    }),
  },
}).createMachine({
  id: "playlist",
  initial: "idle",
  context: {
    playlist: [],
    subscriptionId: null,
  },
  states: {
    // Idle state - not subscribed to socket events
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    // Active state - subscribed to socket events
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["resetPlaylist"],
        },
        INIT: {
          actions: ["setData"],
        },
        PLAYLIST: {
          actions: ["setPlaylist"],
        },
        PLAYLIST_TRACK_ADDED: {
          actions: ["addToPlaylist"],
        },
        PLAYLIST_TRACK_UPDATED: {
          actions: ["updateTrackInPlaylist"],
        },
        PLAYLIST_TRACK_DELETED: {
          actions: ["removeFromPlaylist"],
        },
        ROOM_DATA: {
          actions: ["addTracksToPlaylist"],
        },
        ROOM_SETTINGS_UPDATED: {
          actions: ["clearDisabledPluginData"],
        },
      },
      initial: "collapsed",
      states: {
        expanded: {
          on: {
            TOGGLE_PLAYLIST: "collapsed",
          },
        },
        collapsed: {
          on: {
            TOGGLE_PLAYLIST: "expanded",
          },
        },
      },
    },
  },
})

export const notificationsMachine = setup({
  types: {
    context: {} as NotificationsContext,
    events: {} as NotificationsEvent,
  },
  actions: {
    enterRoom: assign(({ event }) => {
      if (event.type !== "ROOM_ENTERED") return {}
      return {
        roomId: event.roomId,
        items: loadPersistedNotifications(event.roomId),
        location: { surface: null } as NotificationLocation,
        pendingToastIds: [] as string[],
        pendingDismissIds: [] as string[],
      }
    }),
    leaveRoom: assign(() => ({
      roomId: null as string | null,
      items: {} as Record<string, NotificationSpec>,
      location: { surface: null } as NotificationLocation,
      pendingToastIds: [] as string[],
      pendingDismissIds: [] as string[],
    })),
    raiseItem: assign(({ context, event }) => {
      if (event.type !== "RAISE") return {}
      const spec = event.spec

      // Idempotent by id. Allow upgrade: silent store → later live raise with toast
      // (USER_GAME_STATE can race ahead of GIFT_OFFERED / TRADE_INVITE_OFFERED).
      const existing = context.items[spec.id]
      if (existing) {
        if (
          !existing.toast &&
          spec.toast &&
          shouldShowToast(spec, context.location)
        ) {
          const nextItems = { ...context.items, [spec.id]: { ...existing, ...spec } }
          persistItems(context.roomId, nextItems)
          return {
            items: nextItems,
            pendingToastIds: [spec.id],
            pendingDismissIds: [] as string[],
          }
        }
        return { pendingToastIds: [] as string[], pendingDismissIds: [] as string[] }
      }

      // view-type + already at target → drop (no store, no toast).
      if (
        spec.clearOn === "view" &&
        spec.target &&
        locationMatchesTarget(context.location, spec.target)
      ) {
        return { pendingToastIds: [] as string[], pendingDismissIds: [] as string[] }
      }

      const toastIds = shouldShowToast(spec, context.location) ? [spec.id] : []

      // Toast-only (no target): fire toast, do not keep an indicator record.
      if (!spec.target) {
        return {
          pendingToastIds: toastIds,
          pendingDismissIds: [] as string[],
        }
      }

      const nextItems = { ...context.items, [spec.id]: spec }
      persistItems(context.roomId, nextItems)
      return {
        items: nextItems,
        pendingToastIds: toastIds,
        pendingDismissIds: [] as string[],
      }
    }),
    resolveItems: assign(({ context, event }) => {
      if (event.type !== "RESOLVE") return {}
      const next = { ...context.items }
      const dismissIds: string[] = []
      for (const id of event.ids) {
        const existing = next[id]
        if (!existing) {
          // Still dismiss toast if a toast-only raise used this id.
          dismissIds.push(id)
          continue
        }
        if (existing.toast) dismissIds.push(id)
        delete next[id]
      }
      persistItems(context.roomId, next)
      return {
        items: next,
        pendingToastIds: [] as string[],
        pendingDismissIds: dismissIds,
      }
    }),
    reconcileSource: assign(({ context, event }) => {
      if (event.type !== "RECONCILE") return {}
      const keep = new Set(event.keepIds)
      const next = { ...context.items }
      const dismissIds: string[] = []
      for (const [id, spec] of Object.entries(context.items)) {
        if (spec.source !== event.source) continue
        if (keep.has(id)) continue
        if (spec.toast) dismissIds.push(id)
        delete next[id]
      }
      persistItems(context.roomId, next)
      return {
        items: next,
        pendingToastIds: [] as string[],
        pendingDismissIds: dismissIds,
      }
    }),
    applyLocation: assign(({ context, event }) => {
      if (event.type !== "LOCATION_CHANGED") return {}
      const location = event.location
      const next = { ...context.items }
      const dismissIds: string[] = []

      for (const [id, spec] of Object.entries(context.items)) {
        if (!spec.target) continue

        const atTarget = locationMatchesTarget(location, spec.target)
        const atSurface = locationMatchesSurface(location, spec.target)
        const dismissMode = spec.dismissToastOn ?? "target"

        if (spec.clearOn === "view" && atTarget) {
          if (spec.toast) dismissIds.push(id)
          delete next[id]
          continue
        }

        if (spec.toast) {
          if (dismissMode === "target" && atTarget) {
            dismissIds.push(id)
          } else if (dismissMode === "surface" && atSurface) {
            dismissIds.push(id)
          }
        }
      }

      persistItems(context.roomId, next)
      return {
        location,
        items: next,
        pendingToastIds: [] as string[],
        pendingDismissIds: dismissIds,
      }
    }),
    flushToasts: ({ context, event }) => {
      for (const id of context.pendingDismissIds) {
        dismissNotificationToast(id)
      }
      if (event.type === "RAISE") {
        const spec = event.spec
        if (context.pendingToastIds.includes(spec.id) && spec.toast) {
          createNotificationToast({
            id: spec.id,
            toast: spec.toast,
            target: spec.target,
          })
        }
      }
    },
    clearPending: assign({
      pendingToastIds: () => [],
      pendingDismissIds: () => [],
    }),
  },
}).createMachine({
  id: "notifications",
  context: {
    roomId: null,
    location: { surface: null },
    items: {},
    pendingToastIds: [],
    pendingDismissIds: [],
  },
  on: {
    ROOM_ENTERED: { actions: "enterRoom" },
    ROOM_LEFT: { actions: "leaveRoom" },
    RAISE: { actions: ["raiseItem", "flushToasts", "clearPending"] },
    RESOLVE: { actions: ["resolveItems", "flushToasts", "clearPending"] },
    RECONCILE: { actions: ["reconcileSource", "flushToasts", "clearPending"] },
    LOCATION_CHANGED: { actions: ["applyLocation", "flushToasts", "clearPending"] },
  },
})

