export const metadataSourceAuthMachine = setup({
  types: {
    context: {} as MetadataSourceAuthContext,
    events: {} as MetadataSourceAuthEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `metadataSourceAuth-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event),
        eventTypes: ["INIT", "SERVICE_ACCESS_TOKEN_REFRESHED", "SERVICE_AUTHENTICATION_STATUS"],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    assignContext: assign(({ context, event }) => {
      if (event.type !== "INIT") return context
      return {
        userId: event.data?.userId ?? context.userId,
        serviceName: event.data?.serviceName ?? context.serviceName,
      }
    }),
    fetchAuthenticationStatus: ({ context }) => {
      emitToSocket("GET_USER_SERVICE_AUTHENTICATION_STATUS", {
        userId: context.userId,
        serviceName: context.serviceName || "spotify", // Default to spotify for backward compat
      })
    },
    logout: ({ context }) => {
      emitToSocket("LOGOUT_SERVICE", {
        serviceName: context.serviceName || "spotify",
      })
    },
    notifyLogout: ({ context }) => {
      const serviceName = context.serviceName || "service"
      toast({
        title: `${serviceName.charAt(0).toUpperCase() + serviceName.slice(1)} Disconnected`,
        description: `Your ${serviceName} account is now unlinked`,
        status: "success",
      })
    },
    resetContext: assign(() => defaultContext),
  },
  guards: {
    isAuthenticated: ({ event }) => {
      if (event.type === "SERVICE_AUTHENTICATION_STATUS") {
        return event.data.isAuthenticated
      }
      return false
    },
    isUnauthenticated: ({ event }) => {
      if (event.type === "SERVICE_AUTHENTICATION_STATUS") {
        return !event.data.isAuthenticated
      }
      return false
    },
    hasAccessToken: ({ event }) => {
      if (event.type === "SERVICE_ACCESS_TOKEN_REFRESHED") {
        return !!event.data.accessToken
      }
      return false
    },
  },
}).createMachine({
  id: "metadata-source-auth",
  initial: "idle",
  context: defaultContext,
  states: {
    // Idle state - not subscribed to socket events
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    // Active state - subscribed to socket events
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["resetContext"],
        },
        FETCH_STATUS: {
          target: ".loading",
        },
        INIT: {
          actions: ["assignContext"],
        },
        SERVICE_ACCESS_TOKEN_REFRESHED: {
          target: ".authenticated",
          guard: "hasAccessToken",
        },
      },
      initial: "loading",
      states: {
        unauthenticated: {},
        authenticated: {
          on: {
            LOGOUT: {
              target: "unauthenticated",
              actions: ["logout", "notifyLogout"],
            },
          },
        },
        loading: {
          entry: ["fetchAuthenticationStatus"],
          on: {
            SERVICE_AUTHENTICATION_STATUS: [
              {
                target: "authenticated",
                guard: "isAuthenticated",
              },
              {
                target: "unauthenticated",
                guard: "isUnauthenticated",
              },
            ],
          },
        },
      },
    },
  },
})

export const metadataPreferenceMachine = setup({
  types: {
    context: {} as Context,
    events: {} as MetadataPreferenceEvent,
  },
  actions: {
    setAvailableSources: assign({
      availableSources: ({ event }) => {
        if (event.type !== "SET_AVAILABLE_SOURCES") return []
        return event.sources
      },
      // If current preference is not in new sources, reset to first source
      preferredSource: ({ context, event }) => {
        if (event.type !== "SET_AVAILABLE_SOURCES") return context.preferredSource
        const sources = event.sources
        if (context.preferredSource && sources.includes(context.preferredSource)) {
          return context.preferredSource
        }
        return sources[0]
      },
    }),
    setPreferredSource: assign({
      preferredSource: ({ event, context }) => {
        if (event.type !== "SET_PREFERRED_SOURCE") return context.preferredSource
        // Only allow setting if source is available
        if (!context.availableSources.includes(event.source)) {
          return context.preferredSource
        }
        return event.source
      },
    }),
    clearPreference: assign({
      preferredSource: ({ context }) => context.availableSources[0],
    }),
    persistPreference: ({ context }) => {
      if (context.preferredSource) {
        sessionStorage.setItem(STORAGE_KEY, context.preferredSource)
      } else {
        sessionStorage.removeItem(STORAGE_KEY)
      }
    },
    loadPreference: assign({
      preferredSource: ({ context }) => {
        const stored = sessionStorage.getItem(STORAGE_KEY) as MetadataSourceType | null
        // Only use stored preference if it's in available sources
        if (stored && context.availableSources.includes(stored)) {
          return stored
        }
        // Fall back to first available source
        return context.availableSources[0]
      },
    }),
  },
}).createMachine({
  id: "metadataPreference",
  context: {
    availableSources: [],
    preferredSource: undefined,
  },
  entry: ["loadPreference"],
  on: {
    SET_AVAILABLE_SOURCES: {
      actions: ["setAvailableSources", "loadPreference", "persistPreference"],
    },
    SET_PREFERRED_SOURCE: {
      actions: ["setPreferredSource", "persistPreference"],
    },
    CLEAR_PREFERENCE: {
      actions: ["clearPreference", "persistPreference"],
    },
  },
})

export const mediaItemTracksMachine = setup({
  types: {
    context: {} as MediaItemTracksContext,
    events: {} as MediaItemTracksEvent,
  },
  actions: {
    startRequest: assign(({ event }) =>
      event.type === "FETCH"
        ? { mediaKey: event.mediaKey, name: null, tracks: [], error: null }
        : {},
    ),
    sendListTracks: ({ context }) => {
      if (context.mediaKey) {
        emitToSocket("LIST_MEDIA_ITEM_TRACKS", { mediaKey: context.mediaKey })
      }
    },
    setTracks: assign(({ event }) => {
      if (event.type !== "LIST_MEDIA_ITEM_TRACKS_RESULTS") return {}
      return {
        name: event.data?.name ?? null,
        tracks: event.data?.tracks ?? [],
        error: null,
      }
    }),
    setError: assign(({ event }) => {
      if (event.type !== "LIST_MEDIA_ITEM_TRACKS_FAILURE") return {}
      return { tracks: [], error: event.data?.message ?? "Failed to load tracks" }
    }),
    resetContext: assign(() => defaultContext),
  },
  guards: {
    /** Ignore a late payload for an item the viewer already navigated away from. */
    isCurrentMediaKey: ({ context, event }) => {
      if (event.type !== "LIST_MEDIA_ITEM_TRACKS_RESULTS") return false
      const incoming = event.data?.mediaKey
      return incoming == null || incoming === context.mediaKey
    },
  },
}).createMachine({
  id: "mediaItemTracks",
  initial: "idle",
  context: defaultContext,
  on: {
    FETCH: {
      target: ".loading",
      actions: ["startRequest"],
    },
    RESET: {
      target: ".idle",
      actions: ["resetContext"],
    },
  },
  states: {
    idle: {},
    loaded: {},
    failure: {},
    loading: {
      entry: ["sendListTracks"],
      on: {
        LIST_MEDIA_ITEM_TRACKS_RESULTS: {
          target: "loaded",
          guard: "isCurrentMediaKey",
          actions: ["setTracks"],
        },
        LIST_MEDIA_ITEM_TRACKS_FAILURE: {
          target: "failure",
          actions: ["setError"],
        },
      },
    },
  },
})

export const mediaBridgeMachine = setup({
  types: {
    context: {} as MediaBridgeContext,
    events: {} as MediaBridgeEvent,
  },
  actors: {
    statusPoll: statusPollLogic,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `mediaBridge-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as MediaBridgeEvent),
        eventTypes: [
          "MEDIA_BRIDGE_STATUS_CHANGED",
          "LINK_MEDIA_BRIDGE_SUCCESS",
          "LINK_MEDIA_BRIDGE_FAILURE",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    fetchStatus: () => {
      emitToSocket("GET_MEDIA_BRIDGE_STATUS", {})
    },
    requestLink: () => {
      emitToSocket("LINK_MEDIA_BRIDGE", {})
    },
    clearError: assign({ lastError: null }),
    assignDaemonId: assign(({ event }) => {
      if (event.type !== "LINK_MEDIA_BRIDGE_SUCCESS") return {}
      return { daemonId: event.data?.daemonId ?? null, lastError: null }
    }),
    assignServicesFromStatus: assign(({ event }) => {
      if (event.type !== "MEDIA_BRIDGE_STATUS_CHANGED") return {}
      if (event.data?.services === undefined) return {}
      return { services: event.data.services }
    }),
    clearServices: assign({ services: null }),
    assignLinkFailure: assign(({ event }) => {
      if (event.type !== "LINK_MEDIA_BRIDGE_FAILURE") return {}
      return {
        lastError:
          event.data?.message ??
          "No Media Bridge is online. Start the bridge daemon on the DJ Mac, then try again.",
      }
    }),
    notifyLinkSuccess: () => {
      toast({
        title: "Media Bridge linked",
        description: "The DJ Mac bridge is connected to this room.",
        type: "success",
        duration: 4000,
      })
    },
    notifyLinkFailure: ({ context }) => {
      toast({
        title: "Couldn't link Media Bridge",
        description:
          context.lastError ??
          "No Media Bridge is online. Start the bridge daemon on the DJ Mac, then try again.",
        type: "error",
        duration: 8000,
      })
    },
    resetContext: assign(() => defaultContext),
  },
  guards: {
    isConnectedStatus: ({ event }) =>
      event.type === "MEDIA_BRIDGE_STATUS_CHANGED" && Boolean(event.data?.connected),
    isDisconnectedStatus: ({ event }) =>
      event.type === "MEDIA_BRIDGE_STATUS_CHANGED" && !event.data?.connected,
  },
}).createMachine({
  id: "mediaBridge",
  initial: "idle",
  context: defaultContext,
  states: {
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    active: {
      entry: ["subscribe", "fetchStatus"],
      exit: ["unsubscribe", "resetContext"],
      invoke: {
        id: "statusPoll",
        src: "statusPoll",
      },
      on: {
        DEACTIVATE: "idle",
        POLL: { actions: ["fetchStatus"] },
      },
      initial: "unknown",
      states: {
        unknown: {
          on: {
            MEDIA_BRIDGE_STATUS_CHANGED: [
              {
                target: "connected",
                guard: "isConnectedStatus",
                actions: ["assignServicesFromStatus"],
              },
              {
                target: "disconnected",
                guard: "isDisconnectedStatus",
                actions: ["clearServices"],
              },
            ],
            LINK: { target: "linking", actions: ["clearError", "requestLink"] },
          },
        },
        disconnected: {
          on: {
            MEDIA_BRIDGE_STATUS_CHANGED: [
              {
                target: "connected",
                guard: "isConnectedStatus",
                actions: ["assignServicesFromStatus"],
              },
            ],
            LINK: { target: "linking", actions: ["clearError", "requestLink"] },
          },
        },
        connected: {
          on: {
            MEDIA_BRIDGE_STATUS_CHANGED: [
              {
                target: "disconnected",
                guard: "isDisconnectedStatus",
                actions: ["clearServices"],
              },
              { actions: ["assignServicesFromStatus"] },
            ],
          },
        },
        linking: {
          on: {
            LINK_MEDIA_BRIDGE_SUCCESS: {
              target: "connected",
              actions: ["assignDaemonId", "notifyLinkSuccess"],
            },
            LINK_MEDIA_BRIDGE_FAILURE: {
              target: "disconnected",
              actions: ["assignLinkFailure", "notifyLinkFailure", "clearServices"],
            },
            MEDIA_BRIDGE_STATUS_CHANGED: [
              {
                target: "connected",
                guard: "isConnectedStatus",
                actions: ["assignServicesFromStatus"],
              },
              {
                target: "disconnected",
                guard: "isDisconnectedStatus",
                actions: ["clearServices"],
              },
            ],
          },
        },
      },
    },
  },
})

export const lobbyMachine = setup({
  types: {
    context: {} as LobbyContext,
    events: {} as LobbyEvent,
  },
  actors: {
    fetchRooms: fetchRoomsLogic,
    socketSubscription: socketSubscriptionLogic,
  },
  actions: {
    setRooms: assign(({ event }) => {
      if (event.type !== "ROOMS_LOADED") return {}
      return {
        rooms: event.data.rooms,
        error: null,
      }
    }),
    setError: assign(({ event }) => {
      if (event.type !== "FETCH_ERROR") return {}
      return {
        error: event.error,
      }
    }),
    updateRoom: assign(({ context, event }) => {
      if (event.type !== "ROOM_UPDATED") return context
      const { roomId, ...updates } = event.data
      return {
        rooms: context.rooms.map((room) => (room.id === roomId ? { ...room, ...updates } : room)),
      }
    }),
    addOrUpdateRoom: assign(({ context, event }) => {
      if (event.type !== "ROOM_ADDED") return context
      const { roomId, ...roomData } = event.data
      const exists = context.rooms.some((r) => r.id === roomId)
      if (exists) {
        return {
          rooms: context.rooms.map((r) =>
            r.id === roomId ? { ...r, ...roomData } : r,
          ),
        }
      }
      return {
        rooms: [
          ...context.rooms,
          { id: roomId, ...roomData } as LobbyRoom,
        ],
      }
    }),
    removeRoom: assign(({ context, event }) => {
      if (event.type !== "ROOM_REMOVED") return context
      return {
        rooms: context.rooms.filter((r) => r.id !== event.data.roomId),
      }
    }),
  },
}).createMachine({
  id: "lobby",
  initial: "idle",
  context: {
    rooms: [],
    error: null,
  },
  states: {
    idle: {
      on: {
        CONNECT: "connecting",
      },
    },
    connecting: {
      invoke: {
        id: "socketSubscription",
        src: "socketSubscription",
      },
      entry: "fetchRoomsOnConnect",
      always: "connected",
    },
    connected: {
      invoke: {
        id: "socketSubscription",
        src: "socketSubscription",
      },
      initial: "loading",
      on: {
        DISCONNECT: "disconnecting",
        ROOM_UPDATED: {
          actions: "updateRoom",
        },
        ROOM_ADDED: {
          actions: "addOrUpdateRoom",
        },
        ROOM_REMOVED: {
          actions: "removeRoom",
        },
        REFETCH: ".loading",
      },
      states: {
        loading: {
          invoke: {
            id: "fetchRooms",
            src: "fetchRooms",
            onDone: {
              target: "ready",
              actions: assign({
                rooms: ({ event }) =>
                  (Array.isArray(event.output?.rooms) ? event.output.rooms : []) as LobbyRoom[],
                error: null,
              }),
            },
            onError: {
              target: "error",
              actions: assign({
                error: ({ event }) => event.error as RoomError,
              }),
            },
          },
        },
        ready: {},
        error: {
          on: {
            REFETCH: "loading",
          },
        },
      },
    },
    disconnecting: {
      always: "idle",
    },
  },
})

