export const liveTransportMachine = setup({
  types: {
    context: {} as {
      transport: "webrtc" | "hls" | "none"
      hasWhepUrl: boolean
    },
    events: {} as LiveTransportEvent,
    input: {} as { hasWhepUrl: boolean },
  },
  guards: {
    hasWhep: ({ context }) => context.hasWhepUrl,
  },
  actions: {
    markWebRTC: assign({ transport: "webrtc" as const }),
    markHLS: assign({ transport: "hls" as const }),
  },
}).createMachine({
  id: "liveTransport",
  initial: "deciding",
  context: ({ input }) => ({
    transport: "none" as const,
    hasWhepUrl: input.hasWhepUrl,
  }),
  states: {
    deciding: {
      always: [
        { target: "webrtc", guard: "hasWhep" },
        { target: "hls" },
      ],
    },

    webrtc: {
      initial: "signaling",
      states: {
        signaling: {
          entry: log("[transport] webrtc.signaling"),
          on: {
            WHEP_OK: { target: "iceConnecting", actions: log("[transport] WHEP_OK → iceConnecting") },
            WHEP_FAILED: { target: "#liveTransport.webrtcFailed", actions: log("[transport] WHEP_FAILED → webrtcFailed") },
            TRACK_RECEIVED: { actions: log("[transport] track received (during signaling)") },
          },
        },

        iceConnecting: {
          entry: log("[transport] webrtc.iceConnecting"),
          after: { 10000: { target: "#liveTransport.webrtcFailed", actions: log("[transport] ICE timeout → webrtcFailed") } },
          on: {
            ICE_CONNECTED: { target: "playing", actions: log("[transport] ICE_CONNECTED → playing") },
            ICE_COMPLETED: { target: "playing", actions: log("[transport] ICE_COMPLETED → playing") },
            TRACK_RECEIVED: { target: "playing", actions: log("[transport] TRACK_RECEIVED → playing") },
            ICE_FAILED: { target: "#liveTransport.webrtcFailed", actions: log("[transport] ICE_FAILED → webrtcFailed") },
          },
        },

        playing: {
          entry: ["markWebRTC", log("[transport] webrtc.playing — WebRTC active")],
          on: {
            ICE_DISCONNECTED: { target: "disconnectedGrace", actions: log("[transport] ICE_DISCONNECTED → grace period") },
            ICE_FAILED: { target: "#liveTransport.webrtcFailed", actions: log("[transport] ICE_FAILED while playing → webrtcFailed") },
          },
        },

        disconnectedGrace: {
          entry: log("[transport] webrtc.disconnectedGrace (5s before giving up)"),
          after: { 5000: { target: "#liveTransport.webrtcFailed", actions: log("[transport] grace expired → webrtcFailed") } },
          on: {
            ICE_CONNECTED: { target: "playing", actions: log("[transport] ICE recovered → playing") },
            ICE_COMPLETED: { target: "playing", actions: log("[transport] ICE recovered (completed) → playing") },
            ICE_FAILED: { target: "#liveTransport.webrtcFailed", actions: log("[transport] ICE_FAILED during grace → webrtcFailed") },
          },
        },
      },
    },

    webrtcFailed: {
      entry: log("[transport] WebRTC failed, falling back to HLS"),
      always: "hls",
    },

    hls: {
      entry: "markHLS",
    },
  },
})

export const inventoryPeekMachine = setup({
  types: {
    context: {} as InventoryPeekContext,
    events: {} as InventoryPeekEvent,
  },
  actions: {
    setTarget: assign({
      targetUserId: ({ event }) => (event.type === "PEEK" ? event.targetUserId : null),
      items: () => [],
      error: () => null,
    }),
    reset: assign({
      targetUserId: () => null,
      items: () => [],
      error: () => null,
    }),
    setItems: assign({
      items: ({ event }) =>
        event.type === "RESULT" && event.data.success ? (event.data.items ?? []) : [],
      error: () => null,
    }),
    setDenied: assign({
      items: () => [],
      error: ({ event }) =>
        event.type === "RESULT" && !event.data.success
          ? (event.data.message ?? "Could not peek inventory.")
          : null,
    }),
    setTimedOut: assign({
      items: () => [],
      error: () => "Peek timed out.",
    }),
  },
}).createMachine({
  id: "inventoryPeek",
  context: {
    targetUserId: null,
    items: [],
    error: null,
  },
  initial: "idle",
  states: {
    idle: {
      on: { PEEK: { target: "loading", actions: "setTarget" } },
    },
    loading: {
      on: {
        // A second PEEK restarts the request against the new target.
        PEEK: { target: "loading", actions: "setTarget", reenter: true },
        RESULT: [
          {
            target: "error",
            guard: ({ event }) => !event.data.success,
            actions: "setDenied",
          },
          {
            // Authorized, but they are carrying nothing — a distinct outcome
            // from a denied peek, and never a half-filled `loaded`.
            target: "empty",
            guard: ({ event }) => (event.data.items ?? []).length === 0,
            actions: "setItems",
          },
          { target: "loaded", actions: "setItems" },
        ],
        TIMEOUT: { target: "error", actions: "setTimedOut" },
        CLOSE: { target: "idle", actions: "reset" },
      },
    },
    loaded: {
      on: {
        PEEK: { target: "loading", actions: "setTarget" },
        CLOSE: { target: "idle", actions: "reset" },
      },
    },
    empty: {
      on: {
        PEEK: { target: "loading", actions: "setTarget" },
        CLOSE: { target: "idle", actions: "reset" },
      },
    },
    error: {
      on: {
        PEEK: { target: "loading", actions: "setTarget" },
        CLOSE: { target: "idle", actions: "reset" },
      },
    },
  },
})

export const gameStateNewPluginTabsMachine = setup({
  types: {
    context: {} as GameStateNewPluginTabsMachineContext,
    events: {} as GameStateNewPluginTabsEvent,
    input: {} as { roomId: string | null },
  },
  actions: {
    setRoomAndResetBaseline: assign(({ event }) => {
      if (event.type !== "ROOM_CHANGED") {
        return {}
      }
      return {
        roomId: event.roomId,
        previousObservedIds: null,
      }
    }),
    /**
     * First non-empty tab list while still in baseline.
     * - `previousObservedIds === null`: first sync — record snapshot, do not raise.
     * - `previousObservedIds.length === 0`: we already observed `[]` — raise as newly offered.
     */
    establishFromBaseline: assign(({ context, event }) => {
      if (event.type !== "PLUGIN_TABS_CHANGED") {
        return {}
      }
      const sorted = sortIds(event.ids)
      const prev = context.previousObservedIds

      if (prev === null) {
        return { previousObservedIds: sorted }
      }

      if (prev.length === 0) {
        for (const id of sorted) {
          raisePluginTabAttention(id)
        }
        return { previousObservedIds: sorted }
      }

      return { previousObservedIds: sorted }
    }),
    mergeNewPluginTabs: assign(({ context, event }) => {
      if (event.type !== "PLUGIN_TABS_CHANGED") {
        return {}
      }
      const sorted = sortIds(event.ids)
      const prev = context.previousObservedIds ?? []
      const added = sorted.filter((id) => !prev.includes(id))
      const removed = prev.filter((id) => !sorted.includes(id))
      for (const id of added) {
        raisePluginTabAttention(id)
      }
      resolvePluginTabAttention(removed)
      return { previousObservedIds: sorted }
    }),
    raiseTabAttention: ({ context, event }) => {
      if (event.type !== "TAB_ATTENTION") return
      const tabId = event.tabId
      if (!tabId) return
      // Only badge tabs we have already observed (or will prune if tab disappears).
      const observed = context.previousObservedIds
      if (observed != null && observed.length > 0 && !observed.includes(tabId)) {
        return
      }
      raisePluginTabAttention(tabId)
    },
    pruneToEmpty: assign(({ event }) => {
      if (event.type !== "PLUGIN_TABS_CHANGED") {
        return {}
      }
      // Resolve any notifications for tabs that disappeared with the empty list.
      // We don't know prior ids here beyond previousObservedIds — handled in merge
      // when going non-empty→empty via mergeNewPluginTabs when not empty guard.
      return { previousObservedIds: [] as string[] }
    }),
    resolveAllObserved: ({ context }) => {
      const prev = context.previousObservedIds
      if (prev && prev.length > 0) {
        resolvePluginTabAttention(prev)
      }
    },
  },
  guards: {
    isEmptyPluginTabs: ({ event }) =>
      event.type === "PLUGIN_TABS_CHANGED" && event.ids.length === 0,
    isNonEmptyPluginTabs: ({ event }) =>
      event.type === "PLUGIN_TABS_CHANGED" && event.ids.length > 0,
  },
}).createMachine({
  id: "gameStateNewPluginTabs",
  context: ({ input }) => ({
    roomId: input.roomId,
    previousObservedIds: null,
  }),
  initial: "baseline",
  states: {
    /**
     * Wait until we see a non-empty plugin tab list once so an empty initial payload
     * does not treat every later tab as “new”.
     */
    baseline: {
      on: {
        ROOM_CHANGED: {
          actions: "setRoomAndResetBaseline",
          target: "baseline",
          reenter: true,
        },
        PLUGIN_TABS_CHANGED: [
          {
            guard: "isEmptyPluginTabs",
            actions: ["resolveAllObserved", "pruneToEmpty"],
          },
          {
            guard: "isNonEmptyPluginTabs",
            target: "tracking",
            actions: ["establishFromBaseline"],
          },
        ],
        TAB_ATTENTION: {
          actions: ["raiseTabAttention"],
        },
      },
    },
    tracking: {
      on: {
        ROOM_CHANGED: {
          actions: "setRoomAndResetBaseline",
          target: "baseline",
        },
        PLUGIN_TABS_CHANGED: [
          {
            guard: "isEmptyPluginTabs",
            actions: ["resolveAllObserved", "pruneToEmpty"],
            target: "baseline",
          },
          {
            actions: ["mergeNewPluginTabs"],
          },
        ],
        TAB_ATTENTION: {
          actions: ["raiseTabAttention"],
        },
      },
    },
  },
})

export const gameStateNavMachine = setup({
  types: {
    context: {} as GameStateNavContext,
    events: {} as GameStateNavEvent,
  },
  actions: {
    stopPreview: () => {
      stopTrackPreview()
    },
    setActiveTab: assign(({ context, event }) => {
      if (event.type !== "SET_ACTIVE_TAB") return {}
      return {
        activeTabId: event.tabId,
        // Picking a tab lands on its root, including re-picking the tab already
        // being viewed from inside one of its detail frames.
        stacks: { ...context.stacks, [event.tabId]: [] },
      }
    }),
    pushDetail: assign(({ context, event }) => {
      if (event.type !== "PUSH_DETAIL") return {}
      return {
        stacks: {
          ...context.stacks,
          [context.activeTabId]: [...activeStack(context), event.frame],
        },
      }
    }),
    openDetailOnTab: assign(({ context, event }) => {
      if (event.type !== "OPEN_DETAIL_ON_TAB") return {}
      return {
        activeTabId: event.tabId,
        stacks: { ...context.stacks, [event.tabId]: [event.frame] },
      }
    }),
    popToIndex: assign(({ context }) => ({
      stacks: { ...context.stacks, [context.activeTabId]: [] },
    })),
    dropInventoryDetail: assign(({ context, event }) => {
      if (event.type !== "DROP_INVENTORY_DETAIL") return {}
      return {
        stacks: dropInventoryItemFrames(
          context.stacks,
          (frame) => frame.kind === "item" && frame.inventoryItemId === event.itemId,
        ),
      }
    }),
    reconcileInventoryDetails: assign(({ context, event }) => {
      if (event.type !== "RECONCILE_INVENTORY_DETAILS") return {}
      const held = new Set(event.heldItemIds)
      return {
        stacks: dropInventoryItemFrames(
          context.stacks,
          (frame) =>
            frame.kind === "item" &&
            frame.inventoryItemId != null &&
            !held.has(frame.inventoryItemId),
        ),
      }
    }),
    finishTradeSession: assign(({ context, event }) => {
      if (event.type !== "TRADE_SESSION_COMPLETED") return {}
      const stacks = { ...context.stacks, [TRADES_GIFTS_TAB]: [] }
      if (!event.goToInventory) return { stacks }
      return {
        activeTabId: GAME_STATE_DEFAULT_TAB,
        stacks: { ...stacks, [GAME_STATE_DEFAULT_TAB]: [] },
      }
    }),
    setAvailableTabs: assign(({ event }) => {
      if (event.type !== "SET_AVAILABLE_TABS") return {}
      return { availableTabIds: event.tabIds }
    }),
    assignSessionSnapshot: assign(({ event }) => {
      if (event.type !== "SESSION_SNAPSHOT") return {}
      return { allowTrading: event.allowTrading, activeTrade: event.activeTrade }
    }),
    snapToInventory: assign(({ context }) => ({
      activeTabId: GAME_STATE_DEFAULT_TAB,
      stacks: { ...context.stacks, [GAME_STATE_DEFAULT_TAB]: [] },
    })),
    snapIfUnavailable: assign(({ context }) => {
      if (!tabMissingFrom(context.activeTabId, context.availableTabIds)) return {}
      return {
        activeTabId: GAME_STATE_DEFAULT_TAB,
        stacks: { ...context.stacks, [GAME_STATE_DEFAULT_TAB]: [] },
      }
    }),
    resetContext: assign(() => emptyContext()),
    syncChildrenActive: ({ context }) => {
      if (tabMissingFrom(context.activeTabId, context.availableTabIds)) {
        syncChildren(context, true, { tabId: GAME_STATE_DEFAULT_TAB, frame: null })
        return
      }
      syncChildren(context, true)
    },
    syncChildrenAfterTab: ({ context, event }) => {
      if (event.type !== "SET_ACTIVE_TAB") return
      syncChildren(context, true, { tabId: event.tabId, frame: null })
    },
    syncChildrenAfterFinishTrade: ({ context, event, self }) => {
      if (event.type !== "TRADE_SESSION_COMPLETED") return
      if (!self.getSnapshot().matches("active")) return
      if (event.goToInventory) {
        syncChildren(context, true, { tabId: GAME_STATE_DEFAULT_TAB, frame: null })
        return
      }
      const frame =
        context.activeTabId === TRADES_GIFTS_TAB ? null : currentDetailFrame(context)
      syncChildren(context, true, { frame })
    },
    syncChildrenAfterPush: ({ context, event }) => {
      if (event.type !== "PUSH_DETAIL") return
      syncChildren(context, true, { frame: event.frame })
    },
    syncChildrenAfterOpenDetail: ({ context, event, self }) => {
      if (event.type !== "OPEN_DETAIL_ON_TAB") return
      if (!self.getSnapshot().matches("active")) return
      syncChildren(context, true, { tabId: event.tabId, frame: event.frame })
    },
    syncChildrenAfterSnap: ({ context, self }) => {
      if (!self.getSnapshot().matches("active")) return
      syncChildren(context, true, { tabId: GAME_STATE_DEFAULT_TAB, frame: null })
    },
    syncChildrenIfActive: ({ context, event, self }) => {
      if (!self.getSnapshot().matches("active")) return
      const allowTrading =
        event.type === "SESSION_SNAPSHOT" ? event.allowTrading : context.allowTrading
      const activeTrade =
        event.type === "SESSION_SNAPSHOT" ? event.activeTrade : context.activeTrade
      try {
        syncGameStateChildActors({
          navActive: true,
          tabId: context.activeTabId,
          frame: currentDetailFrame(context),
          allowTrading,
          activeTrade,
        })
      } catch (err) {
        console.error("[gameStateNav] child-actor sync failed", err)
      }
    },
    deactivateChildren: ({ context }) => {
      syncChildren(context, false)
    },
    /** Drop the list on close so ACTIVATE cannot snap using a stale set (e.g. trading
     * enabled after a prior open, or Accept-toast deep-link before the surface reports). */
    clearAvailableTabs: assign({
      availableTabIds: () => null as string[] | null,
    }),
  },
  guards: {
    hasDetailFrame: ({ context }) => activeStack(context).length > 0,
    /** Uses the incoming list so the guard is true before `setAvailableTabs` assigns. */
    incomingTabsOmitCurrent: ({ context, event }) =>
      event.type === "SET_AVAILABLE_TABS" &&
      tabMissingFrom(context.activeTabId, event.tabIds),
  },
}).createMachine({
  id: "gameStateNav",
  context: emptyContext(),
  initial: "inactive",
  on: {
    // Deep-link tab/frame before the modal opens; rendered on ACTIVATE.
    SET_ACTIVE_TAB: {
      actions: "setActiveTab",
    },
    TRADE_SESSION_COMPLETED: {
      actions: ["stopPreview", "finishTradeSession"],
    },
    OPEN_DETAIL_ON_TAB: {
      actions: ["stopPreview", "openDetailOnTab", "syncChildrenAfterOpenDetail"],
    },
    DROP_INVENTORY_DETAIL: {
      actions: ["dropInventoryDetail", "syncChildrenIfActive"],
    },
    RECONCILE_INVENTORY_DETAILS: {
      actions: ["reconcileInventoryDetails", "syncChildrenIfActive"],
    },
    SET_AVAILABLE_TABS: [
      {
        guard: "incomingTabsOmitCurrent",
        actions: ["setAvailableTabs", "snapToInventory", "syncChildrenAfterSnap"],
      },
      { actions: "setAvailableTabs" },
    ],
    SESSION_SNAPSHOT: {
      actions: ["assignSessionSnapshot", "syncChildrenIfActive"],
    },
    RESET: {
      target: ".inactive",
      actions: ["deactivateChildren", "resetContext"],
    },
  },
  states: {
    inactive: {
      on: {
        ACTIVATE: "active",
      },
    },
    active: {
      entry: ["snapIfUnavailable", "syncChildrenActive"],
      exit: ["deactivateChildren", "clearAvailableTabs"],
      initial: "index",
      on: {
        // Leaves the frame in place: clearing it here would swap the modal back
        // to the tab index while it is still animating out. Reopening resumes
        // the detail view, the way the selected tab already persists.
        DEACTIVATE: "inactive",
        SET_ACTIVE_TAB: {
          actions: ["setActiveTab", "syncChildrenAfterTab"],
        },
        TRADE_SESSION_COMPLETED: {
          actions: ["stopPreview", "finishTradeSession", "syncChildrenAfterFinishTrade"],
        },
        // Detail-to-detail keeps the state, so the exit action below never runs.
        PUSH_DETAIL: {
          actions: ["stopPreview", "pushDetail", "syncChildrenAfterPush"],
        },
        POP_TO_INDEX: {
          actions: "popToIndex",
        },
      },
      states: {
        index: {
          always: {
            target: "detail",
            guard: "hasDetailFrame",
          },
        },
        detail: {
          exit: "stopPreview",
          always: {
            target: "index",
            guard: not("hasDetailFrame"),
          },
        },
      },
    },
  },
})

export const gameSessionMachine = setup({
  types: {
    context: {} as GameSessionContext,
    events: {} as GameSessionEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `gameSession-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as GameSessionEvent),
        eventTypes: [
          "INIT",
          "GAME_SESSION_STARTED",
          "GAME_SESSION_ENDED",
          "GAME_SESSION_CONFIG_UPDATED",
          "GAME_ECONOMY_SCALE_CHANGED",
          "USER_GAME_STATE",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    /**
     * Seed from login INIT (AuthService includes `activeGameSession`). Do not call
     * GET_MY_GAME_STATE on entry — that runs before LOGIN and has no `socket.data.roomId`.
     */
    setSessionFromInit: assign(({ event }) => {
      if (event.type !== "INIT") return {}
      const s = event.data.activeGameSession ?? null
      return {
        activeSessionId: s?.id ?? null,
        activeSessionName: s?.config?.name ?? null,
        economy: s?.config?.economy ?? null,
      }
    }),
    setSessionFromStarted: assign(({ event }) => {
      if (event.type !== "GAME_SESSION_STARTED") return {}
      return {
        activeSessionId: event.data.sessionId,
        activeSessionName: event.data.config?.name ?? null,
        economy: event.data.config?.economy ?? null,
      }
    }),
    setSessionFromStatus: assign(({ event }) => {
      if (event.type !== "USER_GAME_STATE") return {}
      const s = event.data.session
      return {
        activeSessionId: s?.id ?? null,
        activeSessionName: s?.config?.name ?? null,
        economy: s?.config?.economy ?? null,
      }
    }),
    setSessionFromConfigUpdated: assign(({ event }) => {
      if (event.type !== "GAME_SESSION_CONFIG_UPDATED") return {}
      return {
        activeSessionId: event.data.sessionId,
        activeSessionName: event.data.config?.name ?? null,
        economy: event.data.config?.economy ?? null,
      }
    }),
    mergeEconomyScale: assign(({ event, context }) => {
      if (event.type !== "GAME_ECONOMY_SCALE_CHANGED") return {}
      const prev = resolveEconomy(context.economy)
      return {
        economy: {
          ...prev,
          costScale: event.data.costScale,
          earnScale: event.data.earnScale,
          updatedBy: event.data.updatedBy,
          reason: event.data.reason,
        },
      }
    }),
    clearSession: assign({
      activeSessionId: () => null,
      activeSessionName: () => null,
      economy: () => null,
    }),
    reset: assign({
      subscriptionId: () => null,
      activeSessionId: () => null,
      activeSessionName: () => null,
      economy: () => null,
    }),
  },
}).createMachine({
  id: "gameSession",
  initial: "idle",
  context: {
    subscriptionId: null,
    activeSessionId: null,
    activeSessionName: null,
    economy: null,
  },
  states: {
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["reset"],
        },
        INIT: {
          actions: ["setSessionFromInit"],
        },
        GAME_SESSION_STARTED: {
          actions: ["setSessionFromStarted"],
        },
        GAME_SESSION_ENDED: {
          actions: ["clearSession"],
        },
        GAME_SESSION_CONFIG_UPDATED: {
          actions: ["setSessionFromConfigUpdated"],
        },
        GAME_ECONOMY_SCALE_CHANGED: {
          actions: ["mergeEconomyScale"],
        },
        USER_GAME_STATE: {
          actions: ["setSessionFromStatus"],
        },
      },
    },
  },
})

export function createFeedbackResponseFormMachine(input: FeedbackResponseFormInput) {
  const { onSave } = input
  const allowCommentWithoutVote = input.allowCommentWithoutVote ?? false

  return setup({
    types: {
      context: {} as FeedbackResponseFormContext,
      events: {} as FeedbackResponseFormEvent,
    },
    actions: {
      hydrate: assign(({ event }) => {
        if (event.type !== "HYDRATE") return {}
        return {
          vote: event.vote,
          comment: event.comment,
          savedVote: event.vote,
          savedComment: event.comment,
          savePending: false,
          rollbackVote: null,
          rollbackComment: null,
        }
      }),
      setVoteOptimistic: assign(({ context, event }) => {
        if (event.type !== "SET_VOTE") return {}
        return {
          rollbackVote: context.vote,
          rollbackComment: context.comment,
          vote: event.vote,
          savePending: true,
        }
      }),
      emitVoteSave: ({ context, event }) => {
        if (event.type !== "SET_VOTE") return
        onSave({ topicId: context.topicId, vote: event.vote })
      },
      setCommentDraft: assign(({ event }) => {
        if (event.type !== "SET_COMMENT") return {}
        return { comment: event.comment }
      }),
      emitCommentSave: ({ context }) => {
        onSave({ topicId: context.topicId, comment: context.comment })
      },
      markCommentSavePending: assign({
        savePending: true,
        rollbackVote: ({ context }) => context.vote,
        rollbackComment: ({ context }) => context.comment,
      }),
      syncSaved: assign(({ event }) => {
        if (event.type !== "SYNC_SAVED") return {}
        return {
          vote: event.vote,
          comment: event.comment,
          savedVote: event.vote,
          savedComment: event.comment,
          savePending: false,
          rollbackVote: null,
          rollbackComment: null,
        }
      }),
      rollback: assign(({ context }) => ({
        vote: context.rollbackVote ?? context.savedVote,
        comment: context.rollbackComment ?? context.savedComment,
        savePending: false,
        rollbackVote: null,
        rollbackComment: null,
      })),
      flushIfDirty: ({ context }) => {
        if (context.comment === context.savedComment) return
        if (!context.allowCommentWithoutVote && context.vote == null) return
        // Avoid creating an empty general response with no vote.
        if (
          context.allowCommentWithoutVote &&
          context.vote == null &&
          context.savedVote == null &&
          context.comment === "" &&
          context.savedComment === ""
        ) {
          return
        }
        onSave({ topicId: context.topicId, comment: context.comment })
      },
    },
    guards: {
      canComment: ({ context }) =>
        context.vote != null || context.allowCommentWithoutVote,
      commentDirty: ({ context }) => context.comment !== context.savedComment,
    },
  }).createMachine({
    id: `feedback-response-form-${input.topicId}`,
    context: {
      topicId: input.topicId,
      vote: input.vote,
      comment: input.comment,
      savedVote: input.vote,
      savedComment: input.comment,
      savePending: false,
      rollbackVote: null,
      rollbackComment: null,
      allowCommentWithoutVote,
    },
    initial: "idle",
    on: {
      HYDRATE: { actions: "hydrate" },
      SYNC_SAVED: { actions: "syncSaved" },
      SAVE_FAILED: { actions: "rollback" },
    },
    states: {
      idle: {
        on: {
          SET_VOTE: {
            actions: ["setVoteOptimistic", "emitVoteSave"],
          },
          SET_COMMENT: {
            guard: "canComment",
            target: "typing",
            actions: ["setCommentDraft"],
          },
          FLUSH: {
            guard: "commentDirty",
            actions: ["markCommentSavePending", "flushIfDirty"],
          },
        },
      },
      typing: {
        on: {
          SET_VOTE: {
            actions: ["setVoteOptimistic", "emitVoteSave"],
          },
          SET_COMMENT: {
            target: "typing",
            reenter: true,
            actions: ["setCommentDraft"],
          },
          FLUSH: {
            target: "idle",
            actions: ["markCommentSavePending", "flushIfDirty"],
          },
        },
        after: {
          [COMMENT_DEBOUNCE_MS]: {
            target: "idle",
            actions: ["markCommentSavePending", "emitCommentSave"],
          },
        },
      },
    },
  })
}

export const feedbackMachine = setup({
  types: {
    context: {} as FeedbackContext,
    events: {} as FeedbackEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `feedback-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (ev) => self.send(ev as FeedbackEvent),
        eventTypes: [
          "INIT",
          "ROOM_DATA",
          "FEEDBACK_TOPICS_CHANGED",
          "FEEDBACK_RESPONSE_SAVED",
          "FEEDBACK_RESPONSE_FAILED",
          "FEEDBACK_INBOX",
          "FEEDBACK_INBOX_UPDATED",
        ],
      })
      return { subscriptionId: id }
    }),
    setRoomId: assign(({ event }) => ({
      roomId: event.type === "ACTIVATE" ? (event.roomId ?? null) : null,
    })),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    hydrateFromInit: assign(({ context, event }) => {
      if (event.type !== "INIT") return {}
      const topics = event.data.feedbackTopics ?? []
      const myResponses = event.data.myFeedbackResponses ?? {}
      syncTopicNotifications(context.roomId, topics)
      return { topics, myResponses }
    }),
    applyRoomData: assign(({ context, event }) => {
      if (event.type !== "ROOM_DATA") return {}
      const topics = event.data.feedbackTopics ?? context.topics
      const myResponses = event.data.myFeedbackResponses ?? context.myResponses
      syncTopicNotifications(context.roomId, topics)
      return { topics, myResponses }
    }),
    setTopics: assign(({ context, event }) => {
      if (event.type !== "FEEDBACK_TOPICS_CHANGED") return {}
      syncTopicNotifications(context.roomId, event.data.topics)
      return { topics: event.data.topics }
    }),
    applySavedResponse: assign(({ context, event }) => {
      if (event.type !== "FEEDBACK_RESPONSE_SAVED") return {}
      const response = event.data.response
      return {
        myResponses: {
          ...context.myResponses,
          [response.topicId]: response,
        },
      }
    }),
    toastSaveFailed: assign(({ event }) => {
      if (event.type !== "FEEDBACK_RESPONSE_FAILED") return {}
      toast({
        title: "Could not save feedback",
        description: event.data.reason,
        type: "error",
      })
      return {
        lastFailedTopicId: event.data.topicId,
        lastFailedAt: Date.now(),
      }
    }),
    setInbox: assign(({ event }) => {
      if (event.type !== "FEEDBACK_INBOX") return {}
      return {
        inboxTopics: event.data.topics,
        inbox: event.data.responses,
      }
    }),
    mergeInboxEntry: assign(({ context, event }) => {
      if (event.type !== "FEEDBACK_INBOX_UPDATED") return {}
      const entry = event.data.entry
      const without = context.inbox.filter(
        (e) => !(e.topicId === entry.topicId && e.userId === entry.userId),
      )
      const notifId = feedbackInboxNotificationId(entry.topicId, entry.userId)
      const topicTitle =
        context.inboxTopics.find((t) => t.id === entry.topicId)?.title ??
        context.topics.find((t) => t.id === entry.topicId)?.title ??
        (entry.topicId === GENERAL_FEEDBACK_TOPIC_ID ? "General feedback" : "Feedback")
      raiseNotification({
        id: notifId,
        source: FEEDBACK_INBOX_SOURCE,
        target: { surface: "adminSettings", tabId: "feedback" },
        clearOn: "view",
        toast: {
          title: "New feedback",
          description: topicTitle,
          action: "open",
          duration: 8000,
        },
      })
      return {
        inbox: [entry, ...without].sort((a, b) => b.updatedAt - a.updatedAt),
      }
    }),
    emitSaveResponse: ({ event }) => {
      if (event.type !== "SAVE_RESPONSE") return
      emitToSocket("SAVE_FEEDBACK_RESPONSE", event.data)
    },
    emitSetTopics: ({ event }) => {
      if (event.type !== "SET_TOPICS") return
      emitToSocket("SET_FEEDBACK_TOPICS", { topics: event.data.topics })
    },
    emitFetchInbox: () => {
      emitToSocket("GET_FEEDBACK_INBOX", {})
    },
    markSurfaceViewed: ({ context }) => {
      const roomId = context.roomId
      if (!roomId) return
      const ids = context.topics.map((t) => t.id)
      markFeedbackTopicsViewed(roomId, ids)
      resolveNotifications(ids.map(feedbackTopicNotificationId))
    },
    reset: assign({
      topics: () => [],
      myResponses: () => ({}),
      inboxTopics: () => [],
      inbox: () => [],
      subscriptionId: () => null,
      roomId: () => null,
      lastFailedTopicId: () => null,
      lastFailedAt: () => 0,
    }),
  },
}).createMachine({
  id: "feedback",
  initial: "idle",
  context: {
    topics: [],
    myResponses: {},
    inboxTopics: [],
    inbox: [],
    subscriptionId: null,
    roomId: null,
    lastFailedTopicId: null,
    lastFailedAt: 0,
  },
  states: {
    idle: {
      on: {
        ACTIVATE: {
          target: "active",
          actions: ["setRoomId"],
        },
      },
    },
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe", "reset"],
      on: {
        DEACTIVATE: "idle",
        INIT: { actions: ["hydrateFromInit"] },
        ROOM_DATA: { actions: ["applyRoomData"] },
        FEEDBACK_TOPICS_CHANGED: { actions: ["setTopics"] },
        FEEDBACK_RESPONSE_SAVED: { actions: ["applySavedResponse"] },
        FEEDBACK_RESPONSE_FAILED: { actions: ["toastSaveFailed"] },
        FEEDBACK_INBOX: { actions: ["setInbox"] },
