export const effectiveMetadataSourcesMachine = setup({
  types: {
    context: {} as EffectiveMetadataSourcesContext,
    events: {} as EffectiveMetadataSourcesEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `effectiveMetadataSources-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as EffectiveMetadataSourcesEvent),
        eventTypes: [
          "INIT",
          "EFFECTIVE_METADATA_SOURCES",
          "ROOM_SETTINGS_UPDATED",
          "MEDIA_BRIDGE_STATUS_CHANGED",
          "INVENTORY_ITEM_ACQUIRED",
          "INVENTORY_ITEM_REMOVED",
          "INVENTORY_ITEM_USED",
          "INVENTORY_ITEM_TRANSFERRED",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
      debouncedFetch.cancel()
    },
    fetchEffective: () => {
      debouncedFetch.cancel()
      emitToSocket("GET_EFFECTIVE_METADATA_SOURCES", {})
    },
    scheduleFetchEffective: () => {
      debouncedFetch.schedule()
    },
    assignFromEffectiveEvent: assign(({ event }) => {
      if (event.type !== "EFFECTIVE_METADATA_SOURCES") return {}
      return {
        ...(Array.isArray(event.data?.metadataSourceIds)
          ? { metadataSourceIds: event.data.metadataSourceIds }
          : {}),
        ...(Array.isArray(event.data?.browseableSourceIds)
          ? { browseableSourceIds: event.data.browseableSourceIds }
          : {}),
        ...(event.data?.browseSourceCapabilities
          ? { browseSourceCapabilities: event.data.browseSourceCapabilities }
          : {}),
        ...(Array.isArray(event.data?.myMedia) ? { myMedia: event.data.myMedia } : {}),
      }
    }),
    assignFromInit: assign(({ event }) => {
      if (event.type !== "INIT") return {}
      return {
        ...(Array.isArray(event.data?.effectiveMetadataSourceIds)
          ? { metadataSourceIds: event.data.effectiveMetadataSourceIds }
          : {}),
        ...(Array.isArray(event.data?.browseableSourceIds)
          ? { browseableSourceIds: event.data.browseableSourceIds }
          : {}),
        ...(event.data?.browseSourceCapabilities
          ? { browseSourceCapabilities: event.data.browseSourceCapabilities }
          : {}),
        ...(Array.isArray(event.data?.myMedia) ? { myMedia: event.data.myMedia } : {}),
      }
    }),
    resetContext: assign(() => defaultContext),
  },
  guards: {
    isMyInventoryEvent: ({ event }) => {
      const data = (event as { data?: UserScopedEventData }).data
      return isGameEventForUser(data, getCurrentUser()?.userId)
    },
  },
}).createMachine({
  id: "effectiveMetadataSources",
  initial: "idle",
  context: defaultContext,
  states: {
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    active: {
      entry: ["subscribe", "fetchEffective"],
      exit: ["unsubscribe", "resetContext"],
      on: {
        DEACTIVATE: "idle",
        REFRESH: { actions: ["fetchEffective"] },
        EFFECTIVE_METADATA_SOURCES: { actions: ["assignFromEffectiveEvent"] },
        INIT: { actions: ["assignFromInit"] },
        ROOM_SETTINGS_UPDATED: { actions: ["fetchEffective"] },
        MEDIA_BRIDGE_STATUS_CHANGED: { actions: ["fetchEffective"] },
        INVENTORY_ITEM_ACQUIRED: {
          guard: "isMyInventoryEvent",
          actions: ["scheduleFetchEffective"],
        },
        INVENTORY_ITEM_REMOVED: {
          guard: "isMyInventoryEvent",
          actions: ["scheduleFetchEffective"],
        },
        INVENTORY_ITEM_USED: {
          guard: "isMyInventoryEvent",
          actions: ["scheduleFetchEffective"],
        },
        INVENTORY_ITEM_TRANSFERRED: {
          guard: "isMyInventoryEvent",
          actions: ["scheduleFetchEffective"],
        },
      },
    },
  },
})

export const djMachine = setup({
  types: {
    context: {} as DjContext,
    events: {} as DjEvent,
  },
  guards: {
    isAdmin: () => {
      return getIsAdmin()
    },
    isDeputyDj: ({ event }) => {
      if (event.type !== "INIT") return false
      return !!event.data.user?.isDeputyDj
    },
    isBulkDeputize: ({ event }) => {
      if (event.type !== "DEPUTY_BULK_APPLIED") return false
      return event.data.action === "deputize_all"
    },
    isBulkDedeputize: ({ event }) => {
      if (event.type !== "DEPUTY_BULK_APPLIED") return false
      return event.data.action === "dedeputize_all"
    },
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `dj-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event),
        eventTypes: [
          "INIT",
          "DEPUTY_BULK_APPLIED",
          "START_DEPUTY_DJ_SESSION",
          "END_DEPUTY_DJ_SESSION",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    startDjSession: () => {
      const currentUser = getCurrentUser()
      emitToSocket("SET_DJ", currentUser?.userId)
    },
    endDjSession: () => {
      emitToSocket("SET_DJ", null)
    },
    reset: assign({
      subscriptionId: () => null,
    }),
  },
}).createMachine({
  id: "dj",
  initial: "idle",
  context: {
    subscriptionId: null,
  },
  states: {
    // Idle state - not subscribed to socket events
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    // Active state - subscribed to socket events
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["reset"],
        },
        INIT: {
          target: ".deputyDjaying",
          guard: "isDeputyDj",
        },
      },
      initial: "inactive",
      states: {
        djaying: {
          on: {
            END_DJ_SESSION: {
              target: "inactive",
              actions: ["endDjSession"],
              guard: "isAdmin",
            },
          },
        },
        deputyDjaying: {
          on: {
            END_DEPUTY_DJ_SESSION: "inactive",
            DEPUTY_BULK_APPLIED: {
              target: "inactive",
              guard: "isBulkDedeputize",
            },
          },
        },
        inactive: {
          on: {
            START_DJ_SESSION: {
              target: "djaying",
              actions: ["startDjSession"],
              guard: "isAdmin",
            },
            START_DEPUTY_DJ_SESSION: "deputyDjaying",
            DEPUTY_BULK_APPLIED: {
              target: "deputyDjaying",
              guard: "isBulkDeputize",
            },
          },
        },
      },
    },
  },
})

export function createDebouncedInputMachine(onChange: (value: string) => void) {
  return setup({
    types: {
      context: {} as Context,
      events: {} as DebouncedInputEvent,
    },
    actions: {
      setValue: assign({
        value: ({ event }) => {
          if (event.type === "SET_VALUE") {
            return event.value
          }
          return undefined
        },
      }),
      setSearchValue: assign({
        searchValue: ({ context }) => context.value,
      }),
      onSearchChange: ({ context }) => {
        if (context.value !== undefined && context.value !== null && context.value !== "") {
          onChange(context.value)
        }
      },
    },
  }).createMachine({
    id: "search",
    initial: "idle",
    context: {
      value: undefined,
      searchValue: undefined,
    },
    states: {
      idle: {
        on: {
          SET_VALUE: {
            target: "typing",
            actions: ["setValue"],
          },
        },
      },
      typing: {
        on: {
          SET_SEARCH: {
            target: "idle",
            actions: ["setSearchValue", "onSearchChange"],
          },
          SET_VALUE: {
            target: "typing",
            actions: ["setValue"],
            reenter: true,
          },
        },
        after: {
          450: {
            target: "idle",
            actions: ["setSearchValue", "onSearchChange"],
          },
        },
      },
    },
  })
}

export const createdRoomsFetchMachine = setup({
  types: {
    context: {} as RoomFetchContext,
    events: {} as RoomFetchEvent,
  },
  actors: {
    fetchUserRooms: fetchUserRoomsLogic,
    deleteRoom: deleteRoomLogic,
  },
  actions: {
    setError: assign(({ context, event }) => {
      if (event.type !== "xstate.error.actor.fetchUserRooms") return context
      return {
        error: event.error,
      }
    }),
    setUserId: assign(({ context, event }) => {
      if (event.type !== "FETCH") return context
      return {
        userId: event.data.userId,
      }
    }),
    setRooms: assign(({ context, event }) => {
      if (event.type !== "xstate.done.actor.fetchUserRooms") {
        return context
      }
      return {
        rooms: event.output.rooms,
      }
    }),
    reset: assign(() => {
      return {
        userId: undefined,
        rooms: [],
        error: null,
      }
    }),
    notifyRoomDeleted: () => {
      toast({
        title: "Room deleted",
        description: "Your room has been deleted",
        status: "success",
      })
    },
  },
}).createMachine({
  id: "createdRoomsFetch",
  initial: "initial",
  context: {
    userId: undefined,
    rooms: [],
    error: null,
  },
  on: {
    FETCH: {
      target: ".loading",
      actions: ["setUserId"],
    },
    SESSION_ENDED: {
      target: ".initial",
      actions: ["reset"],
    },
  },
  states: {
    initial: {},
    loading: {
      invoke: {
        id: "fetchUserRooms",
        src: "fetchUserRooms",
        input: ({ context }) => ({ userId: context.userId }),
        onDone: {
          target: "success",
          actions: ["setRooms"],
        },
        onError: {
          target: "error",
          actions: ["setError"],
        },
      },
    },
    deleting: {
      invoke: {
        id: "deleteRoom",
        src: "deleteRoom",
        input: ({ event }) => {
          if (event.type === "DELETE_ROOM") {
            return { roomId: event.data.roomId }
          }
          return { roomId: "" }
        },
        onDone: {
          target: "loading",
          actions: ["notifyRoomDeleted"],
        },
        onError: {
          target: "error",
          actions: ["setError"],
        },
      },
    },
    success: {
      on: {
        DELETE_ROOM: {
          target: "deleting",
        },
      },
    },
    error: {},
  },
})

export const coinGainFeedbackMachine = setup({
  types: {
    context: {} as CoinGainFeedbackContext,
    events: {} as CoinGainFeedbackEvent,
  },
  actions: {
    clearTracking: assign({
      previousCoin: () => undefined,
      pendingCoin: () => undefined,
      animationKind: () => undefined,
      animationCoinDelta: () => undefined,
    }),
    setBaselineFromSync: assign({
      previousCoin: ({ event }) => (event.type === "SYNC" ? event.coin : undefined),
      pendingCoin: () => undefined,
      animationKind: () => undefined,
      animationCoinDelta: () => undefined,
    }),
    setPreviousFromSync: assign({
      previousCoin: ({ event }) => (event.type === "SYNC" ? event.coin : undefined),
    }),
    enterAnimatingGain: assign({
      pendingCoin: ({ event }) => (event.type === "SYNC" ? event.coin : undefined),
      animationKind: () => "gain" as const,
      animationCoinDelta: ({ context, event }) =>
        event.type === "SYNC" && context.previousCoin !== undefined
          ? event.coin - context.previousCoin
          : undefined,
    }),
    enterAnimatingLoss: assign({
      pendingCoin: ({ event }) => (event.type === "SYNC" ? event.coin : undefined),
      animationKind: () => "loss" as const,
      animationCoinDelta: ({ context, event }) =>
        event.type === "SYNC" && context.previousCoin !== undefined
          ? event.coin - context.previousCoin
          : undefined,
    }),
    mergePendingWhileAnimating: assign({
      pendingCoin: ({ event }) => (event.type === "SYNC" ? event.coin : undefined),
    }),
    finishAnimation: assign({
      previousCoin: ({ context }) => context.pendingCoin ?? context.previousCoin,
      pendingCoin: () => undefined,
      animationKind: () => undefined,
      animationCoinDelta: () => undefined,
    }),
  },
  guards: {
    lostTracking: ({ event }) =>
      event.type === "SYNC" && (!event.sessionActive || !event.coinAttributeEnabled),

    sessionWantsCoinTracking: ({ event }) =>
      event.type === "SYNC" && event.sessionActive && event.coinAttributeEnabled,

    shouldAnimateCoinGain: ({ context, event }) =>
      event.type === "SYNC" &&
      event.sessionActive &&
      event.coinAttributeEnabled &&
      event.animationsEnabled &&
      context.previousCoin !== undefined &&
      event.coin > context.previousCoin,

    coinIncreasedWithoutAnimation: ({ context, event }) =>
      event.type === "SYNC" &&
      event.sessionActive &&
      event.coinAttributeEnabled &&
      !event.animationsEnabled &&
      context.previousCoin !== undefined &&
      event.coin > context.previousCoin,

    shouldAnimateCoinLoss: ({ context, event }) =>
      event.type === "SYNC" &&
      event.sessionActive &&
      event.coinAttributeEnabled &&
      event.animationsEnabled &&
      context.previousCoin !== undefined &&
      event.coin < context.previousCoin,

    coinDecreasedWithoutAnimation: ({ context, event }) =>
      event.type === "SYNC" &&
      event.sessionActive &&
      event.coinAttributeEnabled &&
      !event.animationsEnabled &&
      context.previousCoin !== undefined &&
      event.coin < context.previousCoin,
  },
}).createMachine({
  id: "coinGainFeedback",
  initial: "inactive",
  context: {
    previousCoin: undefined,
    pendingCoin: undefined,
    animationKind: undefined,
    animationCoinDelta: undefined,
  },
  states: {
    inactive: {
      on: {
        SYNC: [
          {
            guard: "sessionWantsCoinTracking",
            target: "watching",
            actions: "setBaselineFromSync",
          },
          { actions: "clearTracking" },
        ],
      },
    },
    watching: {
      on: {
        SYNC: [
          {
            guard: "lostTracking",
            target: "inactive",
            actions: "clearTracking",
          },
          {
            guard: "shouldAnimateCoinGain",
            target: "animating",
            actions: "enterAnimatingGain",
          },
          {
            guard: "shouldAnimateCoinLoss",
            target: "animating",
            actions: "enterAnimatingLoss",
          },
          {
            guard: "coinIncreasedWithoutAnimation",
            actions: "setPreviousFromSync",
          },
          {
            guard: "coinDecreasedWithoutAnimation",
            actions: "setPreviousFromSync",
          },
        ],
      },
    },
    animating: {
      on: {
        SYNC: [
          {
            guard: "lostTracking",
            target: "inactive",
            actions: "clearTracking",
          },
          { actions: "mergePendingWhileAnimating" },
        ],
        ANIMATION_FINISHED: {
          target: "watching",
          actions: "finishAnimation",
        },
      },
    },
  },
})

