export const chatMachine = setup({
  types: {
    context: {} as ChatContext,
    events: {} as MachineEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `chat-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as MachineEvent),
        eventTypes: [
          "INIT",
          "ROOM_DATA",
          "MESSAGE_RECEIVED",
          "MESSAGE_DELETED",
          "MESSAGES_CLEARED",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    sendMessage: ({ event }) => {
      if (event.type === "SUBMIT_MESSAGE") {
        emitToSocket("SEND_MESSAGE", event.data)
      }
    },
    startTyping: () => {
      emitToSocket("START_TYPING", {})
    },
    stopTyping: () => {
      emitToSocket("STOP_TYPING", {})
    },
    clearMessagesAndEmit: () => {
      emitToSocket("CLEAR_MESSAGES", {})
    },
    resetMessages: assign({
      messages: () => [],
      subscriptionId: () => null,
    }),
    addMessage: assign({
      messages: ({ context, event }) => {
        if (event.type !== "MESSAGE_RECEIVED") return context.messages
        const incoming = event.data.message
        const base =
          incoming.expiresAt == null
            ? context.messages.filter(
                (m) => !(m.expiresAt != null && m.user.userId === incoming.user.userId),
              )
            : context.messages
        return uniqBy("timestamp", [...base, incoming])
      },
    }),
    removeMessage: assign({
      messages: ({ context, event }) => {
        if (event.type === "MESSAGE_DELETED") {
          return context.messages.filter((m) => m.timestamp !== event.data.timestamp)
        }
        return context.messages
      },
    }),
    deleteMessageAndEmit: ({ event }) => {
      if (event.type === "DELETE_MESSAGE") {
        emitToSocket("DELETE_MESSAGE", { timestamp: event.data.timestamp })
      }
    },
    addMessages: assign({
      messages: ({ context, event }) => {
        if (event.type === "ROOM_DATA") {
          return uniqBy("timestamp", [...context.messages, ...event.data.messages])
        }
        return context.messages
      },
    }),
    handleNotifications: ({ event }) => {
      if (event.type === "MESSAGE_RECEIVED") {
        handleNotifications(event.data.message, getCurrentUser())
      }
    },
    setData: assign({
      messages: ({ context, event }) => {
        if (event.type === "INIT") {
          return event.data.messages || []
        }
        if (event.type === "MESSAGES_CLEARED") {
          return []
        }
        return context.messages
      },
    }),
  },
}).createMachine({
  id: "chat",
  initial: "idle",
  context: {
    messages: [],
    subscriptionId: null,
  },
  states: {
    // Idle state - not subscribed to socket events
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    // Active state - subscribed to socket events
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["resetMessages"],
        },
        CLEAR_MESSAGES: {
          actions: ["clearMessagesAndEmit"],
        },
        RESET: {
          actions: ["resetMessages"],
        },
      },
      initial: "unauthenticated",
      states: {
        unauthenticated: {
          on: {
            INIT: {
              target: "ready",
              actions: ["setData"],
            },
            // Same as `ready`: after reconnect, INIT can lag auth; do not drop SUBMIT (ChatInput clears anyway)
            SUBMIT_MESSAGE: { actions: ["sendMessage"] },
            START_TYPING: { actions: ["startTyping"] },
            STOP_TYPING: { actions: ["stopTyping"] },
          },
        },
        ready: {
          type: "parallel",
          on: {
            INIT: {
              actions: ["setData"],
            },
            ROOM_DATA: {
              actions: ["addMessages"],
            },
            SUBMIT_MESSAGE: { actions: ["sendMessage"] },
            DELETE_MESSAGE: { actions: ["deleteMessageAndEmit"] },
            MESSAGE_RECEIVED: { actions: ["addMessage", "handleNotifications"] },
            MESSAGE_DELETED: { actions: ["removeMessage"] },
            MESSAGES_CLEARED: { actions: ["setData"] },
          },
          states: {
            typing: {
              initial: "inactive",
              id: "typing",
              on: {
                START_TYPING: ".active",
                STOP_TYPING: ".inactive",
              },
              states: {
                active: {
                  entry: ["startTyping"],
                },
                inactive: {
                  entry: ["stopTyping"],
                },
              },
            },
          },
        },
      },
    },
  },
})

export const catalogBrowseMachine = setup({
  types: {
    context: {} as CatalogBrowseContext,
    events: {} as CatalogBrowseEvent,
  },
  guards: {
    hasCachedAlbum: ({ event }) => {
      if (event.type !== "FETCH_ALBUM") return false
      const entry = getSessionCache(albumSessionCacheKey(event.source, event.albumId))
      return entry?.kind === "album"
    },
    hasCachedMedia: ({ event }) => {
      if (event.type !== "FETCH_MEDIA") return false
      const entry = getSessionCache(mediaSessionCacheKey(event.mediaKey))
      return entry?.kind === "media"
    },
    isArtistsFirstPage: ({ event }) =>
      event.type === "FETCH_ARTISTS" && (event.offset ?? 0) === 0,
    isArtistsLoadMore: ({ event }) => event.type === "FETCH_ARTISTS" && (event.offset ?? 0) > 0,
    isAlbumsFirstPage: ({ event }) =>
      event.type === "FETCH_ALBUMS" && (event.offset ?? 0) === 0,
    isAlbumsLoadMore: ({ event }) => event.type === "FETCH_ALBUMS" && (event.offset ?? 0) > 0,
    artistsResultsMatchRequest: ({ context, event }) => {
      if (event.type !== "BROWSE_ARTISTS_RESULTS") return false
      if (event.data.source !== context.source) return false
      if (normalizeBrowseQuery(event.data.query) !== normalizeBrowseQuery(context.artistsPendingQuery)) {
        return false
      }
      return (event.data.offset ?? 0) === context.artistsPendingOffset
    },
    albumsResultsMatchRequest: ({ context, event }) => {
      if (event.type !== "BROWSE_ALBUMS_RESULTS") return false
      if (event.data.source !== context.source) return false
      if (normalizeBrowseQuery(event.data.query) !== normalizeBrowseQuery(context.albumsPendingQuery)) {
        return false
      }
      return (event.data.offset ?? 0) === context.albumsPendingOffset
    },
  },
  actions: {
    sendListArtists: ({ event }) => {
      if (event.type === "FETCH_ARTISTS") {
        emitToSocket("BROWSE_ARTISTS", {
          source: event.source,
          query: event.query,
          offset: event.offset ?? 0,
          limit: event.limit ?? CATALOG_BROWSE_PAGE_SIZE,
        })
      }
    },
    sendListAlbums: ({ event }) => {
      if (event.type === "FETCH_ALBUMS") {
        emitToSocket("BROWSE_ALBUMS", {
          source: event.source,
          query: event.query,
          offset: event.offset ?? 0,
          limit: event.limit ?? CATALOG_BROWSE_PAGE_SIZE,
        })
      }
    },
    stashArtistsRequest: assign(({ event }) => {
      if (event.type !== "FETCH_ARTISTS") return {}
      return {
        source: event.source,
        artistsPendingQuery: event.query,
        artistsPendingOffset: event.offset ?? 0,
      }
    }),
    stashAlbumsRequest: assign(({ event }) => {
      if (event.type !== "FETCH_ALBUMS") return {}
      return {
        source: event.source,
        albumsPendingQuery: event.query,
        albumsPendingOffset: event.offset ?? 0,
      }
    }),
    sendGetArtist: ({ event }) => {
      if (event.type === "FETCH_ARTIST") {
        emitToSocket("BROWSE_ARTIST", {
          source: event.source,
          artistId: event.artistId,
        })
      }
    },
    sendGetAlbum: ({ event }) => {
      if (event.type === "FETCH_ALBUM") {
        emitToSocket("BROWSE_ALBUM", {
          source: event.source,
          albumId: event.albumId,
        })
      }
    },
    sendGetMedia: ({ event }) => {
      if (event.type === "FETCH_MEDIA") {
        emitToSocket("BROWSE_MEDIA_ITEM", {
          mediaKey: event.mediaKey,
        })
      }
    },
    applyCachedAlbum: assign(({ event }) => {
      if (event.type !== "FETCH_ALBUM") return {}
      const entry = getSessionCache(albumSessionCacheKey(event.source, event.albumId))
      if (entry?.kind !== "album") return {}
      return {
        source: entry.source,
        album: entry.album,
        tracks: entry.tracks,
        mediaKey: null,
        mediaName: null,
        error: null,
      }
    }),
    applyCachedMedia: assign(({ event }) => {
      if (event.type !== "FETCH_MEDIA") return {}
      const entry = getSessionCache(mediaSessionCacheKey(event.mediaKey))
      if (entry?.kind !== "media") return {}
      return {
        source: entry.source,
        mediaKey: entry.mediaKey,
        mediaName: entry.mediaName,
        album: null,
        tracks: entry.tracks,
        error: null,
      }
    }),
    setArtists: assign(({ context, event }) => {
      if (event.type !== "BROWSE_ARTISTS_RESULTS") return {}
      const incoming = event.data.items ?? []
      const offset = event.data.offset ?? context.artistsPendingOffset
      const previousLength = offset === 0 ? 0 : context.artists.length
      const artists = offset === 0 ? incoming : uniqueById([...context.artists, ...incoming])
      return {
        source: event.data.source,
        artists,
        artistsTotal: event.data.total,
        artistsHasMore: pageHasMore({
          accumulated: artists,
          incoming,
          previousLength,
          total: event.data.total,
          pageSize: CATALOG_BROWSE_PAGE_SIZE,
        }),
        error: null,
      }
    }),
    setRootAlbums: assign(({ context, event }) => {
      if (event.type !== "BROWSE_ALBUMS_RESULTS") return {}
      const incoming = event.data.items ?? []
      const offset = event.data.offset ?? context.albumsPendingOffset
      const previousLength = offset === 0 ? 0 : context.rootAlbums.length
      const rootAlbums = offset === 0 ? incoming : uniqueById([...context.rootAlbums, ...incoming])
      return {
        source: event.data.source,
        rootAlbums,
        rootAlbumsTotal: event.data.total,
        rootAlbumsHasMore: pageHasMore({
          accumulated: rootAlbums,
          incoming,
          previousLength,
          total: event.data.total,
          pageSize: CATALOG_BROWSE_PAGE_SIZE,
        }),
        error: null,
      }
    }),
    setArtist: assign(({ event }) => {
      if (event.type !== "BROWSE_ARTIST_RESULTS") return {}
      return {
        source: event.data.source,
        artist: event.data.artist,
        albums: event.data.albums ?? [],
        album: null,
        tracks: [],
        error: null,
      }
    }),
    setAlbum: assign(({ event }) => {
      if (event.type !== "BROWSE_ALBUM_RESULTS") return {}
      putSessionCache(albumSessionCacheKey(event.data.source, event.data.album.id), {
        kind: "album",
        source: event.data.source,
        album: event.data.album,
        tracks: event.data.tracks ?? [],
      })
      return {
        source: event.data.source,
        album: event.data.album,
        tracks: event.data.tracks ?? [],
        mediaKey: null,
        mediaName: null,
        error: null,
      }
    }),
    setMedia: assign(({ event }) => {
      if (event.type !== "BROWSE_MEDIA_ITEM_RESULTS") return {}
      putSessionCache(mediaSessionCacheKey(event.data.mediaKey), {
        kind: "media",
        source: event.data.source,
        mediaKey: event.data.mediaKey,
        mediaName: event.data.name,
        tracks: event.data.tracks ?? [],
      })
      return {
        source: event.data.source,
        mediaKey: event.data.mediaKey,
        mediaName: event.data.name,
        album: null,
        tracks: event.data.tracks ?? [],
        error: null,
      }
    }),
    setError: assign(({ event }) => {
      if (
        event.type !== "BROWSE_ARTISTS_FAILURE" &&
        event.type !== "BROWSE_ALBUMS_FAILURE" &&
        event.type !== "BROWSE_ARTIST_FAILURE" &&
        event.type !== "BROWSE_ALBUM_FAILURE" &&
        event.type !== "BROWSE_MEDIA_ITEM_FAILURE"
      ) {
        return {}
      }
      return { error: event.data }
    }),
    clearError: assign({ error: null }),
  },
}).createMachine({
  id: "catalog-browse",
  initial: "idle",
  context: {
    source: null,
    artists: [],
    artistsTotal: undefined,
    artistsHasMore: false,
    artistsPendingQuery: undefined,
    artistsPendingOffset: 0,
    rootAlbums: [],
    rootAlbumsTotal: undefined,
    rootAlbumsHasMore: false,
    albumsPendingQuery: undefined,
    albumsPendingOffset: 0,
    artist: null,
    albums: [],
    album: null,
    mediaKey: null,
    mediaName: null,
    tracks: [],
    error: null,
  },
  on: {
    FETCH_ARTISTS: [
      {
        guard: "isArtistsLoadMore",
        target: ".loadingMoreArtists",
        actions: ["clearError", "stashArtistsRequest"],
      },
      {
        target: ".loadingArtists",
        actions: ["clearError", "stashArtistsRequest"],
      },
    ],
    FETCH_ALBUMS: [
      {
        guard: "isAlbumsLoadMore",
        target: ".loadingMoreAlbums",
        actions: ["clearError", "stashAlbumsRequest"],
      },
      {
        target: ".loadingAlbums",
        actions: ["clearError", "stashAlbumsRequest"],
      },
    ],
    FETCH_ARTIST: {
      target: ".loadingArtist",
      actions: ["clearError"],
    },
    FETCH_ALBUM: [
      {
        guard: "hasCachedAlbum",
        target: ".idle",
        actions: ["clearError", "applyCachedAlbum"],
      },
      {
        target: ".loadingAlbum",
        actions: ["clearError"],
      },
    ],
    FETCH_MEDIA: [
      {
        guard: "hasCachedMedia",
        target: ".idle",
        actions: ["clearError", "applyCachedMedia"],
      },
      {
        target: ".loadingMedia",
        actions: ["clearError"],
      },
    ],
  },
  states: {
    idle: {},
    failure: {},
    loadingArtists: {
      entry: ["sendListArtists"],
      on: {
        FETCH_ARTISTS: [
          {
            guard: "isArtistsFirstPage",
            target: "loadingArtists",
            actions: ["clearError", "stashArtistsRequest"],
          },
          {
            guard: "isArtistsLoadMore",
            target: "loadingArtists",
            reenter: false,
          },
        ],
        BROWSE_ARTISTS_RESULTS: [
          {
            guard: "artistsResultsMatchRequest",
            target: "idle",
            actions: ["setArtists"],
          },
          { target: "idle" },
        ],
        BROWSE_ARTISTS_FAILURE: {
          target: "failure",
          actions: ["setError"],
        },
      },
    },
    loadingMoreArtists: {
      entry: ["sendListArtists"],
      on: {
        FETCH_ARTISTS: [
          {
            guard: "isArtistsFirstPage",
            target: "loadingArtists",
            actions: ["clearError", "stashArtistsRequest"],
          },
          {
            guard: "isArtistsLoadMore",
            target: "loadingMoreArtists",
            reenter: false,
          },
        ],
        BROWSE_ARTISTS_RESULTS: [
          {
            guard: "artistsResultsMatchRequest",
            target: "idle",
            actions: ["setArtists"],
          },
          { target: "idle" },
        ],
        BROWSE_ARTISTS_FAILURE: {
          target: "failure",
          actions: ["setError"],
        },
      },
    },
    loadingAlbums: {
      entry: ["sendListAlbums"],
      on: {
        FETCH_ALBUMS: [
          {
            guard: "isAlbumsFirstPage",
            target: "loadingAlbums",
            actions: ["clearError", "stashAlbumsRequest"],
          },
          {
            guard: "isAlbumsLoadMore",
            target: "loadingAlbums",
            reenter: false,
          },
        ],
        BROWSE_ALBUMS_RESULTS: [
          {
            guard: "albumsResultsMatchRequest",
            target: "idle",
            actions: ["setRootAlbums"],
          },
          { target: "idle" },
        ],
        BROWSE_ALBUMS_FAILURE: {
          target: "failure",
          actions: ["setError"],
        },
      },
    },
    loadingMoreAlbums: {
      entry: ["sendListAlbums"],
      on: {
        FETCH_ALBUMS: [
          {
            guard: "isAlbumsFirstPage",
            target: "loadingAlbums",
            actions: ["clearError", "stashAlbumsRequest"],
          },
          {
            guard: "isAlbumsLoadMore",
            target: "loadingMoreAlbums",
            reenter: false,
          },
        ],
        BROWSE_ALBUMS_RESULTS: [
          {
            guard: "albumsResultsMatchRequest",
            target: "idle",
            actions: ["setRootAlbums"],
          },
          { target: "idle" },
        ],
        BROWSE_ALBUMS_FAILURE: {
          target: "failure",
          actions: ["setError"],
        },
      },
    },
    loadingArtist: {
      entry: ["sendGetArtist"],
      on: {
        BROWSE_ARTIST_RESULTS: {
          target: "idle",
          actions: ["setArtist"],
        },
        BROWSE_ARTIST_FAILURE: {
          target: "failure",
          actions: ["setError"],
        },
      },
    },
    loadingAlbum: {
      entry: ["sendGetAlbum"],
      on: {
        BROWSE_ALBUM_RESULTS: {
          target: "idle",
          actions: ["setAlbum"],
        },
        BROWSE_ALBUM_FAILURE: {
          target: "failure",
          actions: ["setError"],
        },
      },
    },
    loadingMedia: {
      entry: ["sendGetMedia"],
      on: {
        BROWSE_MEDIA_ITEM_RESULTS: {
          target: "idle",
          actions: ["setMedia"],
        },
        BROWSE_MEDIA_ITEM_FAILURE: {
          target: "failure",
          actions: ["setError"],
        },
      },
    },
  },
})

export const authMachine = setup({
  types: {
    context: {} as AuthContext,
    events: {} as AuthEvent,
  },
  actors: {
    visibilityService: visibilityLogic,
    getStoredUser: getStoredUserLogic,
    getSessionUser: getSessionUserLogic,
    logout: logoutLogic,
  },
  actions: {
    log: ({ context, event }) => {
      console.log("ctx", context)
      console.log("event", event)
    },
    assignInitialized: assign({
      initialized: () => true,
    }),
    resetInitialized: assign({
      initialized: () => false,
    }),
    setCurrentUser: assign(({ context, event }) => {
      if (event.type === "xstate.done.actor.getSessionUser") {
        return {
          currentUser: event.output.user,
          isNewUser: event.output.isNewUser,
        }
      }
      if (event.type === "INIT") {
        return {
          currentUser: event.data.user,
          isNewUser: event.data.isNewUser,
        }
      }
      return context
    }),
    setStoredUser: assign(({ context, event }) => {
      if (event.type === "xstate.done.actor.getStoredUser" && event.output.currentUser) {
        const storedUser = event.output.currentUser
        if (storedUser.userId) {
          return {
            currentUser: {
              userId: storedUser.userId,
              username: storedUser.username || undefined,
              isAdmin: storedUser.isAdmin,
            },
            isNewUser: false,
          }
        }
      }
      return context
    }),
    unsetNew: assign(() => ({
      isNewUser: false,
    })),
    setNew: assign(() => ({
      isNewUser: true,
    })),
    login: ({ context, event }) => {
      let userId: string | undefined = context.currentUser?.userId
      let username: string | undefined = context.currentUser?.username

      if (!userId && event.type === "xstate.done.actor.getStoredUser") {
        userId = event.output.currentUser?.userId || undefined
        username = event.output.currentUser?.username || undefined
      }

      const password = context.password
      emitToSocket("LOGIN", {
        fetchAllData: !context.initialized,
        userId,
        username,
        password: password,
        roomId: context.roomId,
      })
    },
    activateAdmin: assign({
      isAdmin: true,
      currentUser: ({ context }) =>
        context.currentUser ? { ...context.currentUser, isAdmin: true } : { userId: "" },
    }),
    deactivateAdmin: assign({
      isAdmin: false,
      currentUser: ({ context }) =>
        context.currentUser ? { ...context.currentUser, isAdmin: false } : context.currentUser,
    }),
    disableRetry: assign({
      shouldRetry: () => false,
    }),
    changeUsername: ({ context }) => {
      if (context.currentUser) {
        emitToSocket("CHANGE_USERNAME", {
          userId: context.currentUser.userId,
          username: context.currentUser.username,
        })
      }
    },
    updateUsername: assign({
      currentUser: ({ context, event }) => {
        if (event.type !== "UPDATE_USERNAME") return context.currentUser
        return (
          context.currentUser && {
            ...context.currentUser,
            username: event.data,
          }
        )
      },
    }),
    saveUser: ({ context, event }) => {
      if (event.type === "INIT") {
        saveCurrentUser({
          currentUser: event.data.user,
        })
      }
    },
    saveUserOnUsername: ({ context, event }) => {
      if (event.type === "UPDATE_USERNAME" && context.currentUser) {
        saveCurrentUser({
          currentUser: { ...context.currentUser, username: event.data },
        })
      }
    },
    setPasswordError: assign({
      passwordError: ({ event }) => {
        if (event.type !== "SET_PASSWORD_ACCEPTED") return undefined
        if (!event.data) return undefined
        if (event.data.passwordAccepted) return undefined
        return "Password incorrect"
      },
    }),
    setPasswordInContext: assign({
      password: ({ context, event }) => {
        if (event.type !== "SET_PASSWORD") return context.password
        return event.data
      },
    }),
    getStoredPassword: assign({
      password: () => getPassword(),
    }),
    disconnectUser: ({ context }) => {
      emitToSocket("USER_LEFT", {
        userId: context.currentUser?.userId,
        roomId: context.roomId,
      })
    },
    clearSession: assign(() => {
      clearCurrentUser()
      return {
        currentUser: undefined,
        isNewUser: true,
        isAdmin: false,
        shouldRetry: true,
        roomId: undefined,
      }
    }),
    nukeUser: () => {
      emitToSocket("NUKE_USER", {})
    },
    kickUser: ({ event }) => {
      if (event.type !== "KICK_USER") return
      emitToSocket("KICK_USER", {
        userId: event.userId,
      })
    },
    checkPasswordRequirement: ({ context }) => {
      if (!context.password) return
      emitToSocket("CHECK_PASSWORD", context.password)
    },
    submitPassword: ({ context, event }) => {
      if (event.type !== "SET_PASSWORD") return
      emitToSocket("SUBMIT_PASSWORD", {
        password: event.data,
        roomId: context.roomId,
      })
    },
    setRoomId: assign({
      roomId: ({ context, event }) => {
        if (event.type !== "SETUP") return context.roomId
        return event.data.roomId
      },
    }),
    savePasswordAction: ({ context, event }) => {
      if (event.type === "SET_PASSWORD") {
        savePassword(context, event)
      }
    },
    logDisconnect: ({ event }) => {
      if (event.type === "SOCKET_OFFLINE") {
        console.log("[Auth] Socket offline, reason:", event.data?.reason)
      }
    },
    showDisconnectedToast: () => {
      toast({
        title: "Connection lost",
        description: "Attempting to reconnect...",
        status: "warning",
        duration: null,
        isClosable: false,
        id: CONNECTION_STATUS_TOAST_ID,
      })
    },
    showReconnectingToast: ({ event }) => {
      if (event.type === "SOCKET_RECONNECTING") {
        toast({
          title: "Reconnecting...",
          description: `Attempt ${event.data?.attemptNumber ?? "…"}`,
          status: "info",
          duration: 2000,
          isClosable: false,
          id: CONNECTION_STATUS_TOAST_ID,
        })
      }
    },
    showReconnectedToast: () => {
      toast({
        title: "Reconnected!",
        description: "Connection restored",
        status: "success",
        duration: 3000,
        isClosable: true,
        id: CONNECTION_STATUS_TOAST_ID,
      })
    },
    showReconnectFailedToast: () => {
      toast({
        title: "Connection failed",
        description: "Unable to reconnect. Please refresh the page.",
        status: "error",
        duration: null,
        isClosable: true,
        id: CONNECTION_STATUS_TOAST_ID,
      })
    },
    showNukeSuccessToast: () => {
      toast({
        status: "success",
        title: "Spotify Disconnected",
        description:
          "Your Spotify account details and room data have been permanently deleted from our servers. Thanks for playing!",
      })
    },
    reloadPage: () => {
      window.location.reload()
    },
  },
  guards: {
    shouldRetry: ({ context }) => context.shouldRetry,
    shouldNotRetry: ({ context }) => !context.shouldRetry,
    /** Stays in `authenticated` for ChatInput and other useIsAuthenticated() UI (see ADR 0031) */
    hasRejoinUser: ({ context }) => Boolean(context.currentUser?.userId),
    isRoomAdmin: ({ event }) => {
      return event.type === "INIT" && !!event.data?.user?.isAdmin
    },
    isAdmin: ({ context }) => {
      return !!context.currentUser?.isAdmin
    },
    requiresPassword: ({ event }) => {
      if (event.type !== "SET_PASSWORD_REQUIREMENT") return false
      return Boolean(event.data?.passwordRequired)
    },
    hasStoredPasswordAndPasswordAccepted: ({ context, event }) => {
      if (event.type !== "SET_PASSWORD_REQUIREMENT") return false
      if (!event.data) return false
      return (
        !event.data.passwordRequired ||
        (event.data.passwordRequired && !!context.password && event.data.passwordAccepted === true)
      )
    },
    passwordAccepted: ({ event }) => {
      if (event.type !== "SET_PASSWORD_ACCEPTED") return false
      return event.data?.passwordAccepted === true
    },
    passwordRejected: ({ event }) => {
      if (event.type !== "SET_PASSWORD_ACCEPTED") return false
      return event.data != null && event.data.passwordAccepted === false
    },
    isReconnectPermanentlyFailed: ({ event }) => {
      return event.type === "SOCKET_OFFLINE" && event.data?.reason === "reconnect_failed"
    },
  },
}).createMachine({
  id: "auth",
  initial: "idle",
  context: {
    isNewUser: false,
    isAdmin: false,
    shouldRetry: true,
    password: undefined,
    passwordError: undefined,
    roomId: undefined,
    initialized: false,
  },
  invoke: [
    {
      id: "visibilityService",
      src: "visibilityService",
    },
  ],
  on: {
    GET_SESSION_USER: ".fetching",
    LOGOUT: {
      target: ".loggingOut",
      actions: ["clearSession"],
    },
    SETUP: {
      target: ".retrieving",
      actions: ["setRoomId"],
    },
  },
  states: {
    idle: {},
    fetching: {
      invoke: {
        id: "getSessionUser",
        src: "getSessionUser",
        onError: {
          target: "unauthenticated",
        },
        onDone: {
          target: "authenticated",
          actions: ["setCurrentUser"],
        },
      },
    },
    unauthenticated: {
      entry: ["getStoredPassword"],
      on: {
        SET_PASSWORD_REQUIREMENT: [
          { target: "connecting", guard: "hasStoredPasswordAndPasswordAccepted" },
          { target: "unauthorized", guard: "requiresPassword" },
          { target: "connecting" },
        ],
      },
    },
    disconnected: {
      entry: ["showDisconnectedToast", "resetInitialized"],
      on: {
        SETUP: {
          target: "retrieving",
          actions: ["setRoomId"],
        },
        // Re-LOGIN in-place: `retrieving` + `connecting` leave `authenticated` and hide ChatInput; stay authenticated like FORCE_REFRESH.
        SOCKET_ONLINE: [
          {
            guard: "hasRejoinUser",
            target: "authenticated",
            actions: [
              "showReconnectedToast",
              "getStoredPassword",
              "resetInitialized",
              "login",
            ],
          },
          {
            target: "retrieving",
            actions: ["showReconnectedToast"],
          },
        ],
        SOCKET_RECONNECTING: {
          actions: ["showReconnectingToast"],
        },
        SOCKET_OFFLINE: {
          actions: ["showReconnectFailedToast"],
          guard: "isReconnectPermanentlyFailed",
        },
      },
    },
    retrieving: {
      entry: ["getStoredPassword"],
      invoke: {
        id: "getStoredUser",
        src: "getStoredUser",
        onDone: {
          target: "connecting",
          actions: ["setStoredUser"],
        },
        onError: {
          target: "connecting",
        },
      },
      /** If global SETUP pulled us out of `unauthorized` mid-flow, the response can arrive here */
      on: {
        SET_PASSWORD_ACCEPTED: [
          { actions: ["setPasswordError"], guard: "passwordRejected" },
          {
            actions: ["setPasswordError", "setNew"],
            target: "connecting",
            guard: "passwordAccepted",
          },
        ],
      },
    },
    connecting: {
      entry: "login",
      on: {
        INIT: [
          {
            target: "authenticated",
            actions: ["activateAdmin", "setCurrentUser", "assignInitialized"],
            guard: "isRoomAdmin",
          },
          {
            target: "authenticated",
            actions: ["setCurrentUser", "saveUser", "assignInitialized"],
          },
        ],
        UNAUTHORIZED: {
          target: "unauthorized",
        },
        // Retry login immediately when socket is online (in case initial attempt failed)
        SOCKET_ONLINE: {
          target: "connecting",
          reenter: true,
        },
        /** Server response can follow entry `login` if we landed here from `retrieving` + race */
        SET_PASSWORD_ACCEPTED: [
          { actions: ["setPasswordError"], guard: "passwordRejected" },
          {
            actions: ["setPasswordError", "setNew"],
            target: "connecting",
            reenter: true,
            guard: "passwordAccepted",
          },
        ],
      },
      after: {
        3000: "connecting",
      },
    },
    authenticated: {
      on: {
        FORCE_REFRESH: {
          actions: ["resetInitialized", "login"],
        },
        /** Transport up — must re-LOGIN to repopulate socket.data and rejoin room channel */
        SOCKET_ONLINE: {
          actions: ["resetInitialized", "login"],
        },
        INIT: [
          {
            actions: ["activateAdmin", "setCurrentUser", "assignInitialized"],
            guard: "isRoomAdmin",
          },
          {
            actions: ["setCurrentUser", "saveUser", "assignInitialized"],
          },
        ],
        SETUP: {
          target: "retrieving",
          actions: ["setRoomId", "setCurrentUser"],
        },
        USER_DISCONNECTED: {
          // Intentional navigation away - go to idle without showing toast
          target: "idle",
          actions: ["disconnectUser"],
        },
        SOCKET_OFFLINE: {
          target: "disconnected",
          actions: ["logDisconnect"],
        },
        UPDATE_USERNAME: {
          actions: ["unsetNew", "updateUsername", "changeUsername", "saveUserOnUsername"],
        },
        ACTIVATE_ADMIN: {
          actions: ["activateAdmin"],
        },
        START_ADMIN_SESSION: {
          actions: ["activateAdmin"],
        },
        END_ADMIN_SESSION: {
          actions: ["deactivateAdmin"],
        },
        KICK_USER: {
          actions: ["kickUser"],
          guard: "isAdmin",
        },
        USER_KICKED: {
          target: "disconnected",
          actions: ["disableRetry", "disconnectUser"],
        },
        NUKE_USER: {
          target: "loggingOut",
          actions: ["clearSession", "nukeUser", "showNukeSuccessToast"],
        },
        SESSION_ENDED: {
          target: "loggingOut",
          actions: ["clearSession"],
        },
      },
    },
    unauthorized: {
      on: {
        /** Do not use root `SETUP` -> `retrieving` while the password prompt is open (drops SET_PASSWORD_ACCEPTED) */
        SETUP: {
          actions: "setRoomId",
        },
        SET_PASSWORD: {
          actions: ["setPasswordInContext", "savePasswordAction", "submitPassword"],
        },
        SET_PASSWORD_ACCEPTED: [
          { actions: ["setPasswordError"], guard: "passwordRejected" },
          {
            actions: ["setPasswordError", "setNew"],
            target: "connecting",
            guard: "passwordAccepted",
          },
        ],
      },
    },
    loggingOut: {
      invoke: {
        id: "logout",
        src: "logout",
        onDone: {
          target: "idle",
          actions: ["clearSession", "reloadPage"],
        },
      },
    },
  },
})

export const audioMachine = setup({
  types: {
    context: {} as AudioContext,
    events: {} as AudioEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `audio-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as AudioEvent),
        eventTypes: [
          "INIT",
          "OFFLINE",
          "ONLINE",
          "TRACK_CHANGED",
          "MEDIA_SOURCE_STATUS_CHANGED",
          "STREAM_HEALTH_CHANGED",
          "ROOM_SETTINGS_UPDATED",
          "PLAYLIST_TRACK_UPDATED",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    setVolume: assign(({ event }) => ({
      volume: (event as { volume: number }).volume,
    })),
    setMeta: assign(({ event }) => {
      if ("data" in event && "meta" in event.data) {
        return { meta: event.data.meta }
      }
      return {}
    }),
    updateNowPlaying: assign(({ context, event }) => {
      if (event.type === "PLAYLIST_TRACK_UPDATED") {
        return {
          meta: {
            ...context.meta,
            nowPlaying: event.data.track,
          },
        }
      }
      return {}
    }),
    clearDisabledPluginDataFromNowPlaying: assign(({ context, event }) => {
      if (event.type !== "ROOM_SETTINGS_UPDATED" || !event.data.pluginConfigs) return {}
      if (!context.meta?.nowPlaying?.pluginData) return {}

      const disabledPlugins = new Set<string>()
      for (const [name, config] of Object.entries(event.data.pluginConfigs)) {
        if ((config as { enabled?: boolean } | undefined)?.enabled !== true) {
          disabledPlugins.add(name)
        }
      }

      if (disabledPlugins.size === 0) return {}

      const cleanedPluginData = { ...context.meta.nowPlaying.pluginData }
      for (const pluginName of disabledPlugins) {
        delete cleanedPluginData[pluginName]
      }

      return {
        meta: {
          ...context.meta,
          nowPlaying: {
            ...context.meta.nowPlaying,
            pluginData: Object.keys(cleanedPluginData).length > 0 ? cleanedPluginData : undefined,
          },
        },
      }
    }),
    setMediaSourceStatus: assign(({ event }) => {
      if (event.type !== "MEDIA_SOURCE_STATUS_CHANGED") return {}
      if (event.data.streamTransport === "webrtc") {
        const s = event.data.status
        return {
          webrtcExperimentalStreamStatus:
            s === "online" ? ("online" as const) : ("offline" as const),
        }
      }
      return { mediaSourceStatus: event.data.status }
    }),
    applyStreamHealth: assign(({ event }) => {
      if (event.type !== "STREAM_HEALTH_CHANGED") return {}
      if (event.data.ingest === "webrtc_experimental") {
        return { webrtcExperimentalStreamStatus: event.data.status }
      }
      return {}
    }),
    setStatusFromMeta: assign(({ event }) => {
      const patch: Partial<AudioContext> = {}
      if (!("data" in event) || !event.data) return patch
      const d = event.data as {
        streamHealthStatus?: "online" | "offline"
        webrtcStreamHealthStatus?: "online" | "offline"
        meta?: RoomMeta
      }
      if (d.streamHealthStatus) {
        patch.mediaSourceStatus = d.streamHealthStatus
      } else if (d.meta?.nowPlaying) {
        patch.mediaSourceStatus = "online"
      } else {
        patch.mediaSourceStatus = "offline"
      }
      if (d.webrtcStreamHealthStatus === "online" || d.webrtcStreamHealthStatus === "offline") {
        patch.webrtcExperimentalStreamStatus = d.webrtcStreamHealthStatus
      }
      return patch
    }),
    setStatusOnline: assign({
      mediaSourceStatus: "online" as const,
    }),
    startListening: () => {
      emitToSocket("START_LISTENING", {
        audioTransport: getListeningAudioTransportForSocket(),
      })
    },
    listen: assign({
      participationStatus: "listening" as const,
    }),
    participate: assign({
      participationStatus: "participating" as const,
    }),
    stopListening: () => {
      emitToSocket("STOP_LISTENING", {})
    },
    resetAudio: assign(() => defaultContext),
    setStreamBufferReady: assign({ streamBufferReady: true }),
    clearStreamBufferReady: assign({ streamBufferReady: false }),
    setPlayOnReady: assign({ playOnReady: true }),
    clearPlayOnReady: assign({ playOnReady: false }),
    setPreviewDuck: assign(({ context }) => ({
      duckSources: { ...context.duckSources, preview: PREVIEW_DUCK_GAIN },
    })),
    clearPreviewDuck: assign(({ context }) => {
      const { preview: _removed, ...rest } = context.duckSources
      return { duckSources: rest }
    }),
    setDuckSource: assign(({ context, event }) => {
      if (event.type !== "SET_DUCK") return {}
      const gain =
        event.gain ?? (event.source === "sfx" ? SFX_DUCK_GAIN : PREVIEW_DUCK_GAIN)
      return {
        duckSources: { ...context.duckSources, [event.source]: gain },
      }
    }),
    clearDuckSource: assign(({ context, event }) => {
      if (event.type !== "CLEAR_DUCK") return {}
      const { [event.source]: _removed, ...rest } = context.duckSources
      return { duckSources: rest }
    }),
  },
  guards: {
    shouldAutoPlayFromReady: ({ context }) => context.playOnReady,
    shouldAutoPlayFromReadyWithBuffer: ({ context }) =>
      context.playOnReady && context.streamBufferReady,
    volumeAboveZero: ({ event }) => {
      if (event.type === "CHANGE_VOLUME") {
        return parseFloat(String(event.volume)) > 0
      }
      return false
    },
    volumeIsZero: ({ event }) => {
      if (event.type === "CHANGE_VOLUME") {
        return parseFloat(String(event.volume)) === 0
      }
      return false
    },
    hasTrack: ({ event }) => {
      if ("data" in event && "streamHealthStatus" in event.data && event.data.streamHealthStatus === "online") {
        return true
      }
      if ("data" in event && "meta" in event.data) {
        return !isEmpty(event.data.meta) && !isNil(event.data.meta.nowPlaying)
      }
      return false
    },
    eventHasTrack: ({ event }) => {
      return (
        event.type === "TRACK_CHANGED" &&
        !isEmpty(event.data.meta) &&
        !isNil(event.data.meta.nowPlaying)
      )
    },
    statusIsOnline: ({ event }) => {
      return event.type === "MEDIA_SOURCE_STATUS_CHANGED" && event.data.status === "online"
    },
    isCurrentTrack: ({ context, event }) => {
      return (
        event.type === "PLAYLIST_TRACK_UPDATED" &&
        !!context.meta?.nowPlaying &&
        context.meta.nowPlaying.mediaSource.trackId === event.data.track.mediaSource.trackId
      )
    },
    isStreamBufferReady: ({ context }) => context.streamBufferReady,
  },
}).createMachine({
  id: "audio",
  initial: "idle",
  context: defaultContext,
  states: {
    // Idle state - not subscribed to socket events
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    // Active state - subscribed to socket events
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["resetAudio"],
        },
        START_PREVIEW: {
          actions: ["setPreviewDuck"],
        },
        END_PREVIEW: {
          actions: ["clearPreviewDuck"],
        },
        SET_DUCK: {
          actions: ["setDuckSource"],
        },
        CLEAR_DUCK: {
          actions: ["clearDuckSource"],
        },
        ROOM_SETTINGS_UPDATED: {
          actions: ["clearDisabledPluginDataFromNowPlaying"],
        },
      },
      initial: "offline",
      states: {
        online: {
          type: "parallel",
          on: {
            INIT: {
              actions: ["setMeta", "setStatusFromMeta"],
            },
            OFFLINE: "offline",
            STREAM_HEALTH_CHANGED: {
              actions: ["applyStreamHealth"],
            },
            TRACK_CHANGED: {
              actions: ["setMeta"],
            },
            MEDIA_SOURCE_STATUS_CHANGED: {
              actions: ["setMediaSourceStatus"],
            },
            PLAYLIST_TRACK_UPDATED: {
              actions: ["updateNowPlaying"],
              guard: "isCurrentTrack",
            },
          },
          states: {
            progress: {
              initial: "stopped",
              states: {
                playing: {
                  initial: "loading",
                  states: {
                    loading: {
                      on: {
                        LOADED: "loaded",
                        PLAY: "loaded",
                      },
                    },
                    loaded: {},
                  },
                  on: {
                    STOP: {
                      target: "stopped",
                      actions: [
                        "stopListening",
                        "participate",
                        "clearStreamBufferReady",
                        "clearPlayOnReady",
                      ],
                    },
                    TOGGLE: {
                      target: "stopped",
                      actions: [
                        "stopListening",
                        "participate",
                        "clearStreamBufferReady",
                        "clearPlayOnReady",
                      ],
                    },
                    TRACK_CHANGED: {
                      actions: ["setMeta"],
                    },
                    MEDIA_SOURCE_STATUS_CHANGED: [
                      {
                        target: "playing.loaded",
                        actions: ["setMediaSourceStatus"],
                        guard: "statusIsOnline",
                      },
                      {
                        target: "#audio.active.offline",
                        actions: ["setMediaSourceStatus", "participate", "stopListening"],
                      },
                    ],
                  },
                },
                stopped: {
                  always: [
                    {
                      target: "playing.loaded",
                      guard: "shouldAutoPlayFromReadyWithBuffer",
                      actions: ["listen", "startListening", "clearPlayOnReady"],
                    },
                    {
                      target: "playing",
                      guard: "shouldAutoPlayFromReady",
                      actions: ["listen", "startListening", "clearPlayOnReady"],
                    },
                  ],
                  on: {
                    // Idempotent cleanup when swapping transport or unmounting a player while
                    // already stopped (e.g. WebRTC signaled LOADED but user never pressed play).
                    STOP: {
                      actions: ["clearStreamBufferReady", "clearPlayOnReady"],
                    },
                    LOADED: {
                      actions: ["setStreamBufferReady"],
                    },
                    PLAY: {
                      actions: ["setStreamBufferReady"],
                    },
                    TOGGLE: [
                      {
                        target: "playing.loaded",
                        guard: "isStreamBufferReady",
                        actions: ["listen", "startListening", "clearPlayOnReady"],
                      },
                      {
                        target: "playing",
                        actions: ["listen", "startListening", "clearPlayOnReady"],
                      },
                    ],
                    TRACK_CHANGED: {
                      actions: ["setMeta"],
                    },
                    MEDIA_SOURCE_STATUS_CHANGED: [
                      {
                        target: "stopped",
                        actions: ["setMediaSourceStatus"],
                        guard: "statusIsOnline",
                      },
                      { target: "#audio.active.offline", actions: ["setMediaSourceStatus"] },
                    ],
                  },
                },
              },
            },
            volume: {
              initial: "unmuted",
              states: {
                muted: {
                  on: {
                    TOGGLE_MUTE: "unmuted",
                    CHANGE_VOLUME: [
                      {
                        actions: ["setVolume"],
                        target: "unmuted",
                        guard: "volumeAboveZero",
                      },
                      {
                        actions: ["setVolume"],
                      },
                    ],
                  },
                },
                unmuted: {
                  on: {
                    TOGGLE_MUTE: "muted",
                    CHANGE_VOLUME: [
                      {
                        actions: ["setVolume"],
                        target: "muted",
                        guard: "volumeIsZero",
                      },
                      {
                        actions: ["setVolume"],
                      },
                    ],
                  },
                },
              },
            },
          },
        },
        offline: {
          entry: ["clearStreamBufferReady"],
          on: {
            TOGGLE: {
              actions: ["setPlayOnReady"],
            },
            STREAM_HEALTH_CHANGED: {
              actions: ["applyStreamHealth"],
            },
            ONLINE: "online",
            INIT: [
              { target: "online", actions: ["setMeta", "setStatusFromMeta"], guard: "hasTrack" },
              { target: "offline", actions: ["setMeta", "setStatusFromMeta"] },
            ],
            TRACK_CHANGED: [
              // If we receive track data while offline, go online
              { target: "online", actions: ["setMeta", "setStatusOnline"], guard: "eventHasTrack" },
              { actions: ["setMeta"] },
            ],
            MEDIA_SOURCE_STATUS_CHANGED: [
              { target: "online", actions: ["setMediaSourceStatus"], guard: "statusIsOnline" },
              { target: "offline", actions: ["setMediaSourceStatus"] },
            ],
          },
        },
        willRetry: {
          on: {
            STREAM_HEALTH_CHANGED: {
              actions: ["applyStreamHealth"],
            },
          },
          after: { 2000: "online" },
        },
      },
    },
  },
})

export const allRoomsFetchMachine = setup({
  types: {
    context: {} as AllRoomsFetchContext,
    events: {} as AllRoomsFetchEvent,
  },
  actors: {
    fetchAllRooms: fetchAllRoomsLogic,
  },
  actions: {
    setError: assign(({ context, event }) => {
      if (event.type !== "xstate.error.actor.fetchAllRooms") return context
      return {
        error: event.error,
      }
    }),
    setRooms: assign(({ context, event }) => {
      if (event.type !== "xstate.done.actor.fetchAllRooms") {
        return context
      }
      return {
        rooms: event.output.rooms,
      }
    }),
  },
}).createMachine({
  id: "allRoomsFetch",
  initial: "initial",
  context: {
    rooms: [],
    error: null,
  },
  on: {
    FETCH: {
      target: ".loading",
    },
  },
  states: {
    initial: {},
    loading: {
      invoke: {
        id: "fetchAllRooms",
        src: "fetchAllRooms",
        onDone: {
          target: "success",
          actions: ["setRooms"],
        },
        onError: {
          target: "error",
          actions: ["setError"],
        },
      },
    },
    success: {},
    error: {},
  },
})

export const allReactionsMachine = setup({
  types: {
    context: {} as AllReactionsContext,
    events: {} as AllReactionsEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `reactions-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event),
        eventTypes: ["REACTION_ADDED", "REACTION_REMOVED", "INIT"],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    setData: assign({
      reactions: ({ event }) => {
        if (event.type === "INIT" && event.data.reactions) {
          return event.data.reactions
        }
        return emptyStore()
      },
    }),
    applyAdded: assign({
      reactions: ({ context, event }) => {
        if (event.type !== "REACTION_ADDED") return context.reactions
        return patchAdd(context.reactions, event.data)
      },
    }),
    applyRemoved: assign({
      reactions: ({ context, event }) => {
        if (event.type !== "REACTION_REMOVED") return context.reactions
        return patchRemove(context.reactions, event.data)
      },
    }),
    resetReactions: assign({
      reactions: () => emptyStore(),
      subscriptionId: () => null,
    }),
  },
}).createMachine({
  id: "allReactions",
  initial: "idle",
  context: {
    reactions: emptyStore(),
    subscriptionId: null,
  },
  states: {
    idle: {
      on: {
        ACTIVATE: "active",
      },
    },
    active: {
      entry: ["subscribe"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["resetReactions"],
        },
        REACTION_ADDED: {
          actions: ["applyAdded"],
        },
        REACTION_REMOVED: {
          actions: ["applyRemoved"],
        },
        INIT: {
          actions: ["setData"],
        },
      },
    },
  },
})

export const adminListenerStateMachine = setup({
  types: {
    context: {} as AdminListenerStateContext,
    events: {} as AdminListenerEvent,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `adminListener-${self.id}-${++subscriptionCounter}`
      subscribeById(id, {
        send: (event) => self.send(event as AdminListenerEvent),
        eventTypes: [
          "ALL_LISTENER_GAME_STATES",
          "ERROR_OCCURRED",
          "GAME_STATE_CHANGED",
          "INVENTORY_ITEM_ACQUIRED",
          "INVENTORY_ITEM_REMOVED",
          "INVENTORY_ITEM_USED",
          "INVENTORY_ITEM_TRANSFERRED",
          "USER_JOINED",
          "USER_LEFT",
          "GAME_SESSION_STARTED",
          "GAME_SESSION_ENDED",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) {
        unsubscribeById(context.subscriptionId)
      }
    },
    clearSubscriptionId: assign({
      subscriptionId: () => null,
    }),
    requestData: () => {
      emitToSocket("GET_ALL_LISTENER_GAME_STATES", {})
    },
    setPayload: assign(({ event }) => {
      if (event.type !== "ALL_LISTENER_GAME_STATES") return {}
      const d = event.data
      return {
        payload: {
          session: d.session,
          listeners: d.listeners ?? [],
          itemDefinitions: d.itemDefinitions ?? [],
        },
        error: null,
      }
    }),
    reset: assign({
      subscriptionId: () => null,
      payload: () => null,
      error: () => null,
    }),
    setError: assign(({ event }) => {
      if (event.type !== "ERROR_OCCURRED") return {}
      return { error: event.data?.message ?? "Could not load listener stats." }
    }),
  },
}).createMachine({
  id: "adminListenerState",
  initial: "idle",
  context: {
    subscriptionId: null,
    payload: null,
    error: null,
  },
  states: {
    idle: {
      on: {
        ACTIVATE: "loading",
      },
    },
    loading: {
      entry: ["subscribe", "requestData"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["unsubscribe", "reset"],
        },
        ALL_LISTENER_GAME_STATES: {
          target: "ready",
          actions: ["setPayload"],
        },
        ERROR_OCCURRED: {
          target: "error",
          actions: ["setError"],
        },
      },
    },
    ready: {
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["unsubscribe", "reset"],
        },
        REFRESH: "refreshing",
        ALL_LISTENER_GAME_STATES: {
          actions: ["setPayload"],
        },
        GAME_STATE_CHANGED: {
          actions: ["requestData"],
        },
        INVENTORY_ITEM_ACQUIRED: {
          actions: ["requestData"],
        },
        INVENTORY_ITEM_REMOVED: {
          actions: ["requestData"],
        },
        INVENTORY_ITEM_USED: {
          actions: ["requestData"],
        },
        INVENTORY_ITEM_TRANSFERRED: {
          actions: ["requestData"],
        },
        USER_JOINED: {
          actions: ["requestData"],
        },
        USER_LEFT: {
          actions: ["requestData"],
        },
        GAME_SESSION_STARTED: {
          actions: ["requestData"],
        },
        GAME_SESSION_ENDED: {
          actions: ["requestData"],
        },
      },
    },
    refreshing: {
      entry: ["requestData"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["unsubscribe", "reset"],
        },
        ALL_LISTENER_GAME_STATES: {
          target: "ready",
          actions: ["setPayload"],
        },
        ERROR_OCCURRED: {
          target: "error",
          actions: ["setError"],
        },
      },
    },
    error: {
      entry: ["unsubscribe", "clearSubscriptionId"],
      on: {
        DEACTIVATE: {
          target: "idle",
          actions: ["unsubscribe", "reset"],
        },
        REFRESH: "loading",
      },
    },
  },
})

const giftInboxMachine = setup({
  types: {
    context: {} as Context,
    events: {} as Event,
  },
  actions: {
    subscribe: assign(({ self }) => {
      const id = `giftInbox-${self.id}-${++subCounter}`
      subscribeById(id, {
        send: (event) => {
          if (self.getSnapshot().status !== "active") return
          self.send(event as Event)
        },
        eventTypes: [
          "GIFT_OFFERED",
          "GIFT_COMPLETED",
          "GIFT_DECLINED",
          "GIFT_CANCELLED",
          "TRADE_INVITE_OFFERED",
          "TRADE_INVITE_EXPIRED",
          "TRADE_INVITE_DECLINED",
          "TRADE_INVITE_CANCELLED",
          "TRADE_INVITE_ACCEPTED",
          "TRADE_UPDATED",
          "TRADE_CANCELLED",
          "TRADE_COMPLETED",
          "USER_GAME_STATE",
        ],
      })
      return { subscriptionId: id }
    }),
    unsubscribe: ({ context }) => {
      if (context.subscriptionId) unsubscribeById(context.subscriptionId)
    },
    seedWatchedTrades: assign(() => {
      const me = getCurrentUser()?.userId
      const trade = getUserGameStatePayload()?.activeTrade
      if (!me || !trade) return { watchedTrades: {} }
      const snapshot = watchSnapshotForUser(trade, me)
      if (!snapshot) return { watchedTrades: {} }
      return { watchedTrades: { [trade.tradeId]: snapshot } }
    }),
    reset: assign({
      subscriptionId: () => null,
      watchedTrades: () => ({}),
    }),
    notifyGiftOffered: ({ event }) => {
      if (event.type !== "GIFT_OFFERED") return
      raiseGiftOffered(event.data?.offer)
    },
    notifyGiftDeclined: ({ event }) => {
      if (event.type !== "GIFT_DECLINED") return
      toastGiftDeclined(event.data?.offer)
    },
    notifyTradeInvite: ({ event }) => {
      if (event.type !== "TRADE_INVITE_OFFERED") return
      applyTradeInviteOffered(event.data?.invite)
    },
    notifyTradeInviteExpired: ({ event }) => {
      if (event.type !== "TRADE_INVITE_EXPIRED") return
      toastTradeInviteExpired(event.data?.invite)
    },
    dismissTradeInviteToastIfMine: ({ event }) => {
      if (event.type !== "TRADE_INVITE_DECLINED" && event.type !== "TRADE_INVITE_CANCELLED") {
        return
      }
      dismissInviteToastIfRecipient(event.data?.invite)
    },
    notifyTradeInviteDeclined: ({ event }) => {
      if (event.type !== "TRADE_INVITE_DECLINED") return
      toastTradeInviteDeclined(event.data?.invite)
    },
    notifyTradeInviteAccepted: assign(({ context, event }) => {
      if (event.type !== "TRADE_INVITE_ACCEPTED") return {}
      return applyTradeInviteAccepted({
        watchedTrades: context.watchedTrades,
        trade: event.data?.trade,
      })
    }),
    notifyTradeUpdated: assign(({ context, event }) => {
      if (event.type !== "TRADE_UPDATED") return {}
      return applyTradeUpdated({
        watchedTrades: context.watchedTrades,
        trade: event.data?.trade,
      })
    }),
    notifyTradeCancelled: assign(({ context, event }) => {
      if (event.type !== "TRADE_CANCELLED") return {}
      return applyTradeCancelled({
        watchedTrades: context.watchedTrades,
        trade: event.data?.trade,
        reason: event.data?.reason,
        cancelledByUserId: event.data?.cancelledByUserId,
      })
    }),
    notifyTradeCompleted: assign(({ context, event }) => {
      if (event.type !== "TRADE_COMPLETED") return {}
      return applyTradeCompleted({
        watchedTrades: context.watchedTrades,
        trade: event.data?.trade,
      })
    }),
    reconcileFromGameState: ({ event }) => {
      if (event.type !== "USER_GAME_STATE") return
      reconcileGiftsFromPayload(event.data)
      reconcileTradeInvitesFromPayload(event.data)
    },
  },
}).createMachine({
  id: "giftInbox",
  initial: "idle",
  context: {
    subscriptionId: null,
    watchedTrades: {},
  },
  states: {
    idle: {
      on: { ACTIVATE: "active" },
    },
    active: {
      entry: ["subscribe", "seedWatchedTrades"],
      exit: ["unsubscribe"],
      on: {
        DEACTIVATE: { target: "idle", actions: ["reset"] },
        RESET: { actions: ["reset"] },
        GIFT_OFFERED: { actions: ["notifyGiftOffered"] },
        GIFT_DECLINED: { actions: ["notifyGiftDeclined"] },
        TRADE_INVITE_OFFERED: { actions: ["notifyTradeInvite"] },
        TRADE_INVITE_EXPIRED: { actions: ["notifyTradeInviteExpired"] },
        TRADE_INVITE_DECLINED: {
          actions: ["dismissTradeInviteToastIfMine", "notifyTradeInviteDeclined"],
        },
        TRADE_INVITE_CANCELLED: { actions: ["dismissTradeInviteToastIfMine"] },
        TRADE_INVITE_ACCEPTED: { actions: ["notifyTradeInviteAccepted"] },
        TRADE_UPDATED: { actions: ["notifyTradeUpdated"] },
        TRADE_CANCELLED: { actions: ["notifyTradeCancelled"] },
        TRADE_COMPLETED: { actions: ["notifyTradeCompleted"] },
        USER_GAME_STATE: { actions: ["reconcileFromGameState"] },
      },
    },
  },
})

export const createTimerMachine = ({ duration, start }: CreateTimerMachineProps) => {
  const tickerLogic = fromCallback<ToggleEvent, { interval: number }>(({ sendBack, input }) => {
    const interval = setInterval(() => {
      sendBack({ type: "TICK" })
    }, input.interval * 1000)
    return () => {
      clearInterval(interval)
    }
  })

  return setup({
    types: {
      context: {} as ToggleContext,
      events: {} as ToggleEvent,
    },
    actors: {
      ticker: tickerLogic,
    },
    actions: {
      setElapsed: assign({
        elapsed: ({ context }) => Date.now() - context.start,
      }),
      setRemaining: assign({
        remaining: ({ context }) => Math.max(0, context.start + context.duration - Date.now()),
      }),
    },
    guards: {
      timerExpired: ({ context }) => Math.ceil(context.remaining / 1000) <= 0,
    },
  }).createMachine({
    id: "timer",
    initial: "idle",
    context: {
      duration,
      elapsed: 0,
      remaining: duration,
      interval: 1,
      start: start || Date.now(),
    },

    states: {
      idle: {
        entry: ["setElapsed", "setRemaining"],
        always: [{ target: "running" }],
      },
      running: {
        invoke: [
          {
            id: "ticker",
            src: "ticker",
            input: ({ context }) => ({ interval: context.interval }),
          },
        ],
        initial: "normal",
        states: {
          normal: {
            always: [{ target: "#timer.expired", guard: "timerExpired" }],
            on: {
              TICK: {
                actions: ["setElapsed", "setRemaining"],
              },
            },
          },
        },
        on: {
          TOGGLE: "paused",
        },
      },
      expired: {},
      paused: {
        on: { TOGGLE: "running" },
      },
    },
    on: {
      RESET: {
        target: ".idle",
      },
    },
  })
}

export const createRoomFormMachine = setup({
  types: {
    context: {} as RoomSetup,
    events: {} as Event,
  },
  actions: {
    assignType: assign(({ context, event }) => {
      if (event.type !== "SELECT_TYPE") return {}
      const nextType = event.data?.type ?? context.type
      if (nextType === "live") {
        return {
          type: "live" as const,
          radioListenUrl: DEFAULT_LIVE_WHEP_URL,
          radioMetaUrl: DEFAULT_LIVE_HLS_URL,
          playbackControllerId: "spotify" as const,
        }
      }
      if (nextType === "jukebox") {
        return {
          type: "jukebox" as const,
          radioListenUrl: undefined,
          radioMetaUrl: undefined,
          radioProtocol: undefined,
          playbackControllerId: undefined,
        }
      }
      if (nextType === "radio") {
        return {
          type: "radio" as const,
          radioMetaUrl: "http://live.rcast.net:8678",
          radioListenUrl: "https://stream1.rcast.net/66341",
          radioProtocol: "shoutcastv2",
          playbackControllerId: "spotify" as const,
        }
      }
      return { type: nextType }
    }),
    assignSettings: assign(({ context, event }) => {
      if (event.type === "SET_SETTINGS") {
        return {
          ...context,
          ...event.data?.settings,
        }
      }
      return context
    }),
    storeRoomSettings: ({ context }) => {
      sessionStorage.setItem("createRoomTitle", context.title)
      sessionStorage.setItem("createRoomType", context.type)
      sessionStorage.setItem("createRoomDeputizeOnJoin", context.deputizeOnJoin.toString())
      sessionStorage.setItem("createRoomPublic", (context.public ?? true).toString())
      if (context.showId) {
        sessionStorage.setItem("createRoomShowId", context.showId)
      } else {
        sessionStorage.removeItem("createRoomShowId")
      }
      if (context.type === "radio" || context.type === "live") {
        sessionStorage.setItem(
          "createRoomPlaybackControllerId",
          context.playbackControllerId ?? "spotify",
        )
      } else {
        sessionStorage.removeItem("createRoomPlaybackControllerId")
      }
      if (context.type === "radio") {
        sessionStorage.setItem("createRoomRadioProtocol", context.radioProtocol ?? "shoutcastv2")
        if (context.radioMetaUrl) {
          sessionStorage.setItem("createRoomradioMetaUrl", context.radioMetaUrl)
        }
        if (context.radioListenUrl) {
          sessionStorage.setItem("createRoomRadioListenUrl", context.radioListenUrl)
        }
        sessionStorage.setItem(
          "createRoomLiveIngestEnabled",
          String(context.liveIngestEnabled ?? false),
        )
        if (context.liveWhepUrl) {
          sessionStorage.setItem("createRoomLiveWhepUrl", context.liveWhepUrl)
        } else {
          sessionStorage.removeItem("createRoomLiveWhepUrl")
        }
        if (context.liveHlsUrl) {
          sessionStorage.setItem("createRoomLiveHlsUrl", context.liveHlsUrl)
        } else {
          sessionStorage.removeItem("createRoomLiveHlsUrl")
        }
      }
      if (context.type === "live") {
        if (context.radioListenUrl) {
          sessionStorage.setItem("createRoomRadioListenUrl", context.radioListenUrl)
        }
        if (context.radioMetaUrl) {
          sessionStorage.setItem("createRoomradioMetaUrl", context.radioMetaUrl)
        }
      }
    },
    navigateToCreatePage: ({ event }) => {
      if (event.type === "NEXT") {
        window.location.href = "/rooms/create"
      }
    },
  },
}).createMachine({
  id: "createRoomForm",
  initial: "selectType",
  context: {
    type: "jukebox",
    title: "My Room",
    showId: undefined as string | undefined,
    radioMetaUrl: "http://live.rcast.net:8678",
    radioListenUrl: "https://stream1.rcast.net/66341",
    radioProtocol: "shoutcastv2",
    liveIngestEnabled: false,
    liveWhepUrl: undefined as string | undefined,
    liveHlsUrl: undefined as string | undefined,
    deputizeOnJoin: true,
    public: true,
  },
  states: {
    selectType: {
      on: {
        SELECT_TYPE: {
          actions: ["assignType"],
        },
        NEXT: "settings",
      },
    },
    settings: {
      on: {
        BACK: "selectType",
        NEXT: {
          actions: ["storeRoomSettings", "navigateToCreatePage"],
          target: "creating",
        },
        SET_SETTINGS: {
          actions: ["assignSettings"],
        },
      },
    },
    creating: {
      type: "final",
    },
  },
})

export const configImportMachine = setup({
  types: {
    context: {} as ConfigImportMachineContext,
    events: {} as ConfigImportMachineEvent,
  },
  actors: {
    applyImport: applyImportLogic,
  },
  guards: {
    needsReplaceConfirm: ({ event }) =>
      event.type === "SUBMIT" && event.mode === "replace" && event.needsReplaceConfirm,
  },
  actions: {
    resetForm: assign({
      rawText: "",
      confirmReplace: false,
      pendingMode: null,
      pendingRun: null,
      lastResult: null,
      lastError: null,
    }),
    setText: assign(({ event }) => {
      if (event.type !== "SET_TEXT") return {}
      return { rawText: event.rawText, confirmReplace: false }
    }),
    armReplaceConfirm: assign(({ event }) => {
      if (event.type !== "SUBMIT") return {}
      return {
        confirmReplace: true,
        pendingMode: event.mode,
        pendingRun: event.run,
      }
    }),
    stageSubmit: assign(({ event }) => {
      if (event.type !== "SUBMIT") return {}
      return {
        confirmReplace: false,
        pendingMode: event.mode,
        pendingRun: event.run,
        lastError: null,
      }
    }),
    /** Capture invoke output — id-based done event types are not stable across XState versions. */
    captureResult: assign(({ event }) => {
      if (!("output" in event)) return {}
      return { lastResult: (event as { output: ConfigImportApplyResult }).output }
    }),
    captureError: assign(({ event }) => {
      if (!("error" in event)) return {}
      return { lastError: errorMessage((event as { error: unknown }).error) }
    }),
    /**
     * Host provides via `.provide({ actions: { reportSuccess } })`.
     * Reads `context.lastResult` (set by `captureResult`).
     */
    reportSuccess: () => {},
    /**
     * Host provides via `.provide({ actions: { reportError } })`.
     * Reads `context.lastError` (set by `captureError`).
     */
    reportError: () => {},
  },
}).createMachine({
  id: "configImport",
  initial: "closed",
  context: {
    rawText: "",
    confirmReplace: false,
    pendingMode: null,
    pendingRun: null,
    lastResult: null,
    lastError: null,
  },
  states: {
    closed: {
      on: {
        OPEN: { target: "open", actions: "resetForm" },
      },
    },
    open: {
      on: {
        CLOSE: { target: "closed", actions: "resetForm" },
        SET_TEXT: { actions: "setText" },
        SUBMIT: [
          { guard: "needsReplaceConfirm", actions: "armReplaceConfirm" },
          { target: "submitting", actions: "stageSubmit" },
        ],
      },
    },
    submitting: {
      invoke: {
        id: "applyImport",
        src: "applyImport",
        input: ({ context }) => ({
          run: context.pendingRun ?? (async () => ({ success: false, message: "Nothing to run" })),
        }),
        onDone: {
          target: "closed",
          // capture → report (reads context) → reset
          actions: ["captureResult", "reportSuccess", "resetForm"],
        },
        onError: {
          target: "open",
          actions: [
            "captureError",
            "reportError",
            assign({ pendingMode: null, pendingRun: null }),
          ],
        },
      },
    },
  },
})

